window.__LEX={"G1300":"<h1>diateleo</h1>\n<p>Strong n° 1300 <i>Prononciation [dee-at-el-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>amener complètement à une fin, accomplir, passer le temps à</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·τελέω-ῶ</b> <span>(<i>f</i>. -τελῶ, <i>non</i> -τελέσω, <i>etc</i>.)</span><br><b>   I <i>tr.</i></b> achever complètement, accomplir entièrement : τὰ δέκα ἔτη, XÉN. <i>Cyr. 1, 5, 4,</i> les dix années (qu’on doit passer dans une classe de citoyens) ; δ. χάριν, EUR. <i>Her. 434,</i> réaliser un bienfait ; δ. τὸν βίον, ATT. passer sa vie ; <i>avec un part</i>. τὸν λοιπὸν βίον καθεύδοντες διατελοῖτε ἄν, PLAT. <i>Ap. 31</i> a, vous passeriez le reste de votre vie à dormir ;<br><b>   II</b> <i>abs</i>. διατελεῖν :<br><b>      1</b> passer sa vie : μετ' ἀλλήλων, PLAT. <i>Conv. 192</i> c, les uns avec les autres ; δ. ἀλύπως, PLAT. <i>Phil. 43</i> d, passer sa vie sans chagrin ; ἐν ὕπνῳ, ARSTT. <i>G.A. 5, 1, 15,</i> passer sa vie à dormir ; ἐν τῇ θαλάττῃ, ARSTT. <i>Probl. 23, 14,</i> passer sa vie sur mer ;<br><b>      2</b> <i>en génér</i>. continuer d’être, continuer, persévérer : διατέλει ὥσπερ ἤρξω, PLAT. <i>Gorg. 494</i> c, continue comme tu as commencé ; <i>avec un part</i>. διετέλει χρώμενος τῇ κορύνῃ, PLUT. <i>Thes. 8,</i> il continua de se servir de la massue ; <i>avec un adj</i>. ἀνυπόδητος καὶ ἀχίτων διατελεῖς, XÉN. <i>Mem. 1, 6, 2,</i> tu restes constamment pieds nus et sans tunique ; ἀσφαλέστατος ἂν διατελοίη, THC. <i>1, 34,</i> il assurerait tout à fait et d’une manière durable sa propre tranquillité ; <i>en parl. de choses,</i> continuer, PLAT. <i>Rsp. 395</i> d.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατελεω - διατελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1301":"<h1>diatereo</h1>\n<p>Strong n° 1301 <i>Prononciation [dee-at-ay-reh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>garder continuellement ou soigneusement, conserver avec soin, se garder fidèlement de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·τηρέω-ῶ :<br>   I</b> conserver avec soin <i>ou</i> jusqu’au bout, <i>d’où :</i><br><b>      1</b> maintenir fidèlement, <i>acc</i>. (la liberté, DÉM. <i>290, 10 ;</i> les lois, ESCHN. <i>54, 28, etc.) ; avec un adj. en relat. avec le rég</i>. δ. βοῦς ἐννέα ἔτη ἀνοχεύτους, ARSTT. <i>H.A. 8, 7, 3,</i> conserver des génisses sans les faire saillir pendant neuf ans ; τι ἀϐλαϐὲς δ. POL. <i>7, 8, 7,</i> conserver qqe ch. intact ;<br><b>      2</b> continuer avec persévérance, persister dans : τὸν πόλεμον, PLUT. <i>Dio. 33,</i> poursuivre la guerre ;<br><b>   II</b> observer avec soin, surveiller : τι, PLAT. <i>Leg. 836</i> c ; ARSTT. <i>H.A. 9, 7, 3,</i> qqe ch. ; <i>avec</i> μή : δ. μή τι πάθωσι, DÉM. <i>115, 26,</i> veiller avec soin à ce qu’ils n’éprouvent aucun mal ; <i>avec double rég</i>. δ. ἑαυτὸν ἔκ τινος, NT. <i>Ap. 15, 29,</i> se garder avec soin de qqe ch.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατηρεω - διατηρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1302":"<h1>diati</h1>\n<p>Strong n° 1302 <i>Prononciation [dee-at-ee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>à travers, par, avec, parce que, pourquoi</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατι - διατί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 25 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (3)</li>\n<li>Luc (5)</li>\n<li>Jean (5)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1303":"<h1>diatithemai</h1>\n<p>Strong n° 1303 <i>Prononciation [dee-at-ith'-em-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>arranger, disposer, faire ses affaires\n<ol type=\"a\">\n<li>de quelque chose qui nous appartient</li>\n<li>disposer par la volonté, faire un testament</li>\n</ol>\n</li>\n<li>faire un pacte, signer une alliance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·τίθημι</b> <span>(<i>f</i>. διαθήσω, <i>ao.2</i> διέθην, <i>etc</i>.)</span><br><b>      1</b> disposer çà et là, distribuer, répartir : δ. τὸ μὲν ἐπὶ δεξιά, τὸ δ' ἐν ἀριστερά, HDT. <i>7, 39,</i> placer une moitié (du corps d’un enfant) à droite (d’une route), l’autre moitié à gauche, δ. οἶνον εἰς ὀστράκια, ARSTT. <i>H.A. 8, 4, 3,</i> distribuer le vin dans des coquilles ;<br><b>      2</b> <i>p. suite,</i> disposer, organiser, régler, <i>en gén</i>. θεοὶ διέθεσαν τὰ ὄντα, XÉN. <i>Mem. 2, 1, 27,</i> les dieux ont disposé <i>ou</i> réglé ce qui est, <i>càd</i>. toute chose ; δ. ἀγῶνας, XÉN. <i>Hell. 6, 4, 30,</i> instituer des concours ; <i>particul</i>. disposer en détail, <i>d’où</i> mettre en ordre (un récit, une description, <i>etc.), d’où</i> exposer, raconter, décrire, STR. <i>9 ; en parl. de rhapsodes, d’orateurs,</i> réciter, déclamer, <i>etc</i>. PLAT. <i>Charm. 162</i> d, <i>Leg. 658</i> d ;<br><b>      3</b> traiter bien <i>ou</i> mal : δ. τὰ τοῦ πολέμου κράτιστα, THC. <i>6, 15,</i> mener la guerre pour le mieux ; δ. πρᾶγμα κακῶς, DÉM. <i>369, 13,</i> mal conduire une affaire ; <i>avec un rég. de pers</i>. δ. τινὰ ἀνηκέστως, HDT. <i>3, 155,</i> traiter qqn avec barbarie ; ἀπόρως διατεθείς, LYS. <i>151, 24,</i> réduit au dénûment ; ἀθλίως διατίθεσθαι, PLAT. <i>Criti. 121</i> b, être dans une situation malheureuse ;<br><b>      4</b> disposer bien <i>ou</i> mal, mettre dans telle <i>ou</i> telle disposition d’esprit <i>ou</i> de corps : δ. τινὰ ἀπίστως πρός τινα, DÉM. <i>463, 19,</i> disposer qqn à la défiance pour un autre ; δ. τὸν ἀκροατήν πως, ARSTT. <i>Rhet. 1, 2, 3,</i> mettre l’auditeur dans qqe disposition d’esprit : οὕτω δ. τινὰ ὥστε, ISOCR. <i>98</i> a, mettre qqn dans une telle disposition d’esprit <i>ou</i> de caractère que, <i>etc. ; au pass</i>. être disposé de telle ou telle façon, être dans telle ou telle disposition d’esprit : πρός τινα, PLAT. <i>Theæt. 151</i> c, à l’égard de qqn ; <i>avec un adv</i>. δυσκόλως διατίθεσθαι πρός τινα, ISOCR. <i>161</i> e, avoir pour qqn des dispositions malveillantes ; <i>avec un acc. déterminat</i>. δ. τὸν εἰρημένον τρόπον, ARSTT. <i>Pol. 5, 2, 4,</i> être disposé de la façon qu’on a dite (<i>en ce sens on emploie souv</i>. διάκειμαι, <i>v. ce mot) ; t. de gr. au pass</i>. être employé passivement, être passif, <i>en parl. de verbes,</i> DYSC. <i>Synt. 12, 13 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. διαθήσομαι, <i>ao.2</i> διεθέμην, <i>etc</i>.)</span> disposer soi-même <i>ou</i> pour soi, <i>d’où :</i><br><b>      1</b> exposer en détail : λόγους, POL. <i>3, 108, 2 ;</i> DS. <i>12, 17,</i> débiter des discours ; πολὺν ἔπαινόν τινος, DH. <i>3, 17,</i> faire tout au long un grand éloge de qqn ;<br><b>      2</b> disposer, régler : νόμους, PLAT. <i>Leg. 834</i> a, rédiger des lois ; διαθήκην τινί, AR. <i>Av. 440, ou</i> πρός τινα, NT. <i>Ap. 3, 25,</i> régler une convention avec qqn ; ἔριν συμφερόντως, XÉN. <i>Mem. 2, 6, 23,</i> arranger un différend pour le bien commun des parties ; <i>en parl. d’affaires,</i> disposer (d’une propriété, d’un bien, <i>etc.), d’où</i> vendre <i>ou</i> échanger, XÉN. <i>An. 7, 3, 10 ;</i> PLAT. <i>Leg. 849</i> d, <i>etc. ;</i> δ. φόρτον, HDT. <i>1, 1 et 194,</i> mettre sa cargaison en vente ; δ. τι τριπλασίας τιμῆς, DÉM. <i>1048, 25,</i> vendre qqe ch. trois fois plus cher ; διατίθεσθαι τὴν θυγατέρα, XÉN. <i>Cyr. 5, 2, 7,</i> régler la situation de sa fille, <i>càd</i>. l’établir ; <i>particul</i>. disposer par testament : δ. διαθήκας, LYS. <i>155, 23,</i> régler ses dispositions par testament ; δ. τὰ ἑαυτοῦ, PLAT. <i>Leg. 922</i> e, <i>etc</i>. disposer de ses biens par testament ; δ. τὴν οὐσίαν τινί, IS. <i>63, 5,</i> céder par testament sa fortune à qqn ; ἀποθανεῖν μὴ διαθέμενον, ARSTT. <i>Pol. 2, 9, 15,</i> mourir intestat ; ὁ διαθέμενος, NT. <i>Hebr. 9, 16,</i> celui qui a testé.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατιθεμαι - διατίθημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n<li>Hébreux (4)</li>\n</ul>\n</td></tr>\n</table>","G1304":"<h1>diatribo</h1>\n<p>Strong n° 1304 <i>Prononciation [dee-at-ree'-bo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>séjourner</li>\n<li>porter au loin, consumer, user, consumer d'ou passer le temps</li>\n<li>passer le temps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·τρίϐω</b> <span>(<i>f</i>. διατρίψω, <i>ao.2 pass</i>. διετρίϐην, <i>pf</i>. διατέτριμμαι)</span><br><b>   I</b> frotter, user en frottant, <i>d’où :</i><br><b>      1</b> réduire en poudre : ῥίζαν, IL. <i>11, 847,</i> broyer une racine ;<br><b>      2</b> user par le frottement, <i>d’où fig</i>. consumer, perdre, détruire : χρήματα, THGN. <i>921,</i> gaspiller sa fortune ; κάκιστα διατριϐῆναι, HDT. <i>7, 120,</i> être broyé, <i>càd</i>. périr misérablement ;<br><b>   II</b> <i>particul</i>. passer le temps, <i>d’où :</i><br><b>      1</b> <i>avec idée de temps</i> remettre, différer : χόλον, IL. <i>4, 42,</i> user la colère (de qqn), en retarder <i>ou</i> en contenir l’explosion ; γάμον, OD. <i>20, 341,</i> retarder un mariage ; <i>avec deux acc</i>. τινὰ δ. γάμον, OD. <i>2, 204,</i> faire attendre à qqn, <i>càd</i>. remettre sans cesse un mariage ; <i>ou avec un gén</i>. μὴ δ. ὁδοῖο, OD. <i>2, 404,</i> ne pas perdre de temps à se mettre en route ; δ. χρόνον, HDT. <i>1, 24 ;</i> PLAT. <i>Phæd. 117</i> a, <i>etc</i>. employer du temps, passer du temps, <i>etc. ;</i> ἀφικόμενος εἰς Κόρινθον διέτριϐέ τινας ἡμέρας, XÉN. <i>Hell. 6, 5, 49,</i> arrivé à Corinthe, il y passa quelques jours ; δ. μετά τινος, PLAT. <i>Ap. 33</i> b, <i>Phæd. 59</i> d, passer le temps avec qqn, <i>càd</i>. s’entretenir avec qqn ; ἔν τινι, PLAT. <i>Ap. 29</i> c ; ISOCR. <i>149</i> e, <i>etc. ;</i> περί τι, PLAT. <i>Phæd. 90</i> b ; ESCHN. <i>69, 5 ;</i> PLUT. <i>M. 8</i> a ; πρός τινι, ARSTT. <i>Pol. 5, 8 ;</i> PLUT. <i>Marc. 21 ;</i> ἐπί τινι, ISOCR. <i>30</i> d ; DÉM. <i>22 ;</i> PLUT. <i>Sol. 23,</i> employer son temps à qqe ch., s’occuper de qqe ch. ; <i>avec un part</i>. XÉN. <i>Cyr. 1, 2, 18 ;</i> HDN <i>3, 10, 3 ; etc</i>. passer son temps à faire qqe ch. ; <i>abs. en mauv. part,</i> passer son temps, perdre son temps, HPC. <i>911</i> g ; AR. <i>Eq. 515, Vesp. 849 ;</i> XÉN. <i>Cyr. 3, 3, 25 ;</i> LUC. <i>V. auct. 26 ;</i><br><b>      2</b> <i>avec idée de lieu,</i> passer son temps qqe part, séjourner : ἐν ταῖς ὁδοῖς, XÉN. <i>Mem. 2, 1, 15,</i> sur les routes ; ἐν γυμνασίοις, AR. <i>Nub. 1002,</i> dans les gymnases ;<br><b><i>Moy</i>. διατρίϐομαι</b>, perdre son temps : μή τι διατριϐώμεθα πείρης, A. RH. <i>2, 883,</i> ne différons pas notre entreprise.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατριβω - διατρίβω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Actes (8)</li>\n</ul>\n</td></tr>\n</table>","G1305":"<h1>diatrophe</h1>\n<p>Strong n° 1305 <i>Prononciation [dee-at-rof-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>entretien, subsistance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διατροφή, ῆς (ἡ)</b> nourriture, subsistance, XÉN. <i>Vect. 4, 49 ;</i> MÉN. (STOB. <i>Fl. 61, 1</i>) ; DS. <i>19, 32 ;</i> NT. <i>1Tim. 6, 8</i>.<br><span><b>Étym</b>. διατρέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διατροφη - διατροφή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1306":"<h1>diaugazo</h1>\n<p>Strong n° 1306 <i>Prononciation [dee-ow-gad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>briller à travers, poindre, apparaître (aube), se lever en parlant du jour\n<ol type=\"a\">\n<li>de la lumière du jour venant à travers l'obscurité de la nuit</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·αυγάζω :<br>      1</b> briller à travers, <i>en parl. d’un éclair,</i> PLUT. <i>M. 893</i> e ;<br><b>      2</b> commencer à briller : ἡ ἡμέρα διαυγάζει, NT. <i>2Petr. 1, 19,</i> le jour commence à poindre ; ἅμα τῷ διαυγάζειν, POL. <i>3, 104, 5,</i> au point du jour.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-αυγαζω - διαυγάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1307":"<h1>diaphanes</h1>\n<p>Strong n° 1307 <i>Prononciation [dee-af-an-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>transparent, translucide</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διαφανής, ής, ές</b> <span>[φᾰ]</span><br><b>   I</b> (διά, en séparant) que l’on discerne, que l’on voit distinctement, distinct, PLAT. <i>Rsp. 544</i> d, <i>548</i> c ;<br><b>   II</b> (διά, à travers) :<br><b>      1</b> <i>propr. en parl. de liquides,</i> transparent, limpide, HPC. <i>211</i> e, <i>1252</i> c ; PLAT. <i>Phædr. 229</i> b ; <i>de verre,</i> AR. <i>Nub. 767 ; de couleurs,</i> ARSTT. <i>G.A. 5, 1, fin ;</i><br><b>      2</b> <i>fig. en parl. de paroles,</i> clair, évident, SOPH. <i>O.R. 754 ;</i><br><b>   III</b> qui brille d’un vif éclat :<br><b>      1</b> <i>au propre,</i> HDT. <i>4, 73, 75 ; en parl. d’objets (four, coquille, etc.) fortement chauffés,</i> HDT. <i>2, 92 ;</i> HPC. <i>476, 22 ; 788</i> a, <i>894</i> b ;<br><b>      2</b> <i>fig</i>. illustre, éclatant, PLAT. <i>Rsp. 600</i> b, <i>Tim. 25</i> b.<br><span><b>Étym</b>. διαφαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφανης - διαφανής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1308":"<h1>diaphero</h1>\n<p>Strong n° 1308 <i>Prononciation [dee-af-er'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>porter ou transporter quelque part</li>\n<li>transporter par différents moyens\n<ol type=\"a\">\n<li>dans différentes directions, vers divers lieux\n<ol>\n<li>de gens amenés ici et là en bateau, ballottés</li>\n</ol>\n</li>\n<li>mettre à l'épreuve, éprouver, voir ce qui diffère\n<ol>\n<li>distinguer entre le bien et le mal, légal et illicite, approuver ce qui excelle</li>\n<li>exceller, surpasser</li>\n</ol>\n</li>\n<li>ce qui fait la différence, ce qui est important</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·φέρω</b> <span>(<i>f</i>. διοίσω, <i>ao.1</i> διήνεγκα, <i>etc. ; pass. ao</i>. διηνέχθην, <i>etc</i>.)</span><br><b>A</b> (διά, <i>marquant</i> séparation) ;<br><b>   I <i>tr</i>.<br>      1</b> porter d’un côté et de l’autre, ballotter, <i>en parl. d’un navire, et, p. anal., d’une litière,</i> PLUT. <i>Galb. 26 ; fig. au pass</i>. être ballotté (par l’espérance) PLUT. <i>M. 606</i> d ;<br><b>      2</b> porter de côté et d’autre, en divers endroits : δ. τὰς κόρας, EUR. <i>Bacch. 1087,</i> porter ses regards de tous côtés ; δ. ἕκαστα εἰς τὰς χώρας τὰς προσηκούσας, XÉN. <i>Œc. 9, 8,</i> disposer chaque chose à la place convenable ; δ. ἀγγελίας, LUC. <i>D. deor. 24, 1,</i> répandre des nouvelles ; ἡ φήμη διηνέχθη, PLUT. <i>M. 163</i> c, le bruit se répandit ; <i>au pass</i>. être porté <i>ou</i> se porter de côté et d’autre : ἐν χώρᾳ, PLUT. <i>Thes. 24,</i> dans un pays ; φύγῃ διαφέρεσθαι, PLUT. <i>Cæs. 33,</i> se disperser en fuyant ; <i>en parl. de navigateurs,</i> se porter de côté et d’autre, louvoyer, STR. <i>144 ; en ce sens, en mauv. part,</i> bouleverser : ἄνω καὶ κάτω δ. EUR. <i>Bacch. 753,</i> mettre sens dessus dessous, bouleverser ; <i>fig</i>. δ. ψυχὰς φροντίσι, PLUT. <i>M. 133</i> d, troubler l’âme par des soucis ; <i>abs</i>. ἄτα διαφέρει τὸν αἴτιον, ESCHL. <i>Ch. 62,</i> la pensée du crime bouleverse le coupable ;<br><b>   II <i>intr.</i></b> être différent, <i>abs</i>. XÉN. <i>Œc. 20, 19 ;</i> τινός, EUR. <i>Or. 251 ;</i> AR. <i>Vesp. 20 ;</i> XÉN. <i>Cyr. 8, 2, 21,</i> de qqn <i>ou</i> de qqe ch. ; τινὶ δ. XÉN. <i>Hier. 1, 7 ;</i> PLAT. <i>Ap. 35</i> a, différer en qqe ch. ; τινός τινι, PLAT. <i>Ap. 35</i> b ; <i>1 Alc. 124</i> c, de qqn en qqe ch. ; δ. τι, ARSTT. <i>H.A. 2, 1, 3 ;</i> δ. εἴς τι, XÉN. <i>Hier. 1, 2 ;</i> ἔν τινι (<i>constr. rare</i>) DÉM. <i>291, 17 ;</i> πρός τι, ARSTT. <i>H.A. 2, 13, 10 ;</i> κατά τι, <i>ibid. 1, 1, 1,</i> différer en qqe ch. ; κατ' οὐδὲν ἀλλήλων διαφέροντες, LUC. <i>D. mort. 15, 1,</i> ne différant en rien les uns des autres ; τινὸς ἤ τινι ἢ οὐδὲν δ. EL. <i>N.A. 14, 26,</i> différer (de peau, de couleur, <i>etc</i>.) par qqe trait ou ne différer en rien ; τοσοῦτον δ. ὅσον, XÉN. <i>Œc. 20, 20,</i> différer autant… que ; οὐδὲν διαφέρειν ἤ, XÉN. <i>Vect. 3, 25,</i> ne différer en rien de ; <i>p. suite,</i> se distinguer de, l’emporter sur : τινός τι, ESCHN. <i>11, 13 ;</i> LUC. <i>D. mort. 12, 1,</i> l’emporter sur qqn en qqe ch. ; <i>rar</i>. τινά τινι, POL. <i>1, 88, 7 ;</i> DS. <i>2, 5 ; 11, 67,</i> surpasser qqn en qqe ch. ; διαφέρειν τινί, THC. <i>2, 39 ;</i> ESCHN. <i>19, 4 ;</i> ἐπί τινι, XÉN. <i>Mem. 4, 2, 1 ;</i> ἔν τινι, ISOCR. <i>34</i> e ; πρός τι, ESCHN. <i>25, 42 ;</i> εἴς τι, XÉN. <i>Cyr. 1, 1, 6 ;</i> PLAT. <i>Ap. 35</i> a ; κατά τι, XÉN. <i>Lac. 1, 10,</i> se distinguer par qqe ch., l’emporter par qqe ch. ; <i>abs</i>. ἱμάτια διαφέροντα, PLAT. <i>Phæd. 64</i> d, vêtements distingués ; πράσσειν διαφέρον τι, POL. <i>6, 39, 2,</i> faire qqe action d’éclat, qqe ch. de remarquable ; δ. τινός, <i>avec l’inf</i>. PLAT. <i>Prot. 328</i> a, l’emporter sur qqn pour faire qqe ch. ; <i>p. anal. au sens d’un compar. et suivi de</i> ἤ : πολὺ διέφερεν ἀλέξασθαι ἢ μάχεσθαι, XÉN. <i>An. 3, 4, 33,</i> il valait bien mieux repousser l’ennemi (en se maintenant dans une position fixe) que de combattre (en poursuivant la marche) ;<br><b>   III</b> <i>impers</i>. διαφέρει, il importe : οὐδὲν διαφέρει, XÉN. <i>Cyr. 2, 3, 4 ;</i> PLAT. <i>Phæd. 89</i> c, <i>Prot. 329</i> d, il n’importe en rien ; <i>avec un dat. de pers</i>. διαφέρειν τινί, POL. <i>4, 27, 4,</i> importer à qqn ; ἰδίᾳ τι αὐτῷ διέφερε, THC. <i>3, 42,</i> il avait à cela qqe intérêt personnel ; <i>avec un dat. de pers. et un inf</i>. οὐδέ τί οἱ διέφερε πληγέντι ἀποθανέειν, HDT. <i>1, 85,</i> il ne lui importait en rien, <i>càd</i>. il lui était indifférent de mourir frappé (par cet homme) ; <i>avec un dat. de pers. et</i> εἰ : δοκῶ τοῖς θανοῦσι διαφέρειν βραχύ, εἰ, EUR. <i>Tr. 1248,</i> les morts, j’imagine, s’inquiètent peu si, <i>etc. ; abs</i>. αἱ χῶραι διαφέρουσι, TH. <i>C.P. 5, 14, 9,</i> les conditions (de terroir, de climat, <i>etc</i>.) du pays importent ; τὸ διαφέρον, ANTIPH. (<i>Bkk. 89</i>) ; τὰ διαφέροντα, THC. <i>6, 92 ;</i> LYS. <i>187, 13 ;</i> IS. <i>47, 35 ;</i> AND. <i>31, 34, etc. ou</i> τὰ διαφέροντα πράγματα, PLUT. <i>Cæs. 65,</i> ce qui importe, les affaires qui importent ;<br><b>B</b> (διά, à travers, jusqu’au bout) :<br><b>   I</b> porter au delà, transporter : δ. ναῦς τὸν ἰσθμόν, THC. <i>8, 8,</i> transporter ses vaisseaux de l’autre côté de l’isthme ; τινὰ εἰς Σικελίαν, APP. <i>Civ. 4, 48,</i> transporter qqn en Sicile ; <i>d’où intr</i>. se porter à travers, pénétrer dans ; τὸ ἄκρον διήνεγκε κάτω τοῦ ὀμφαλοῦ, HPC. <i>1148</i> f, la pointe s’enfonça au-dessous du nombril ;<br><b>   II</b> porter jusqu’au bout, <i>càd. :</i><br><b>      1</b> apporter : ψῆφον, THC. <i>4, 74 ;</i> XÉN. <i>Conv. 5, 8 ;</i> EUR. <i>Or. 49, 1652 ;</i> ESCHN. <i>82, 20 ;</i> DÉM. <i>795, 1 ;</i> PLUT. <i>Tim. 23,</i> apporter son suffrage ;<br><b>      2</b> porter d’une manière continue : σκῆπτρα, EUR. <i>I.A. 1195,</i> porter le sceptre ; γαστρὸς ὄγκον, EUR. <i>Ion 15,</i> porter le fruit de ses entrailles ; <i>abs</i>. XÉN. <i>Mem. 2, 2, 5 ;</i><br><b>      3</b> <i>en parl. du temps,</i> porter jusqu’au bout : δ. τὸν αἰῶνα, HDT. <i>3, 40,</i> passer le temps ; <i>abs</i>. διοίσει ἄπαις, EUR. <i>Rhes. 982,</i> il passera sa vie sans enfants ; <i>p. suite,</i> durer, continuer, <i>avec un partic</i>. θεοὺς σέϐων βίον διήνεγκε, EUR. <i>Hel. 10,</i> il a passé sa vie dans le respect et le culte des dieux ; <i>avec un acc. de temps :</i> δ. ἐννέα ἔτεα, HPC. <i>537, 49,</i> durer neuf ans ; <i>avec une prép</i>. δ. ἕως <i>et le gén</i>. HPC. <i>553, 54,</i> durer, se maintenir jusqu’à, <i>etc. ; d’où</i> faire traîner en longueur : πόλεμον, HDT. <i>1, 74,</i> faire traîner une guerre en longueur (<i>ou qqf</i>. la soutenir jusqu’à la fin, HDT. <i>1, 25 ;</i> THC. <i>1, 11 ; 6, 54 ; 8, 75 ;</i> PAUS. <i>3, 10, 5</i>) ;<br><b>      4</b> supporter : τι, SOPH. <i>O.R. 321 ;</i> EUR. <i>Hipp. 1143 ;</i> PLUT. <i>Dem. c. Cic. 4,</i> qqe ch. ; χαλεπῶς τι, HDN <i>2, 5, 15,</i> qqe ch. avec peine ;<br><b><i>Moy</i>. διαφέρομαι</b> <span>(<i>f</i>. διοίσομαι, <i>ao</i>. διηνέχθην)</span><br><b>      1</b> différer d’avis, être en désaccord : ἀλλήλοις, PLAT. <i>Euthyphr. 5</i> a ; πρὸς ἀλλήλους, LYS. <i>150, fin, ou</i> πρὸς ἀλλήλους ταῖς γνώμαις, POL. <i>4, 23, 7,</i> les uns avec les autres ; σφίσιν αὐτοῖς, ANT. <i>135, 22,</i> avec eux-mêmes ; <i>abs</i>. μηδὲν διαφέρου περὶ τούτου, AR. <i>Lys. 1172,</i> ne dispute pas là-dessus ; δ. περί τινος, PLAT. <i>Euthyphr. 11</i> b ; ἀμφί τινος, XÉN. <i>An. 4, 5, 17 ;</i> ἔν τινι, XÉN. <i>Œc. 17, 4,</i> disputer sur qqe ch. ; δ. ὡς, DÉM. <i>1296, 24,</i> soutenir contrairement à qqn… que ; <i>abs</i>. τὰ διαφέροντα, THC. <i>1, 70,</i> les intérêts en jeu ; <i>p. suite,</i> combattre : περὶ τῆς βασιληΐης, HDT. <i>1, 173,</i> pour la royauté, se disputer la royauté ;<br><b>      2</b> passer son temps : σοῦ διοίσεται μόνος, SOPH. <i>Aj. 511,</i> il passera sa vie séparé de toi (<i>sel. d’autres,</i> δ. <i>au sens pass</i>. il sera tourmenté, malheureux, <i>litt</i>. ballotté, <i>cf</i>. A, I, 1) ; <i>abs</i>. passer son temps, <i>d’où</i> durer, se maintenir, HPC. <i>823</i> c.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφερω - διαφέρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n13 fois dans 13 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1309":"<h1>diapheugo</h1>\n<p>Strong n° 1309 <i>Prononciation [dee-af-yoo'-go]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fuir un danger, s'échapper, se tirer d'affaire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·φεύγω</b> <span>(<i>f</i>. -φεύξομαι, <i>ao.2</i> διέφυγον, <i>etc</i>.)</span> s’enfuir, échapper par la fuite : ἐκ τῆς Μήλου, THC. <i>8, 39,</i> s’enfuir de Mèlos ; <i>d’où en gén</i>. échapper à, se soustraire à : τινά, EUR. <i>Bacch. 642, Ion 1254,</i> échapper à qqn ; δουλοσύνην, HDT. <i>6, 45,</i> échapper à la servitude ; χρέα, AR. <i>Nub. 442,</i> esquiver le payement d’une dette ; θάνατον, PLAT. <i>Ap. 39</i> a ; νόσημα, ARSTT. <i>H.A. 8, 21,</i> échapper à la mort, à une maladie ; <i>abs</i>. THC. <i>2, 49 ;</i> HPC. <i>175</i> g, échapper à la mort ; δ. ἔκ τινος εἴς τι, PLAT. <i>Leg. 815</i> e, échapper à une ch. (à un mal) pour se réfugier dans une autre (dans un bien) ; <i>avec un suj. de chose :</i> τοῦτο διαφεύγει με, PLAT. <i>Phæd. 95</i> e, <i>etc. ;</i> ISOCR. <i>80</i> b, cela m’échappe, <i>càd</i>. je l’ignore <i>ou</i> je ne m’en souviens plus (<i>lat</i>. me fugit).<br><span><b><span class=\"arrow\"></span></b> <i>Fut. poét</i>. διαφευξοῦμαι, AR. <i>l. c. Ao. pass. inf</i>. διαφευχθῆναι, JOS. <i>A.J. 17, 3, 1</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφευγω - διαφεύγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1310":"<h1>diaphemizo</h1>\n<p>Strong n° 1310 <i>Prononciation [dee-af-ay-mid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étendre au loin, divulguer, publier, porter çà et là</li>\n<li>répandre sa renommée ou son renom</li>\n<li>forme passive aller à la dérive</li>\n<li>sens intransitif être indifférent</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·φημίζω</b> <span>(<i>impf</i>. διεφήμιζον, <i>ao</i>. διεφήμισα)</span> faire connaître partout, divulguer, ARAT. <i>221 ;</i> DH. <i>11, 46 ;</i> NT. <i>Marc. 1, 45 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao. 3 pl</i>. διεφημίξαντο, DP. <i>26)</i></span><i> m. sign</i>.<br><span><b>Étym</b>. διά, φήμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφημιζω - διαφημίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1311":"<h1>diaphtheiro</h1>\n<p>Strong n° 1311 <i>Prononciation [dee-af-thi'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>changer pour le pire, corrompre\n<ol type=\"a\">de l'esprit, du moral</ol>\n</li>\n<li>détruire, ruiner\n<ol type=\"a\">\n<li>consumer\n<ol>\n<li>de la vigueur et de la force corporelle</li>\n<li>du ver qui mange les provisions, les vêtements, etc.</li>\n</ol>\n</li>\n<li>tuer</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·φθείρω</b> <span>(<i>f</i>. -φθερῶ, <i>ao</i>. διέφθειρα, <i>pf.1</i> διέφθαρκα, <i>pf.2 trans. ou intr</i>. διέφθορα ; <i>pass. ao.2</i> διεφθάρην, <i>pf</i>. διέφθαρμαι)</span><br><b>A <i>tr</i>.<br>   I</b> détruire : πόλιν, IL. <i>13, 625,</i> une ville ; αἱ νῆες διεφθάρησαν, HDT. <i>1, 166 ;</i> AND. <i>18, 32,</i> les vaisseaux furent détruits ; <i>avec un rég. de pers</i>. δ. τινά, ESCHL. <i>Ag. 1266,</i> faire périr qqn ; <i>p. opp. à</i> φύω, SOPH. <i>O.R. 438 ; au pass</i>. ὑπὸ τῆς νόσου διεφθαρμένος, ISOCR. <i>180</i> c, ruiné par la maladie ; πᾶς διέφθαρται στρατός, ESCHL. <i>Pers. 716,</i> toute l’armée a été détruite ; <i>particul. en parl. des mutilations ou infirmités physiques :</i> διεφθαρμένος τὴν ἀκοήν, HDT. <i>1, 38 ;</i> τὰ ὄμματα, PLAT. <i>Rsp. 517</i> a, privé de l’ouïe, de la vue ; <i>ou simpl</i>. διέφθαρτο, HDT. <i>1, 34,</i> il était atteint d’infirmité (sourd et muet) ; διέφθαρμαι δέμας τὸ πᾶν, SOPH. <i>Tr. 1056,</i> tout mon corps est détruit ; <i>p. anal</i>. διεφθάρθαι φρένας, EUR. <i>Hel. 1192,</i> être consumé par la douleur, avoir l’esprit égaré ; τὴν φρόνησιν διαφθαρείς, ISOCR. <i>274</i> b, qui a perdu la raison ; τὸ διαφθαρὲν φρενῶν, EUR. <i>Or. 297,</i> égarement de la raison (<i>cf</i>. φρενοϐλάϐεια) ;<br><b>   II</b> <i>p. suite,</i> mettre à mal, <i>d’où :</i><br><b>      1</b> endommager, gâter : γραμματεῖον, ISOCR. <i>363, 365,</i> falsifier un écrit ; νόμους, ISOCR. <i>373</i> b, altérer les lois ;<br><b>      2</b> corrompre, séduire : γυναῖκα, LYS. <i>93, 16 ;</i> κόρην, MÉN. <i>Adelph. fr. 6,</i> une femme, une jeune fille ; <i>au mor</i>. τοὺς νέους, PLAT. <i>Ap. 25</i> a, <i>Euthyphr. 2</i> c, <i>etc</i>. corrompre les jeunes gens ; ἀργυρίῳ, ARSTT. <i>Pol. 2, 6, 14 ;</i> ἐπὶ χρήμασι, DÉM. <i>241, 1, ou simpl</i>. διαφθείρειν τινά, HDT. <i>5, 51 ;</i> DÉM. <i>122, 21 ;</i> ESCHN. <i>38, 10,</i> corrompre qqn à prix d’argent ;<br><b>      3</b> perdre par avortement, <i>acc</i>. HPC. <i>1255</i> b ; PLUT. <i>M. 242</i> c ; <i>d’où abs</i>. avorter, HPC. <i>1221</i> d, <i>1229</i> a ; IS. <i>73, 4 ;</i><br><b>B</b> <i>Pf. 2</i> διέφθορα <i>tantôt au sens tr. (seul us. chez les Att</i>.) δ. τὰς φρένας, EUR. <i>Hipp. 1013,</i> faire perdre la raison ; δ. τὰς ἐλπίδας, SOPH. <i>El. 306,</i> détruire les espérances ; <i>tantôt au sens intr</i>. διέφθορας, IL. <i>15, 128,</i> tu es perdu ; αἷμα διεφθορός, HPC. <i>M. mul. 2, 23,</i> sang corrompu ; διεφθορότα σώματα, PLUT. <i>M. 87</i> c, corps en putréfaction ;<br><b><i>Moy.</i></b> perdre par avortement, <i>acc</i>. HPC. <i>599, 11 ; 619, 25</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. itér. 3 sg</i>. διαφθείρεσκε, HDT. <i>1, 36. Fut. épq. 3 sg</i>. διαφθέρσει, IL. <i>13, 625. Pf. au sens tr</i>. διέφθαρκα, EUR. <i>Med. 226 ;</i> PLAT. <i>Ap. 33</i> c ; ESCHN. <i>38, 10, etc. Pf. 2</i> διέφθορα (<i>v. ci-dessus). — Pass. fut</i>. διαφθαρήσομαι, THC. <i>4, 37. Fut. ion. 3 sg</i>. διαφθαρέεται, HDT. <i>8, 108 ; 3 pl</i>. -έονται, HDT. <i>9, 42. Pl.q.pf. 3 pl. ion</i>. διεφθαρέατο, HDT. <i>8, 90</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφθειρω - διαφθείρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G1312":"<h1>diaphthora</h1>\n<p>Strong n° 1312 <i>Prononciation [dee-af-thor-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corruption, destruction</li>\n<li>dans le N.T, la destruction du corps après la mort</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διαφθορά, ᾶς (ἡ) :<br>   I <i>tr</i>.<br>      1</b> destruction, perte, ruine, PLAT. <i>Soph. 228</i> a, <i>etc. ;</i> τῆς πόλεως, THC. <i>8, 86,</i> de l’État ; μορφῆς, ESCHL. <i>Pr. 643,</i> métamorphose, <i>au plur</i>. διαφθοραὶ Λαΐου, SOPH. <i>O.R. 513,</i> meurtre de Laïus ; ὀμμάτων διαφθοραί, SOPH. <i>O.C. 552,</i> perte de la vue ;<br><b>      2</b> action de corrompre : τῶν νέων, XÉN. <i>Ap. 19 ;</i> κριτῶν, ARSTT. <i>Rhet. 1, 12, 8,</i> les jeunes gens, des juges ;<br><b>   II</b> <i>intr</i>. état de putréfaction (du fœtus) HPC. <i>202</i> d ; <i>591, 23 ;</i><br><b>   III</b> <i>pass</i>. ce qui est détruit, <i>d’où</i> proie (pour les poissons) <i>en parl. d’un cadavre,</i> SOPH. <i>Aj. 1297 (cf</i>. ἁρπαγή) ; <i>fig. joint à</i> ὕϐρισμα <i>et à</i> ἐπίχαρμα, EUR. <i>H.f. 459</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. διαφθορή, HPC. <i>ll. cc</i>.<br><span><b>Étym</b>. διαφθείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφθορα - διαφθορά</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (6)</li>\n</ul>\n</td></tr>\n</table>","G1313":"<h1>diaphoros</h1>\n<p>Strong n° 1313 <i>Prononciation [dee-af'-or-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>différent, de sortes variées, divers</li>\n<li>excellent, surpassant, supérieur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διάφορος, ος, ον :<br>A</b> qui diffère, <i>en gén., d’où :</i><br><b>   I</b> différent, HDT. <i>2, 83 ; 4, 81 ;</i> PLAT. <i>Leg. 964</i> a ; τινος, PLAT. <i>Parm. 141</i> b ; <i>Phil. 61</i> d, <i>etc. ;</i> τινι, EUR. <i>Med. 579,</i> de qqe ch. ; <i>subst</i>. τὸ διάφορον, la différence, HDT. <i>2, 7 ;</i> HPC. <i>792</i> e ; <i>plur</i>. τὰ διάφορα, les différences, IS. <i>89, 1,</i> DÉM. <i>16, 26 ;</i><br><b>   II</b> <i>particul. en b. part,</i> qui se distingue, supérieur, remarquable : πάντων διάφορος, ANTIPH. (ATH. <i>643</i> d) qui se distingue entre tous ; τινι, DS. <i>2, 57 ;</i> πρός τι, PLUT. <i>Cleom. 16,</i> par qqe ch., à l’égard de qqe ch. ; <i>d’où</i> avantageux, utile, THC. <i>4, 3 ;</i> πρός τι, PLAT. <i>Leg. 779</i> b, pour qqe ch. ; τὰ διάφορα, THC. <i>1, 68,</i> les intérêts ;<br><b>B</b> qui diffère d’avis, de sentiment, <i>d’où :</i><br><b>   I</b> qui est en désaccord : τινι, HDT. <i>5, 75 ;</i> LYS. <i>144, 2 ;</i> XÉN. <i>Hell. 5, 2, 17 ; 6, 4, 25 ;</i> PLAT. <i>Leg. 679</i> b, <i>etc</i>. avec qqn ; δ. τινος, DÉM. <i>849, 10 ;</i> IS. <i>36, 7,</i> adversaire de qqn ; <i>subst</i>. τὸ διάφορον :<br><b>      1</b> la partie adverse, DH. <i>6, 36 ;</i><br><b>      2</b> différend, contestation, THC. <i>2, 37 ; 5, 40 ;</i><br><b>      3</b> différence, balance d’un compte, HYPÉR. <i>Eux. 30 ;</i> prix, EPICT. <i>Ench. 25, 4 ; au plur</i>. dépenses, DÉM. <i>887, 8 ; d’où</i> argent, <i>en gén</i>. POL. <i>4, 18, 8 ; 6, 45, 4 ;</i><br><b>   II</b> <i>p. suite,</i> qui contrarie, désagréable à, <i>dat</i>. PLAT. <i>Leg. 843</i> c.<br><span><b>Étym</b>. διαφέρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφορος - διάφορος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (3)</li>\n</ul>\n</td></tr>\n</table>","G1314":"<h1>diaphulasso</h1>\n<p>Strong n° 1314 <i>Prononciation [dee-af-oo-las'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>garder soigneusement, tenir sous sa garde (se dit des anges)\n<ol type=\"a\">\n<li>la version des Septante utilise l'expression de soin providentiel de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·φυλάσσω</b>, <i>att</i>. <b>-άττω</b> <span>(<i>f</i>. άξω, <i>ao</i>. διεφύλαξα, <i>etc</i>.)</span> <span>[ῠ]</span><br><b>      1</b> garder avec soin (des remparts, une ville, <i>etc.) acc</i>. HDT. <i>6, 101 et 133 ;</i> LYS. <i>193, 29, etc. ;</i><br><b>      2</b> observer avec soin, <i>acc</i>. HDT. <i>2, 121, 1 ; fig</i>. observer, maintenir (des lois, la paix, <i>etc</i>.) PLAT. <i>Leg. 951</i> b ; PHILIPP. (DÉM. <i>251, 24) ; avec</i> τὸ μή <i>et l’inf</i>. veiller à ne pas, PLAT. <i>Pol. 261</i> e ; <i>avec</i> ὅτι, veiller à, se préoccuper de, PLAT. <i>Criti. 112</i> d ;<br><b>      3</b> garder souvenir, LUC. <i>Char. 7 ;</i><br><b><i>Moy.</i></b> faire bonne garde, veiller sur, EUR. <i>I.A. 369</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαφυλασσω - διαφυλάσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1315":"<h1>diacheirizomai</h1>\n<p>Strong n° 1315 <i>Prononciation [dee-akh-i-rid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>déplacer par l'usage des mains, prendre en main, diriger, administrer, gouverner</li>\n<li>poser les mains sur, tuer, faire périr de ses propres mains, maltraiter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·χειρίζω</b>, avoir <i>ou</i> prendre en main, manier, gérer, <i>acc</i>. PLAT. <i>Gorg. 526</i> b ; AND. <i>21, 43 ;</i> ARSTT. <i>Pol. 6, 8, 16 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> manier, traiter, soigner, <i>acc</i>. HPC. <i>638, 42 ;</i> PLUT. <i>Per. 15 ;</i><br><b>      2</b> porter la main sur, tuer, <i>acc</i>. POL. <i>8, 23, 8 ;</i> PLUT. <i>M. 220</i> b ; NT. <i>Ap. 5, 30 ; 26, 21</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. moy. part. acc. sg</i>. διαχειριούμενον, HPC. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαχειριζομαι - διαχειρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1316":"<h1>diachorizomai</h1>\n<p>Strong n° 1316 <i>Prononciation [dee-akh-o-rid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>séparer complètement ou entièrement</li>\n<li>se séparer, partir, quitter</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δια·χωρίζω</b>, <i>f</i>. ίσω, <i>att</i>. -ιῶ, diviser, séparer, <i>acc</i>. XÉN. <i>Œc. 9, 7 ;</i> PLAT. <i>Tim. 59</i> c, <i>Phil. 17</i> a ; <i>avec</i> ἀπό <i>et le gén</i>. PLAT. <i>Pol. 262</i> b.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διαχωριζομαι - διαχωρίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1317":"<h1>didaktikos</h1>\n<p>Strong n° 1317 <i>Prononciation [did-ak-tik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>apte et habile dans l'enseignement, capable d'enseigner</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδακτικός, ή, όν</b> <span>[δῐ]</span> propre à instruire, didactique, PHIL. <i>2, 412 ;</i> NT. <i>1Tim. 3, 2 ; 2, 2, 24</i>.<br><span><b>Étym</b>. διδάσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδακτικος - διδακτικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1318":"<h1>didaktos</h1>\n<p>Strong n° 1318 <i>Prononciation [did-ak-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui peut être enseigné</li>\n<li>enseigné, instruit par quelqu'un</li>\n<li>enseignants, précepteurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδακτός, ή</b> <i>ou</i> <b>ός, όν</b> <span>[ῐ]</span><br><b>   I</b> <i>en parl. de choses</i> :<br><b>      1</b> enseigné, appris, SOPH. <i>El. 344 ;</i> EUR. <i>Hipp. 79 ;</i><br><b>      2</b> qu’on peut <i>ou</i> qu’il faut enseigner, PD. <i>N. 3, 71 ;</i> SOPH. <i>Tr. 64, fr. 723 ;</i> PLAT. <i>Euthyd. 274</i> e ; <i>Eryx. 398</i> d, <i>404</i> d ; ISOCR. <i>295</i> b ; <i>etc. ;</i><br><b>   II</b> <i>en parl. de pers</i>. enseigné, instruit : τινος, SPT. <i>1Macc. 4, 7 ;</i> NT. <i>Joh. 6, 45,</i> instruit en qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. διδακτός, PLAT. <i>Eryx. 398</i> d.<br><span><b>Étym</b>. <i>vb. de</i> διδάσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδακτος - διδακτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G1319":"<h1>didaskalia</h1>\n<p>Strong n° 1319 <i>Prononciation [did-as-kal-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enseignement, instruction</li>\n<li>enseigner\n<ol type=\"a\">\n<li>ce qui doit être pensé, doctrine</li>\n<li>préceptes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδασκαλία, ας (ἡ)</b> <span>[ῐκᾰ]</span><br><b>   I</b> instruction, enseignement, PD. <i>P. 4, 102 ;</i> XÉN. <i>Cyr. 8, 7, 3 ;</i> PLAT. <i>Leg. 803</i> a, <i>Rsp. 493</i> b, <i>etc. ;</i> ARSTT. <i>Nic. 2, 2, 1 ;</i> διδασκαλίαν ποιεῖσθαι, THC. <i>2, 42,</i> enseigner, montrer ; διδασκαλίαν παρέχειν, THC. <i>2, 87,</i> servir de leçon ;<br><b>   II</b> <i>en parl. du théâtre :</i><br><b>      1</b> instructions : δ. τῶν χορῶν, PLAT. <i>Gorg. 501</i> e ; PLUT. <i>Nic. c. Crass. 1, Per. 5, M. 1096</i> a, instructions pour le chant du chœur, <i>ou en gén</i>. pour la déclamation des acteurs <i>ou</i> pour le jeu des danseurs ;<br><b>      2</b> <i>p. ext</i>. représentation d’une pièce, ARSTT. <i>Poet. 19, 6 ;</i><br><b>      3</b> œuvre dramatique, PLUT. <i>Cim. 8, etc. ;</i><br><b>      4</b> διδασκαλίαι, <i>litt</i>. renseignements, <i>càd</i>. catalogues des pièces de théâtre (avec le nom des auteurs, la date et les particularités des représentations) ARSTT. <i>fr. 575, etc. ;</i> DS. <i>5, 26</i>.<br><span><b>Étym</b>. διδάσκαλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδασκαλια - διδασκαλία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n21 fois dans 21 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (8)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (4)</li>\n</ul>\n</td></tr>\n</table>","G1320":"<h1>didaskalos</h1>\n<p>Strong n° 1320 <i>Prononciation [did-as'-kal-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un professeur</li>\n<li>dans le N.T, celui qui enseigne les choses de Dieu et les devoirs de l'homme\n<ol type=\"a\">\n<li>celui qui est capable d'enseigner, ou qui le pense</li>\n<li>les docteurs de la religion Juive</li>\n<li>ceux qui par leur grand pouvoir d'enseigner attiraient des foules autour d'eux: ex. Jean Baptiste, Jésus</li>\n<li>Jésus par lui-même car il enseignait la voie du salut</li>\n<li>les apôtres et Paul</li>\n<li>ceux qui dans les assemblées de Chrétiens continuaient l'œuvre d'enseignement, avec l'aide du Saint Esprit</li>\n<li>les faux ψευδος enseignants parmi les Chrétiens</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδάσκαλος, ου (ὁ, ἡ)</b> <span>[ῐκᾰ]</span><br><b>      1</b> celui <i>ou</i> celle qui enseigne ; maître, précepteur, ATT. ; δ. τινος, XÉN. <i>Cyr. 1, 6, 19 ; 2, 3, 5 ;</i> ISOCR. <i>253</i> d, <i>291</i> c, <i>etc. ;</i> celui qui enseigne qqe ch. ; <i>avec un gén. de pers</i>. δ. τινος, PLAT. <i>Ap. 33</i> a ; LUC. <i>Macr. 21, etc</i>. le maître de qqn ; <i>avec double rég</i>. δ. τέχνης πάσης βροτοῖς, ESCHL. <i>Pr. 110,</i> qui enseigne aux mortels tous les arts ; <i>abs</i>. ESCHL. <i>Pr. 373, 391 ; etc. ;</i> εἰς διδασκάλου (<i>s.-e</i>. οἶκον) φοιτᾶν, PLAT. <i>1 Alc. 109</i> d, aller à l’école, fréquenter l’école ; ἐν διδασκάλων ἤκουον, PLAT. <i>1 Alc. 110</i> a, j’ai appris à l’école ; διδασκάλων ἀπαλλαγῆναι, PLAT. <i>Gorg. 514</i> c, <i>ou</i> ἐκ δ. ἀπ. PLAT. <i>Prot. 326</i> c, quitter l’école ;<br><b>      2</b> <i>t. de théâtre,</i> χοροῦ δ. <i>ou abs</i>. διδάσκαλος, celui qui dirige les répétitions d’un chœur, d’une pièce, <i>càd</i>. l’auteur lui-même, <i>d’où</i> poète dramatique, AR. <i>Av. 912, Ach. 628 ;</i> ANT. <i>143, 4</i>.<br><span><b><span class=\"arrow\"></span></b> ἡ δ. HH. <i>Merc. 556 ;</i> ESCHL. <i>Pr. 110 ;</i> EUR. <i>Andr. 947 ;</i> THCR. <i>Idyl. 21, 2 ;</i> LUC. <i>Tim. 33</i>.<br><span><b>Étym</b>. διδάσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδασκαλος - διδάσκαλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n58 fois dans 57 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (12)</li>\n<li>Luc (17)</li>\n<li>Jean (8)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1321":"<h1>didasko</h1>\n<p>Strong n° 1321 <i>Prononciation [did-as'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enseigner\n<ol type=\"a\">\n<li>tenir un discours aux autres en vue de les instruire, avoir des paroles didactiques</li>\n<li>être un enseignant</li>\n<li>remplir le rôle d'enseignant, se conduire comme un enseignant</li>\n</ol>\n</li>\n<li>instruire\n<ol type=\"a\">\n<li>donner une instruction</li>\n<li>faire assimiler une doctrine</li>\n<li>ce qui est dit ou enjoint</li>\n<li>expliquer ou exposer une chose</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδάσκω</b> <span>(<i>f</i>. διδάξω, <i>ao</i>. ἐδίδαξα, <i>pf</i>. δεδίδαχα ; <i>pass. ao</i>. ἐδιδάχθην, <i>pf</i>. δεδίδαγμαι)</span> <span>[ῐ]</span><br><b>      1</b> enseigner, instruire, apprendre : τι, IL. <i>9, 442 ;</i> PLAT. <i>Phædr. 276</i> c, <i>etc</i>. enseigner qqe ch. ; τινά, IL. <i>11, 832 ;</i> OD. <i>8, 488 ;</i> ESCHL. <i>Pr. 196 ;</i> XÉN. <i>Hell. 2, 4, 10,</i> instruire qqn ; <i>avec double rég</i>. τινά τι, IL. <i>23, 307 ;</i> OD. <i>8, 481 ;</i> XÉN. <i>Mem. 1, 2, 10 ;</i> PLAT. <i>Conv. 201</i> d, <i>etc. ;</i> EUR. <i>Hipp. 252, etc. ;</i> τινὰ περί τινος, AR. <i>Nub. 382 (cf. ci-dessous</i> THC. <i>3, 71</i>), apprendre qqe ch. à qqn ; τινὰ ποιεῖν τι, IL. <i>5, 51, etc. ;</i> PLAT. <i>Men. 85</i> d ; LYS. <i>141, 37 ; postér</i>. τινὶ ποιεῖν τι, PLUT. <i>Marc. 12 (seul ex. connu de cette construct. ; ttf. cf</i>. PLAT. <i>Theæt. 201</i> b, <i>où le dat. s’explique par attract</i>.) apprendre à qqn à faire qqe ch. ; τινὰ δ. <i>avec un acc. de pers. et</i> εἶναι : δ. τινὰ ὑψαγόρην ἔμεναι, OD. <i>1, 384,</i> apprendre à qqn à être disert ; <i>ou sans</i> εἶναι : διδάσκειν τινὰ ἱππέα, PLAT. <i>Men. 94</i> b, apprendre à qqn l’équitation (<i>litt</i>. à être cavalier) ; πολλοὶ τοὺς υἱοὺς ῥήτορας διδάσκουσιν, ARISTONYM. (STOB. <i>Fl. 4, 106</i>) beaucoup apprennent à leurs fils à devenir rhéteurs ; <i>cf</i>. PLUT. <i>M. 405</i> f ; CHAR. LAMPS. (ATH. <i>520</i> f) ; <i>avec une conj</i>. περὶ τῶν πεπραγμένων διδάξοντας ὡς ξυνέφερε, THC. <i>3, 71,</i> devant expliquer les faits en les présentant sous un jour favorable ; <i>abs</i>. πῶς δή ; δίδαξον, ESCHL. <i>Eum. 431,</i> comment donc ? explique ; λέγων διδασκέτω, XÉN. <i>An. 5, 7, 11,</i> qu’il parle et qu’il s’explique ; <i>au pass. avec un gén</i>. διδασκόμενος πολέμοιο, IL. <i>16, 811,</i> instruit <i>ou</i> expert dans la guerre ; <i>avec l’acc</i>. ὃς οὔτ' ἐδιδάχθη οὔτ' οἶδεν καλὸν οὐδέν, HDT. <i>3, 81,</i> qui n’a appris ni ne sait rien de beau ; <i>avec double rég</i>. τά σε προτί φασιν Ἀχιλλῆος δεδιδάχθαι, IL. <i>11, 831,</i> les remèdes que l’on dit t’avoir été enseignés par Achille ; <i>avec l’inf</i>. βρέφος διδάσκεται λέγειν, EUR. <i>Suppl. 914,</i> le petit enfant apprend à répéter (ce qu’on lui enseigne) ; <i>avec une conj</i>. διδάσκεσθαι ὡς, XÉN. <i>Hell. 2, 3, 45,</i> apprendre que, <i>etc. ;</i><br><b>      2</b> <i>particul</i>. διδάσκειν δρᾶμα, HDT. <i>6, 21 ;</i> δ. διθύραμϐον, HDT. <i>1, 23 ;</i> Πέρσας, AR. <i>Ran. 1026 (cf</i>. PLAT. <i>Prot. 327</i> d) faire représenter une pièce, un dithyrambe, les Perses (d’Eschyle) <i>etc., litt</i>. donner les instructions nécessaires aux acteurs qui doivent jouer ;<br><b><i>Moy</i>. διδάσκομαι</b> <span>(<i>f</i>. διδάξομαι)</span><br><b>   I <i>tr</i>.<br>      1</b> faire instruire : τι τοὺς υἱέας, PLAT. <i>Prot. 325</i> b, faire apprendre qqe ch. à ses enfants ; δ. τινα ἱππεύειν, PLAT. <i>Rsp. 467</i> e, faire apprendre l’équitation à qqn ; τὸν υἱὸν ἱππέα διδάσκεσθαι ἀγαθόν, PLAT. <i>Men. 93</i> d (<i>cf</i>. XÉN. <i>Mem. 4, 4, 5</i>) faire donner à son fils l’éducation d’un bon cavalier ;<br><b>      2</b> instruire, enseigner qqn, PLAT. <i>Menex. 238</i> b ; AR. <i>Nub. 783 ;</i> LUC. <i>Tox. 14, etc. ;</i><br><b>   II</b> <i>au sens réfléchi,</i> s’instruire <i>ou</i> apprendre pour soi, <i>abs</i>. AR. <i>Nub. 127 ; avec l’acc</i>. ἀστυνόμους ὀργὰς δ. SOPH. <i>Ant. 354,</i> apprendre à connaître les lois qui portent à vivre en société, les mœurs civilisées.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. épq</i>. διδασκέμεναι, IL. <i>9, 442, et</i> διδασκέμεν, IL. <i>23, 308. Ao. poét</i>. δίδαξα, IL. <i>5, 51 ;</i> PD. <i>N. 3, 55. Autre ao. poét</i>. *ἐδιδάσκησα, <i>d’où opt</i>. διδασκήσαιμι, HH. <i>Cer. 144 ; inf</i>. διδασκῆσαι, HÉS. <i>O. 64. Pass. fut. réc</i>. διδαχθήσομαι, DH. <i>3, 70 ;</i> SEXT. <i>182. Moy. f. au sens pass</i>. διδάξομαι, SOPH. <i>Ant. 726 ;</i> EUR. <i>Andr. 739 ;</i> AR. <i>Nub. 127 ;</i> PLAT. <i>Rsp. 421. Ao. poét. 2 sg</i>. διδάξαο, MOSCH. <i>3, 97</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *d(e)ns-, enseigner ; <i>prés. factitif en</i> -σκ- <i>de</i> δαῆναι, <i>v</i>. *δάω, <i>avec redoublement</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδασκω - διδάσκω</font>\n<br><br>forme du verbe primaire dao (apprendre)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n97 fois dans 91 versets de 17 livres bibliques (NT)\n<ul>\n<li>Matthieu (14)</li>\n<li>Marc (17)</li>\n<li>Luc (17)</li>\n<li>Jean (10)</li>\n<li>Actes (16)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (3)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>1 Jean (3)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1322":"<h1>didache</h1>\n<p>Strong n° 1322 <i>Prononciation [did-akh-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>enseignement\n<ol type=\"a\">\n<li>ce qui est dit</li>\n<li>doctrine, enseignement concernant quelque chose</li>\n</ol>\n</li>\n<li>l'action d'enseigner, l'instruction\n<ol type=\"a\">\n<li>dans une assemblée de Chrétiens, parler pour enseigner, ce qui distingue d'autres façons de s'exprimer en public</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διδαχή, ῆς (ἡ)</b> <span>[ῐᾰ]</span> enseignement, instruction, HDT. <i>3, 134 ; 5, 58 ;</i> THC. <i>1, 120 ;</i> PLAT. <i>Rsp. 536</i> d, <i>etc. ;</i> διδαχὴν ποιεῖσθαι, THC. <i>4, 126, etc</i>. donner des enseignements.<br><span><b>Étym</b>. διδάσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδαχη - διδαχή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n30 fois dans 29 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (5)</li>\n<li>Luc (1)</li>\n<li>Jean (3)</li>\n<li>Actes (4)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n<li>2 Jean (3)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G1323":"<h1>didrachmon</h1>\n<p>Strong n° 1323 <i>Prononciation [did'-rakh-mon]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une « didrachmon » ou double drachme, pièce d'argent égale à deux drachmes ou un Alexandrin, ou un demi sicle</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>δί·δραχμος, ος, ον</b>, de deux drachmes, qui se paie deux drachmes, qui pèse deux drachmes (EUDÈME ANAT. (GAL.)) ARSTT. <i>Œc. 2, 36 ;</i> δ. ὁπλῖται, THC. <i>3, 17,</i> hoplites dont la solde est de 2 drachmes par jour ; τὸ δίδραχμον, ARSTT. <i>Ath. 10, 2 ;</i> NT. <i>Matth. 17, 24,</i> pièce de 2 drachmes.<br><span><b>Étym</b>. δίς, δραχμή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδραχμον - δίδραχμον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G1324":"<h1>Didumos</h1>\n<p>Strong n° 1324 <i>Prononciation [did'-oo-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Didyme (Angl. Didymus) = « deux, jumeaux »\n<ol><li>surnom de l'apôtre Thomas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Δίδυμος, ου (ὁ)</b> Didyme :<br><b>      1</b> <i>grammairien,</i> PLUT. <i>Sol. 1, etc. ;</i><br><b>      2</b> <i>n. de l’apôtre Thomas,</i> NT. <i>Joh. 11, 16 ;</i><br><b>      3</b> <i>autres,</i> DIN. <i>fr. 85 Baiter-Sauppe ;</i> ANTH. <i>7, 568, etc</i>.<br><span><b>Étym</b>. <i>cf</i>. δίδυμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Διδυμος - Δίδυμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G1325":"<h1>didomi</h1>\n<p>Strong n° 1325 <i>Prononciation [did'-o-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner</li>\n<li>donner quelque chose à quelqu'un\n<ol type=\"a\">\n<li>de son propre accord</li>\n<li>accorder, répondre à une demande</li>\n<li>fournir les choses nécessaires</li>\n<li>donner, délivrer\n<ol>\n<li>des présents</li>\n<li>des écrits</li>\n<li>des instructions, commettre</li>\n</ol>\n</li>\n<li>donner ce qui est dû ou obligatoire, payer le salaire</li>\n</ol>\n</li>\n<li>se donner à quelqu'un de soi même\n<ol type=\"a\">\n<li>le suivre comme un maître</li>\n</ol>\n</li>\n<li>admettre ou permettre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίδωμι</b> <span>(<i>impf</i>. ἐδίδουν ; <i>f</i>. δώσω ; <i>ao.1</i> ἔδωκα <i>seul. à l’ind. ; ao.2</i> *ἔδων, <i>seul. au plur., d’où impér</i>. δός, <i>sbj</i>. δῶ, <i>opt</i>. δοίην, <i>inf</i>. δοῦναι, <i>part</i>. δούς ; <i>pf</i>. δέδωκα ; <i>pass. f</i>. δοθήσομαι, <i>ao</i>. ἐδόθην, <i>pf</i>. δέδομαι)</span><br><b>A <i>tr</i>.<br>   I</b> donner, <i>avec idée d’un don volontaire ou spontané, p. opp. à</i> ἀποδίδωμι ; <i>d’où :</i><br><b>      1</b> faire don de : τινί τι, OD. <i>24, 274,</i> de qqe ch. à qqn ; δωρεὰν δοῦναί τινι, DÉM. <i>323, 25,</i> faire un don à qqn ; χρήματα διδόναι τινί, DÉM. <i>260, 22,</i> donner de l’argent à qqn ; ταύτης ἦρχε τῆς χώρας, δόντος βασιλέως αὐτῷ, <i>etc</i>. THC. <i>1, 138,</i> il commandait à ce pays, le grand roi lui ayant fait don de (Magnésie, de Lampsaque, <i>etc.) ; en relat. avec</i> λαμϐάνω : δός τι καὶ λάϐε (<i>var</i>. λάϐοις) τι, PLAT. <i>Ax. 366</i> c, donne et prends qqe ch. ; δὸς λάϐε, ANTH. <i>9, 546,</i> donne et prends ; <i>particul</i>. donner en mariage, <i>d’ord. en parl. de la femme :</i> δ. θυγατέρα ἀνδρί, IL. <i>6, 192 ; 19, 291 ; ou simpl</i>. δ. θυγατέρα, IL. <i>11, 226 ;</i> θυγατέρα δ. τινὶ γυναῖκα, HDT. <i>1, 107 ; abs</i>. τινὶ δ. τινά, IS. <i>53, 26 ; ou simpl</i>. τινὰ δ. OD. <i>15, 367,</i> donner une fille en mariage à qqn ; <i>rar. en parl. de l’homme :</i> δ. κόρᾳ ἄνδρα, PD. <i>P. 9, 121,</i> donner un mari à une jeune fille ; <i>avec un inf</i>. δώσω σοι Χαρίτων μίαν ὀπυιέμεναι, IL. <i>14, 268,</i> je te donnerai pour compagne une des Grâces ; <i>abs</i>. ἐδίδοσαν καὶ ἤγοντο ἐξ ἀλλήλων, HDT. <i>5, 92,</i> ils se donnaient en mariage et épousaient les filles les uns des autres ; ὁ δοὺς καὶ γήμας, EUR. <i>Med. 288,</i> celui qui a donné en mariage et celui qui a épousé, <i>càd</i>. le beau-père et le gendre, <i>p. opp. à</i> γαμουμένη, l’épouse ;<br><b>      2</b> remettre de la main à la main : δ. ἐς χεῖρας λαϐεῖν, SOPH. <i>El. 1119,</i> remettre entre les mains (de qqn) ; δ. τεύχεα θεράποντι φορῆναι, IL. <i>7, 149,</i> donner à un serviteur ses armes à porter ;<br><b>      3</b> offrir : ἑκατόμϐας, IL. <i>12, 6 ;</i> ἱρὰ θεοῖσιν, OD. <i>1, 67,</i> des hécatombes, des sacrifices aux dieux ; <i>postér</i>. consacrer : οἱ δεδομένοι, ceux qui ont été consacrés (au service de Dieu), les ministres <i>ou</i> serviteurs du Temple, SPT. <i>Par. 1, 9, 2 ;</i><br><b>      4</b> servir, présenter : δ. πιεῖν, HDT. <i>4, 172 ;</i> ῥοφεῖν, AR. <i>fr. 10 ;</i> μασᾶσθαι, EUP. <i>2-1, 525 Meineke</i> donner à boire, à manger ;<br><b>      5</b> procurer : νίκην, IL. <i>7, 203 ;</i> κῦδος, IL. <i>16, 88, etc</i>. procurer la victoire, de la gloire, <i>etc. ; avec un adv</i>. δ. τινὶ εὖ, SOPH. <i>O.C. 642 ;</i> τινὶ εὖ δ. POL. <i>4, 21, 11,</i> procurer du bonheur <i>ou</i> être favorable à qqn ; τινὶ τὴν τύχην δ. εὖ, EUR. <i>I.A. 390,</i> procurer à qqn une heureuse fortune ; <i>ou abs. sans dat</i>. εὖ δ. EUR. <i>Alc. 1004, Or. 667,</i> procurer du bonheur ; τῆς τύχης εὖ διδούσης, SOPH. <i>O.R. 1081,</i> la fortune étant favorable ; <i>en mauv. part :</i> δ. ἄλγεα, IL. <i>1, 96 ;</i> πημονάς, ESCHL. <i>Pers. 292,</i> envoyer <i>ou</i> causer des souffrances, des douleurs (à qqn) ;<br><b>      6</b> livrer : τινὰ κυσίν, IL. <i>23, 21 ;</i> πυρί τινα, IL. <i>23, 183 ;</i> OD. <i>24, 65,</i> livrer qqn aux chiens, au feu ; ὀδύνῃσί τινα δ. IL. <i>5, 397 ;</i> OD. <i>17, 567 ; ou</i> ἀχέεσσι, OD. <i>19, 167,</i> livrer qqn aux souffrances, aux douleurs ; διδόναι τινά τινι, XÉN. <i>An. 6, 6, 31,</i> remettre une personne à une autre ; δ. ἑαυτόν τινι, HDT. <i>6, 108 ;</i> THC. <i>2, 68 ;</i> SOPH. <i>Ph. 84,</i> se remettre entre les mains de qqn ; <i>avec un inf</i>. τοῦτον ἔδωκεν ἐμοὶ ὑπήκοον εἶναι, XÉN. <i>An. 1, 6, 6</i> (mon père) me l’a donné pour qu’il m’obéisse ; ἐγὼ δέ σοι δίδωμι ἐμαυτὸν καὶ τοὺς ἐμοὺς τούτους ἑταίρους φίλους εἶναι πιστούς, XÉN. <i>An. 7, 3, 15,</i> nous nous livrons à toi mes compagnons que voici et moi-même pour être envers toi de fidèles amis ; <i>avec un n. de chose abstraite :</i> δ. ἑαυτὸν τοῖς δεινοῖς, DÉM. <i>258, 12 ;</i> εἰς κινδύνους, POL. <i>3, 17, 8,</i> s’exposer à des dangers ; δ. ἑαυτὸν εἰς ἔντευξιν, POL. <i>3, 15, 4,</i> se prêter à une entrevue ; εἰς τρυφήν, DS. <i>17, 108,</i> s’abandonner à la mollesse ; εἰς λῃστείας, DS. <i>18, 47,</i> se livrer à des actes de brigandage ;<br><b>      7</b> transmettre, enseigner : τέχνην ῥητορικήν, PLAT. <i>Phædr. 271</i> a, l’art de la rhétorique, <i>cf</i>. PLAT. <i>Rsp. 152</i> a, <i>etc. ;</i><br><b>      8</b> produire, fournir, apporter : δ. ὅρκον, DÉM. <i>1002, 3 ;</i> IS. <i>77, 16,</i> prêter serment ; δ. ψῆφον, DÉM. <i>542, 18 ;</i> γνώμην, DÉM. <i>704, 5,</i> donner son vote, son avis ; ἀκοὴν δ. τινί, SOPH. <i>El. 30,</i> prêter l’oreille à qqn ;<br><b>      9</b> accorder, concéder (un bienfait, une faveur, l’objet d’une demande, <i>etc.), particul. dans les vœux, les prières, etc. :</i> δός <i>avec un infin</i>. accorde (moi) de, <i>etc</i>. IL. <i>3, 351 ; avec une propos. infin</i>. accorde <i>ou</i> permets que, <i>etc</i>. IL. <i>3, 322 ;</i> ESCHL. <i>Ch. 18, etc. ; avec un dat. et un inf. :</i> τούτῳ εὐτυχεῖν δοῖεν θεοί, ESCHL. <i>Sept. 421,</i> puissent les dieux donner à celui-ci d’être heureux ; <i>dans une discussion,</i> concéder (à un interlocuteur, <i>etc</i>.) : εἴ μοι δίδως καὶ συγχωρεῖς εἶναι ταῦτα, PLAT. <i>Phæd. 100</i> b, si tu m’accordes cela et que tu conviennes qu’il en est ainsi :<br><b>      10</b> <i>p. suite,</i> permettre : λόγον τινὶ δ. XÉN. <i>Hell. 5, 2, 20,</i> donner la parole à qqn ; <i>en parl. de la loi :</i> νόμος αὐτῷ δέδωκε, <i>avec l’inf</i>. PLAT. <i>Leg. 813</i> c, la loi lui a permis de, <i>etc. ;</i> δέδοται ὑπὸ τοῦ νόμου, <i>avec l’inf</i>. PLAT. <i>Conv. 183</i> b, il est permis par la loi de, <i>etc. ;</i> δεδωκότων αὐτῷ τῶν νόμων, IS. <i>63, 8,</i> les lois le lui ayant permis :<br><b>      11</b> faire remise (d’une peine), remettre, <i>d’où</i> pardonner (une faute) : δ. τινί τι, DÉM. <i>274, 1 et 8,</i> pardonner qqe ch. à qqn :<br><b>      12</b> <i>postér</i>. ordonner : ἐδόθη αὐτοῖς ἵνα μή, <i>etc</i>. NT. <i>Apoc. 9, 5,</i> ordre leur fut donné de ne pas, <i>etc. ;</i><br><b>   II</b> (<i>au prés. et à l’impf</i>.) offrir de donner, consentir à donner : ὁμήρους οὐκ ἐδίδοσαν, XÉN. <i>An. 6, 1, 9,</i> ils ne voulaient pas donner d’otages ; <i>cf</i>. HDT. <i>3, 184 ; 5, 94 ;</i> XÉN. <i>Hell. 5, 3, 14 ;</i><br><b>B</b> <i>intr. en appar. (s.-e</i>. ἑαυτόν) se donner, s’abandonner, se livrer : ἡδονῇ, EUR. <i>Ph. 21 ;</i> ἡδοναῖς, PHILSTR. <i>496 et 512,</i> au plaisir ; δρόμῳ, ALCIPHR. <i>3, 47,</i> à la course ; εἰς δημοκοπίαν, DS. <i>Exc. 2, p. 567, 45</i>, se laisser aller à flatter le peuple.<br><span><b><span class=\"arrow\"></span></b> <i>Les formes de δίδωμι paraissent se rapporter à deux types de conjug</i>. *διδόω, δίδωμι :<br><b>   I</b> *διδόω, <i>prés. ind. 2 sg</i>. διδοῖς (<i>sel. Bkk</i>. δίδως) IL. <i>9, 164 ;</i> HDT. <i>8, 137 ; épq</i>. διδοῖσθα (<i>sel. Bkk</i>. διδώσθα) IL. <i>19, 270 ; 3 sg</i>. διδοῖ, OD. <i>17, 350 ;</i> PD. <i>I. 4, 33 ;</i> ESCHL. <i>Suppl. 1010 ;</i> HDT. <i>2, 48 ; 3, 119, etc. ; 3 pl</i>. διδοῦσι, IL. <i>19, 265, etc. ;</i> HDT. <i>2, 30 et 89 ;</i> DC. <i>65, 13, etc. Impér. 2 sg</i>. δίδου, OD. <i>3, 58 ;</i> HDT. <i>3, 140 ;</i> XÉN. <i>Hell. 3, 4, 26 ; éol</i>. δίδοι, PD. <i>O. 1, 85 ; 6, 104 ; 7, 89 ; N. 5, 50. Inf</i>. διδοῦν, THGN. <i>1329 ; épq</i>. διδοῦναι, IL. <i>24, 425. — Impf. 1 sg</i>. ἐδίδουν, HDT. <i>6, 86 ;</i> ATT. (AR. <i>Eq. 678 ;</i> AND. DÉM. <i>etc.) ; 2 sg</i>. ἐδίδους (ἐδίδως <i>Bkk</i>.) OD. <i>19, 367 ;</i> XÉN. <i>An. 5, 8, 4 ; 3 sg</i>. ἐδίδου (ἐδίδω <i>Bkk</i>.) OD. <i>11, 289 ;</i> HÉS. <i>Th. 563 ;</i> PD. <i>P. 9, 117 ;</i> HDT. <i>1, 208 ; 3, 128 ;</i> ATT. (THC. <i>8, 29 ;</i> XÉN. <i>Cyr. 8, 2, 17 ; etc.) ; poét</i>. δίδου (δίδω <i>Bkk</i>.) IL. <i>5, 165 ; 6, 192, 219 ; 3 pl</i>. ἐδίδουν, HÉS. <i>O. 139 ;</i> HPC. <i>8, 446 Littr. ;</i> DH. <i>5, 6. — Fut</i>. διδώσω, OD. <i>13, 358 ; inf</i>. διδώσειν, OD. <i>24, 313. ;</i><br><b>   II</b> <i>de</i> δίδωμι : <i>Act. prés. ind. 1 sg</i>. δίδωμι, IL. <i>23, 620 ;</i> HDT. <i>3, 140 ; 2 sg</i>. δίδως, ATT. (SOPH. <i>Aj. 1354 ;</i> PLAT. <i>Phæd. 100 etc.) ; 3 sg</i>. δίδωσι, IL. <i>20, 299 ;</i> PD. <i>P. 5, 65 ;</i> ATT. (THC. <i>2, 101, etc.) ; 1 pl</i>. δίδομεν, IL. <i>2, 228 ;</i> AR. <i>Eq. 69, etc. ; postér. (p. anal. avec</i> διδόασι) διδόαμεν, JOS. <i>A.J. 11, 5 ;</i> GAL. <i>11, 349 ; 2 pl</i>. δίδοτε, XÉN. <i>Cyr. 4, 6, 13 ; etc. ; 3 pl</i>. διδόασι, <i>seule forme att</i>. THC. <i>1, 42 ;</i> AR. <i>Vesp. 715, etc. (un seul ex. att. de</i> διδοῦσι, <i>mais dout</i>. ANTIPH. <i>dans Com. fr. 3, 85). Impér. 2 sg. épq</i>. δίδωθι (<i>p</i>. δίδοθι) OD. <i>3, 380 ; 3 sg</i>. διδότω, PLAT. <i>Leg. 916 ; 2 pl</i>. δίδοτε, XÉN. <i>Cyr. 4, 5, 47. Sbj. 2 sg</i>. διδῷς, EUR. <i>Hel. 1257, etc. ; 3 sg</i>. διδῷ, AR. <i>Av. 519, etc. ; 3 pl</i>. διδῶσι, SOPH. <i>fr. 748. Opt</i>. διδοίην, LYS. <i>7, 6 Baiter-Sauppe ;</i> -οίης, SOPH. <i>O.C. 642 ;</i> -οίη, HDT. <i>1, 86 ;</i> ATT. (SOPH. <i>O.C. 777 ;</i> XÉN. <i>Vect. 2, 6, etc.) ; postér</i>. -ῴη, PLUT. <i>Lys. 9 ; 1 pl. inus. ; 2 pl</i>. -οίητε, PLUT. <i>Alex. 32 ; ou</i> -οῖτε, OD. <i>11, 359 ; 3 pl</i>. -οῖεν, XÉN. <i>An. 3, 2, 7, etc. Inf</i>. διδόναι, HDT. <i>6, 62 ;</i> THC. <i>2, 7, 97, etc. ; poét</i>. διδόμεν, PD. <i>N. 7, 97 ; I. 8, 60. Part</i>. διδούς, IL. <i>9, 699 ;</i> AND. <i>2, 23 Baiter-Sauppe. — Impf</i>. *ἐδίδων, ἐδίδως, ἐδίδω <i>ou</i> δίδω (<i>v. ci-dessus</i> *διδόω) ; <i>2 pl</i>. ἐδίδοτε, SOPHIL. (<i>Com. fr. 3, 581) ; 3 pl</i>. ἐδίδοσαν, HDT. <i>8, 9 ;</i> ATT. (THC. <i>7, 87, etc.) ; poét</i>. δίδοσαν, OD. <i>17, 367 ; épq</i>. ἔδιδον, HH. <i>Cer. 437 ou</i> δίδον, <i>ibid. 327. — Particularités des autres temps : Fut. épq</i>. διδώσω (<i>v. ci-dessus</i> *διδόω) ; <i>fut. dor</i>. δωσῶ, THCR. <i>Idyl. 5, 96 ; inf. épq</i>. δωσέμεναι, IL. <i>13, 369 ; ou</i> δωσέμεν (δώσειν <i>Bkk</i>.) IL. <i>10, 323 ; 22, 117. — Ao.1</i> ἔδωκα (<i>seul. ind</i>.) OD. <i>9, 361,</i> HDT. <i>1, 124 ;</i> ATT. (SOPH. <i>Ant. 902, etc.) ; poét</i>. δῶκα, IL. <i>4, 43 ; 2 sg</i>. ἔδωκας, IL. <i>21, 473, etc. ; poét</i>. δῶκας, OD. <i>4, 467 ; 3 sg</i>. ἔδωκε, IL. <i>11, 243, etc. ; poét</i>. δῶκε, IL. <i>5, 2 ;</i> HÉS. <i>O. 705 ;</i> PD. <i>O. 1, 63 ;</i> 'δωκεν, SOPH. <i>Aj. 1303 ; 1 pl</i>. ἐδώκαμεν, XÉN. <i>An. 3, 2, 5, etc. ; 2 pl</i>. ἐδώκατε, ALEX. (<i>Com. fr. 3, 479), etc. ; 3 pl</i>. ἔδωκαν, IL. <i>13, 303 ; 22, 379 ;</i> HÉS. <i>O. 92 ;</i> XÉN. <i>Mem. 1, 1, 9, etc. ; poét</i>. δῶκαν, HÉS. <i>O. 741 ;</i> PD. <i>P. 4, 115. — Ao.2</i> *ἔδων, <i>inus. au sg. ; 1 pl</i>. ἔδομεν, AR. <i>Vesp. 586, etc. ; poét</i>. δόμεν, IL. <i>17, 443 ; 2 pl</i>. ἔδοτε, AND. <i>2, 22 ;</i> LYS. <i>19, 21 ;</i> ESCHN. <i>3, 187 Baiter-Sauppe ; 3 pl</i>. ἔδοσαν, OD. <i>20, 78 ;</i> HÉS. <i>Th. 141 ;</i> PD. <i>N. 6, 10 ;</i> HDT. <i>6, 108 ;</i> ATT. (THC. <i>4, 56, etc.) ; poét</i>. δόσαν, OD. <i>7, 242 ;</i> THGN. <i>463 ; épq</i>. ἔδον, HÉS. <i>Th. 30. De cet ao.2 : Impér</i>. δός, δότω, δότε, δότωσαν (XÉN. <i>Hier. 8, 4) ou</i> δόντων (PLAT. <i>Leg. 753</i> a). <i>Sbj</i>. δῶ (OD. <i>20, 296 ;</i> XÉN. <i>Cyr. 8, 4, 16, etc</i>.) δῷς, δῷ, δῶμεν, δῶτε, δῶσι ; <i>sbj. épq. 3 sg</i>. δώῃ, IL. <i>6, 527 ; 7, 81 ; 16, 725 ; ou</i> δώῃσι, IL. <i>1, 324 ; 12, 275 ; ou</i> δῷσι, OD. <i>2, 144 ; 1 pl</i>. δώομεν, IL. <i>7, 299 ; 3 pl</i>. δώωσι, IL. <i>1, 137 ; 9, 278 ;</i> HÉS. <i>Th. 222 ;</i> A. RH. <i>1, 1293. Opt</i>. δοίην, -ης, -η, -ημεν (<i>ou</i> δοῖμεν) IL. <i>13, 378 ;</i> PLAT. <i>Rsp. 607 ;</i> -ητε, -ησαν, DAMOX. (<i>Com. fr. 4, 532) ou</i> δοῖεν, IL. <i>23, 650 ;</i> XÉN. <i>An. 4, 8, 7, etc. Inf</i>. δοῦναι, IL. <i>23, 593 ;</i> SOPH. <i>Ant. 303, etc. ; poét</i>. δόμεναι, IL. <i>19, 138, ou</i> δόμεν, IL. <i>9, 571 ;</i> HÉS. <i>O. 354 ;</i> AR. <i>Av. 930, 973 ; dor</i>. PD. <i>N. 8, 20 ;</i> THC. <i>5, 77 ;</i> AR. <i>Lys. 1163 ;</i> δοῦν, PHŒN. COL. <i>1, 20 Schneidew. Part</i>. δούς, OD. <i>15, 369, etc. — Ao.2 itér</i>. δόσκον, IL. <i>14, 382. — Pl.q.pf. 3 sg. ion</i>. ἐδεδώκεε, HDT. <i>8, 67</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *d(e)h₃-, donner, <i>avec redoubl. ; cf. lat</i>. dă-re, <i>sscr</i>. dádāti.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διδωμι - δίδωμι</font>\n<br><br>forme d'un verbe primaire, utilisé avec ses alternatives à la plupart des temps</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> « donner » en général, opposé à  « prendre » ;\n<br><br> est spécifique, « donner, accorder, présenter » ;\n<br><br> peut être utilisé même pour des maux ; mais  pourrait être utilisé seulement ironiquement pour de telles choses</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n413 fois dans 377 versets de 22 livres bibliques (NT)\n<ul>\n<li>Matthieu (56)</li>\n<li>Marc (38)</li>\n<li>Luc (60)</li>\n<li>Jean (75)</li>\n<li>Actes (35)</li>\n<li>Romains (9)</li>\n<li>1 Corinthiens (15)</li>\n<li>2 Corinthiens (13)</li>\n<li>Galates (6)</li>\n<li>Ephésiens (12)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (4)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (6)</li>\n<li>Tite (1)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (6)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (7)</li>\n<li>Apocalypse (57)</li>\n</ul>\n</td></tr>\n</table>","G1326":"<h1>diegeiro</h1>\n<p>Strong n° 1326 <i>Prononciation [dee-eg-i'-ro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>s'éveiller, se réveiller (d'un sommeil)\n<ol type=\"a\">\n<li>de la mer, qui commence à s'agiter, à se lever</li>\n<li>métaph :\n<ol>\n<li>réveiller l'esprit</li>\n<li>remuer, rendre actif</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·εγείρω</b> <span>(<i>f</i>. ερῶ)</span><br><b>      1</b> réveiller, HPC. <i>1277, 37 ;</i> HDN <i>2, 1, 13 ;</i> LGS <i>2, 35 ;</i> ANTH. <i>11, 171 ; fig</i>. δ. τὴν αὔξησιν φυτοῦ, GEOP. <i>9, 3,</i> favoriser la croissance d’une plante ; <i>au mor</i>. exciter, encourager, SPT. <i>2Macc. 7, 21 ;</i><br><b>      2</b> <i>p. anal</i>. dresser, élever : πύλας, SPT. <i>Judith 1, 4,</i> des portes ;<br><b><i>Moy.</i></b> (<i>ao.2</i>) se réveiller, ANTH. <i>5, 275 (3 sg</i>. διέγρετο) ; <i>5, 259</i>.<br><span><b>Étym</b>. <i>part. fém</i>. διεγρομένης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-εγειρω - διεγείρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G1327":"<h1>diexodos</h1>\n<p>Strong n° 1327 <i>Prononciation [dee-ex'-od-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une route qui traverse, sortie\n<ol type=\"a\">\n<li>littéralement : les routes qui sortent des routes</li>\n<li>lieu où la route se termine à l'entrée de la ville, issues des grandes routes</li>\n<li>frontières de pays</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·έξοδος, ου (ἡ) :<br>A</b> conduit de sortie, issue :<br><b>   I</b> <i>au propre :</i><br><b>      1</b> <i>en gén</i>. HDT. <i>3, 117 ;</i> PLAT. <i>Tim. 84</i> d ; <i>particul</i>. point où l’on sort d’un pays, <i>d’où</i> limite, frontière, SPT. <i>Num. 34, 4, 5 ; Jos. 15, 7 ;</i><br><b>      2</b> passage pour les excréments, HPC. <i>756</i> g ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> moyen d’échapper, PLAT. <i>Rsp. 405</i> c ;<br><b>      2</b> issue (d’une entreprise, <i>etc</i>.) POL. <i>2, 1, 3 ; 23, 2, 2 ;</i><br><b>B</b> trajet, évolution :<br><b>   I</b> <i>au propre :</i> PLAT. <i>Phædr. 247</i> a ; ἡλίου, EUR. <i>Andr. 1087 (cf</i>. HDT. <i>2, 24</i>) ; πλανητῶν, ARSTT. <i>Mund. 6,</i> évolution du soleil, des planètes ; ἀνέμων, SOPH. <i>fr. 424,</i> évolution des vents ; <i>particul. t. milit</i>. διέξοδοι τακτικαί, PLAT. <i>Leg. 813</i> e, mouvements de troupes ; <i>d’où en gén</i>. expédition ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> développement d’un discours, exposition, description, PLAT. <i>Prot. 326</i> a, <i>361</i> d, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> détail (d’un plan, <i>etc</i>.) HDT. <i>3, 136 ;</i> κατὰ διέξοδον, ARSTD. <i>t. 2, 481,</i> en détail.<br><span><b>Étym</b>. διά, ἔξοδος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-εξοδος - διέξοδος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1328":"<h1>diermeneutes</h1>\n<p>Strong n° 1328 <i>Prononciation [dee-er-main-yoo-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un interprète, exégète, traducteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διερμηνευτής, οῦ (ὁ)</b> interprète, NT. <i>1Cor. 14, 28 ;</i> CHRYS. <i>3, 485</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διερμηνευτης - διερμηνευτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1329":"<h1>diermeneuo</h1>\n<p>Strong n° 1329 <i>Prononciation [dee-er-main-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>montrer le sens de ce qui est dit, expliquer, exposer</li>\n<li>traduire dans un autre langage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ερμηνεύω</b>, interpréter, expliquer, POL. <i>3, 22, 3 ;</i> SPT. <i>2Macc. 1, 36 ;</i> PHIL. <i>1, 226, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διερμηνευω - διερμηνεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G1330":"<h1>dierchomai</h1>\n<p>Strong n° 1330 <i>Prononciation [dee-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller, passer\n<ol type=\"a\">\n<li>marcher, voyager, passer dans un lieu</li>\n<li>prendre la route, traverser une région</li>\n</ol>\n</li>\n<li>aller en différents lieux\n<ol type=\"a\">\n<li>du peuple : aller au loin</li>\n<li>d'un bruit, d'une rumeur : s'étendre, se répandre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·έρχομαι</b> <span>(<i>f</i>. δίειμι, <i>ao.2</i> διῆλθον, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> aller à travers, traverser, <i>abs</i>. IL. <i>23, 876 ; avec un acc</i>. δ. πῶϋ, IL. <i>3, 198, etc</i>. traverser un troupeau ; τὴν Θετταλίαν, POL. <i>4, 61, 1,</i> traverser la Thessalie ; θύρας, LYS. <i>121, 7,</i> passer à travers des portes ; <i>avec le gén</i>. OD. <i>6, 304, etc. ;</i> δ. διὰ νήσου, HDT. <i>6, 31,</i> traverser une île ; <i>avec un suj. de chose : fig</i>. κἀμὲ γὰρ διῆλθέ τι, EUR. <i>Suppl. 288,</i> car moi aussi, qqe chose m’a été jusqu’au cœur, m’a ému ; βάξις διῆλθ' Ἀχαιούς, SOPH. <i>Aj. 999,</i> un bruit se répandit parmi les Grecs ; <i>abs</i>. λόγος διῆλθε, THC. <i>6, 46 ;</i> XÉN. <i>An. 1, 4, 7 ;</i> PLUT. <i>Alc. 2,</i> un bruit se répandit ;<br><b>      2</b> parcourir jusqu’au bout : ὁδόν, HDT. <i>3, 25, etc</i>. accomplir un voyage ; <i>fig</i>. τὸν βίον, PLAT. <i>Gorg. 523</i> a, <i>Rsp. 365,</i> passer sa vie entière ; παιδείαν, XÉN. <i>Cyr. 1, 5, 1,</i> recevoir une éducation complète ; <i>en parl. de discours,</i> parcourir tout au long, exposer en détail, <i>acc</i>. PD. <i>N. 4, 117 ;</i> PLAT. <i>Crit. 48</i> b ; DÉM. <i>175, 23 ; d’où</i> discourir : περί τινος, PLAT. <i>Prot. 347</i> a ; ISOCR. <i>54</i> a ; ὑπέρ τινος, POL. <i>1, 13, 10,</i> sur qqe ch. ; τι πρός τινα, PLUT. <i>Æmil. 31,</i> exposer longuement qqe ch. à qqn ;<br><b>      3</b> parcourir, <i>en gén. :</i> ἃ διῆλθον, THC. <i>1, 21,</i> les événements (anciens) que je viens d’esquisser ;<br><b>   II <i>intr.</i></b> passer, s’écouler, <i>en parl. du temps,</i> HDT. <i>1, 8 ;</i> DÉM. <i>25, 14 ;</i> POL. <i>20, 10, 17 ; etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διερχομαι - διέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 41 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (10)</li>\n<li>Jean (1)</li>\n<li>Actes (21)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1331":"<h1>dierotao</h1>\n<p>Strong n° 1331 <i>Prononciation [dee-er-o-tah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>demander pour\n<ol type=\"a\">\n<li>demander beaucoup, une chose après l'autre</li>\n<li>trouver suite à une demande, s'informer, s'enquérir</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ερωτάω-ῶ :<br>      1</b> interroger en détail : τινα, PLAT. <i>Gorg. 458</i> a, <i>etc. ;</i> XÉN. <i>Cyr. 1, 3, 15,</i> qqn ; τινά τι, PLAT. <i>Prot. 315</i> c, qqn sur qqe ch. ;<br><b>      2</b> interroger avec persistance, ne cesser de questionner, DÉM. <i>34, 22</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διερωταω - διερωτάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1332":"<h1>dietes</h1>\n<p>Strong n° 1332 <i>Prononciation [dee-et-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de deux ans, âgé de deux ans</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ετής, ής, ές :<br>      1</b> qui dure deux ans, HDT. <i>2, 2 ;</i> ARSTT. <i>G.A. 4, 10 ;</i> DH. <i>8, 2 ;</i> SPT. <i>2Macc. 10, 3 ;</i> LGS <i>1, 4 ;</i> ἐπὶ διετὲς ἡϐᾶν, ESCHN. <i>70, 42 ;</i> DÉM. <i>1135,</i> dépasser de deux ans l’âge de l’adolescence, <i>càd</i>. avoir 18 ans ;<br><b>      2</b> âgé de deux ans, ARSTT. <i>H.A. 2, 1, 37, etc</i>.<br><span><b>Étym</b>. δίς, ἔτος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διετης - διετής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1333":"<h1>dietia</h1>\n<p>Strong n° 1333 <i>Prononciation [dee-et-ee'-a]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>l'espace de deux ans</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διετία, ας (ἡ)</b> durée de deux ans, NT. <i>Ap. 24, 27 ; 28, 3</i>.<br><span><b>Étym</b>. διετής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διετια - διετία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1334":"<h1>diegeomai</h1>\n<p>Strong n° 1334 <i>Prononciation [dee-ayg-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>amener une narration jusqu'à sa fin</li>\n<li>raconter, relater en entier, décrire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ηγέομαι-οῦμαι</b>, exposer en détail, raconter, décrire : τι, AR. <i>Av. 198 ;</i> PLAT. <i>Conv. 172</i> c ; LUC. <i>H. conscr. 30, 57,</i> qqe ch. ; τινα, PLAT. <i>Theæt. 144</i> c, qqn.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διηγεομαι - διηγέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT).\n<ul>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1335":"<h1>diegesis</h1>\n<p>Strong n° 1335 <i>Prononciation [dee-ayg'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une narration, un récit, relation, histoire</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διήγησις, εως (ἡ)</b> récit, narration, exposition, PLAT. <i>Phædr. 266</i> e, <i>Rsp. 392</i> d ; ARSTT. <i>Rhet. 3, 16 ;</i> POL. <i>3, 36, 4</i>.<br><span><b>Étym</b>. διηγέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διηγησις - διήγησις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1336":"<h1>dienekes</h1>\n<p>Strong n° 1336 <i>Prononciation [dee-ay-nek-es']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>continuellement, pour toujours, permanent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ηνεκής, ής, ές</b>, qui se continue sans interruption, continu ; ῥάϐδοι, IL. <i>12, 297,</i> baguettes tout d’une pièce, <i>càd</i>. longues et solides ; ῥίζαι, IL. <i>12, 134,</i> racines qui se prolongent, <i>càd</i>. longues, étendues ; ὦλξ δ. OD. <i>18, 375,</i> sillon continu ; ὄρος δ. STR. <i>137,</i> chaîne de montagnes continue ; <i>en parl. du temps,</i> ARSTT. <i>Plant. 1, 4, 4 ;</i> A. RH. <i>2, 391 ;</i> νύξ, LUC. <i>V.H. 1, 19,</i> nuit continuelle, longue ; νόμος, PLAT. <i>Leg. 839</i> a, loi d’un effet durable ; ἐς τὸ διηνεκές, APP. <i>Civ. 1, 4,</i> pour toujours.<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. διαν- <span>[ᾱ]</span> PLAT. <i>Hipp. ma. 301 b et e (vulg</i>. διην-) ; ANAXANDR. (ATH. <i>455</i> f).<br><span><b>Étym</b>. διά, ἐνεγκεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διηνεκης - διηνεκής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (4)</li>\n</ul>\n</td></tr>\n</table>","G1337":"<h1>dithalassos</h1>\n<p>Strong n° 1337 <i>Prononciation [dee-thal'-as-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ressemblant ou formant deux mers</li>\n<li>espace entre deux mers, bordé des deux côtés par la mer\n<ol type=\"a\">\n<li>un isthme ou langue de terre, l'extrémité qui est recouverte par les vagues</li>\n<li>un récif contre lequel les vagues de jettent de tous les côtés</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·θάλασσος</b>, <i>att</i>. <b>-ττος, ος, ον</b> <span>[ῐᾰλ]</span><br><b>      1</b> baigné par deux mers, NT. <i>Ap. 27, 41 ;</i><br><b>      2</b> qui se partage en deux mers, STR. <i>124 ;</i> DP. <i>156 ;</i><br><b>      3</b> où se rencontrent deux courants, <i>en parl. des Syrtes,</i> D. CHR. <i>1, 190 Reiske</i>.<br><span><b>Étym</b>. δίς, θάλασσα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διθαλασσος - διθάλασσος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1338":"<h1>diikneomai</h1>\n<p>Strong n° 1338 <i>Prononciation [dee-ik-neh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>passer par, pénétrer à travers, percer, pénétrer par une chose jusqu'à une autre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ϊκνέομαι-οῦμαι</b> <span>(<i>f</i>. διΐξομαι, <i>ao.2</i> διϊκόμην)</span><br><b>      1</b> passer par, pénétrer à travers : διά τινος ποτί τι, T. LOCR. <i>101</i> a, pénétrer par une chose jusqu’à une autre ; εἴς τι, TH. <i>C.P. 3, 6, 1,</i> jusqu’à qqe ch. ; μέχρι τινός, PLUT. <i>Dem. 20 ;</i> D. CHR. <i>1, 389,</i> parvenir jusqu’à qqn ; <i>abs</i>. PLUT. <i>Nic. 27 ;</i><br><b>      2</b> parcourir par la parole, raconter, IL. <i>9, 61 ; 19, 186</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut</i>. διΐξομαι, IL. <i>9, 61 ;</i> HH. <i>Cer. 416. Ao.2, 2 sg</i>. διΐκεο, IL. <i>19, 186 ;</i> A. RH. <i>2, 411. Pl.q.pf. 3 sg</i>. διῗκτο, PLUT. <i>Dem. 20</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-ικνεομαι - διϊκνέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1339":"<h1>diistemi</h1>\n<p>Strong n° 1339 <i>Prononciation [dee-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre séparément, mettre en morceaux, disjoindre</li>\n<li>se tenir à part, partir, se séparer, s'éloigner de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ΐστημι :<br>A</b> <i>tr. (aux temps suiv. prés., impf., f</i>. διαστήσω, <i>ao.1</i> διέστησα) ;<br><b>   I. 1</b> établir de côté et d’autre : τοὺς λόχους, THC. <i>4, 74,</i> porter ses bataillons de différents côtés ;<br><b>      2</b> établir de distance en distance : κίονες διεστάθησαν, CALLIX. (ATH. <i>196</i> b) des colonnes avaient été placées de distance en distance ;<br><b>   II</b> <i>p. suite</i> :<br><b>      1</b> séparer : κατ' εἴδη, PLAT. <i>Phil. 23</i> d ; εἰς μέρη, DÉM. <i>245, 23,</i> en espèces, en parties ; τι ἀπό τινος, PLUT. <i>M. 662</i> b ; τί τινος, ATH. <i>303</i> d, séparer une chose d’une autre ; τινά τινος, PLUT. <i>Ant. 84 ;</i> τινὰ ἀπό τινος, DH. <i>9, 17,</i> une personne d’une autre ; <i>fig</i>. τὴν Ἑλλάδα, HDT. <i>9, 2,</i> désunir la Grèce ; τινά τινος, AR. <i>Vesp. 41 ;</i> THC. <i>6, 77,</i> détacher une personne d’une autre ;<br><b>      2</b> distinguer : τί τινος, ATH. <i>303</i> d, une chose d’une autre ;<br><b>B</b> <i>intr. (aux temps suiv. : ao.2</i> διέστην, <i>pf</i>. διέστηκα, <i>pl.q.pf</i>. διειστήκειν) :<br><b>      1</b> se séparer, s’écarter : τὰ διεστεῶτα, HDT. <i>7, 129,</i> déchirures du sol ;<br><b>      2</b> <i>p. ext</i>. s’éloigner, se retirer, <i>en parl. d’une armée qui se retire devant une autre,</i> POL. <i>10, 3, 6 ;</i> διέστησαν χωρίς, HDT. <i>8, 16,</i> ils se retirèrent chacun de son côté ;<br><b>      3</b> s’établir de distance en distance, THC. <i>4, 32 ;</i><br><b>      4</b> se désunir, être désuni : διαστήτην ἐρίσαντε, IL. <i>1, 6,</i> ils se brouillèrent après s’être querellés ; ἡ Πελοπόννησος ἅπασα διειστήκει, DÉM. <i>231, 5,</i> tout le Péloponnèse était divisé ;<br><b>      5</b> <i>fig</i>. être éloigné de, <i>gén</i>. LGN <i>8, 2 ; d’où</i> être différent : πλούτου ἀρέτη διέστηκεν, PLAT. <i>Rsp. 550</i> e, la vertu est en opposition avec la fortune ; διέστηκε πρὸς ἄλληλα, ARSTT. <i>Pol. 1, 5, 8</i> (le mâle et la femelle) sont différents l’un de l’autre ;<br><b><i>Moy</i>. διΐσταμαι</b> <span>(<i>impf</i>. διϊστάμην, <i>f</i>. διαστήσομαι)</span><br><b>   I <i>tr</i>.<br>      1</b> établir de côté et d’autre : ἀράχνια λεπτά, THCR. <i>Idyl. 16, 96,</i> tendre de côté et d’autre des toiles minces, <i>en parl. d’araignées ;</i><br><b>      2</b> <i>p. suite,</i> séparer, distinguer, PLAT. <i>Tim. 63, etc. ;</i><br><b>   II <i>intr.</i></b> s’écarter, se séparer : θάλασσα διΐστατο, IL. <i>13, 29,</i> la mer s’écartait (s’entrouvrait).<br><span><b><span class=\"arrow\"></span></b> <i>Impf. 3 sg</i>. διΐστη, PLUT. <i>Pomp. 19. Ao.2 part. neutre</i> διαστάν, SOPH. <i>O.C. 1662. Pl.q.pf. 3 sg</i>. διειστήκει, <i>v. ci-dessus</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-ιστημι - διΐστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1340":"<h1>diischurizomai</h1>\n<p>Strong n° 1340 <i>Prononciation [dee-is-khoo-rid'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appuyer sur</li>\n<li>affirmer fortement, avec confiance</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ϊσχυρίζομαι</b> <span>(<i>impf</i>. διϊσχυριζόμην)</span> <span>[ῡ]</span><br><b>      1</b> insister fortement sur, <i>dat</i>. ANT. <i>133, 20 ;</i><br><b>      2</b> soutenir avec force, affirmer fortement : τι, PLAT. <i>Phæd. 63</i> c, qqe ch. ; περί τινος, AND. <i>20, 14 ;</i> LYS. <i>138, 3,</i> au sujet de qqe ch. <i>ou</i> de qqn ; <i>avec une prop. inf</i>. PLAT. <i>Phæd. 114</i> d ; <i>avec</i> ὅτι, LYS. <i>133 ;</i> DÉM. <i>447, 25,</i> affirmer que ; περί τινος ὡς, PLAT. <i>Ep. 317</i> c, affirmer au sujet de qqn que, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-ισχυριζομαι - διϊσχυρίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1341":"<h1>dikaiokrisia</h1>\n<p>Strong n° 1341 <i>Prononciation [dik-ah-yok-ris-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un juste jugement (comme celui de Dieu)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαιοκρισία, ας (ἡ)</b> <span>[ῐρῐ]</span> jugement équitable, NT. <i>Rom. 2, 5</i>.<br><span><b>Étym</b>. δικαιοκρίτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιοκρισια - δικαιοκρισία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1342":"<h1>dikaios</h1>\n<p>Strong n° 1342 <i>Prononciation [dik'-ah-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>juste, qui observe la loi divine\n<ol type=\"a\">\n<li>au sens large : droit, juste, vertueux, gardant les commandements de Dieu\n<ol>\n<li>les propres justes, qui sont justes à leurs propres yeux, fiers de leurs vertus, qu'elles soient réelles ou imaginaires</li>\n<li>non fautif, innocent</li>\n<li>ceux dont les pensées, les paroles, les actions sont entièrement conformes à la volonté de Dieu, qui n'ont pas besoin de modifier leur cœur ou leur vie\n<ol type=\"a\">\n<li>en réalité : seulement Christ</li>\n</ol>\n</li>\n<li>approuvé ou accepté de Dieu</li>\n</ol>\n</li>\n<li>sens plus étroit : rendre à chacun selon son dû, dans un sens judiciaire, porter un juste jugement sur les autres</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίκαιος, α</b> <i>ou</i> <b>ος, ον</b> <span>[ῐ]</span><br><b>A</b> conforme aux convenances, au droit :<br><b>   I</b> <i>en parl. de pers</i>. observateur de la règle, <i>particul. :</i><br><b>      1</b> qui remplit ses devoirs envers les dieux et les hommes, honnête, juste, OD. <i>3, 52, etc. ; p. opp. à</i> δυσσεϐής, ESCHL. <i>Sept. 598 ;</i><br><b>      2</b> humain, civilisé, IL. <i>11, 832 ; 13, 6 ; particul</i>. qui pratique l’hospitalité, OD. <i>9, 175 ;</i><br><b>   II</b> <i>en parl. d’actions,</i> juste, honnête, convenable, OD. <i>18, 414, etc. ; subst</i>. τὸ δίκαιον, HÉS. <i>O. 224 ;</i> HDT. <i>7, 137 ;</i> ESCHL. <i>Sept. 1073 ;</i> SOPH. <i>Ph. 1251 ;</i> DÉM. <i>211 extr. ; 1291, 11 ;</i> τὰ δίκαια, AR. <i>Ach. 645, 655 ; Eq. 510, etc</i>. le droit, la justice ; ἐκ τοῦ δ. selon la justice, AR. <i>Av. 1435 ; ou</i> d’après une induction légitime, THC. <i>2, 89 ;</i> μετὰ τοῦ δ. LYS. <i>191, 33,</i> selon la justice ; ξὺν τῷ δικαίῳ, SOPH. <i>Ph. 1251,</i> ayant la justice avec moi, de mon côté ; τὰ δ. πράττεσθαί τινα, ESCHL. <i>Ag. 812,</i> infliger à qqn le traitement mérité, un juste châtiment ; τὰ δ. les droits et les devoirs de chacun : τὰ πρὸς ἀλλήλους δίκαια, POL. <i>3, 21, 10,</i> les obligations mutuelles ;<br><b>B</b> <i>p. ext. :</i><br><b>   I</b> conforme à la règle :<br><b>      1</b> <i>en parl. de pers. :</i> δ. πολίτης, DÉM. <i>34, 15,</i> citoyen régulier, véritable citoyen ; δ. συγγραφεύς, LUC. <i>H. conscr. 39,</i> véritable écrivain ;<br><b>      2</b> <i>en parl. d’animaux :</i> ἵππον δ. ποιεῖσθαί τινι, XÉN. <i>Mem. 4, 4, 5,</i> rendre un cheval propre au service de qqn ;<br><b>      3</b> <i>en parl. de choses :</i> σχῆμα σώματος δ. HPC. <i>Art. 832,</i> corps bien proportionné ; ἅρμα δ. XÉN. <i>Cyr. 2, 2, 26,</i> char bien équilibré ; <i>d’où</i> parfait, excellent, PLUT. <i>M. 669</i> d ;<br><b>      4</b> <i>en parl. de nombres :</i> ἑκατὸν ὀργυιαὶ δ. HDT. <i>2, 149,</i> cent arpents juste ;<br><b>   II</b> δίκαιός εἰμι, <i>avec l’inf. au sens de</i> δίκαιόν ἐστιν ἐμέ, <i>avec l’inf</i>. il est juste que je…, <i>d’où :</i><br><b>      1</b> j’ai le droit de : δ. εἰμι κολάζειν, AR. <i>Nub. 1434,</i> j’ai le droit de punir ; δ. εἰσιν ἀπιστότατοι εἶναι, THC. <i>4, 17,</i> ils ont le droit d’être très défiants ;<br><b>      2</b> je suis digne de, je mérite de, <i>en mauv. part :</i> δ. ἐστιν ἀπολωλέναι, DÉM. <i>74, 26,</i> il mérite de périr ;<br><b>      3</b> j’ai le devoir de : δ. ἐστε ἰέναι, HDT. <i>9, 60,</i> il est convenable que vous alliez, vous devez aller ; <i>qqf. en ces divers sens</i> δίκαιόν ἐστιν, <i>avec la prop. inf</i>. HDT. <i>1, 39 ;</i> ESCHL. <i>Pr. 11, ou</i> δίκαια (<i>s.-e</i>. ἐστιν) SOPH. <i>Aj. 1126, etc</i>.<br><span>•<i> Cp</i>. -ότερος, IL. <i>19, 181 ;</i> LUC. <i>Cal. 27</i>. <i>• Sup</i>. -ότατος, IL. <i>11, 832 ; 13, 6 ;</i> HDT. <i>3, 148 ;</i> XÉN. <i>Cyr. 8, 3, 15 ;</i> PLAT. <i>Conv. 172</i> b, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, EUR. <i>Her. 901, I.T. 1202 ;</i> DS. <i>5, 72 ;</i> <span>[-αι-]</span> <i>bref dans une inscr. att</i>. KE. <i>95, 4 (3<sup>e</sup> siècle av. J.C</i>.).<br><span><b>Étym</b>. δίκη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιος - δίκαιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n80 fois dans 75 versets de 20 livres bibliques (NT)\n<ul>\n<li>Matthieu (18)</li>\n<li>Marc (2)</li>\n<li>Luc (11)</li>\n<li>Jean (3)</li>\n<li>Actes (6)</li>\n<li>Romains (7)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (2)</li>\n<li>Colossiens (1)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (6)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G1343":"<h1>dikaiosune</h1>\n<p>Strong n° 1343 <i>Prononciation [dik-ah-yos-oo'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sens large : état de celui qui est comme il doit être, justice, la condition acceptable par Dieu\n<ol type=\"a\">\n<li>doctrine concernant le chemin pour atteindre un état approuvé par Dieu</li>\n<li>intégrité, vertu, pureté de vie, droiture, pensées et actions correctes</li>\n</ol>\n</li>\n<li>sens plus étroit : justice qui donne à chacun ce qui lui est dû</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαιοσύνη, ης (ἡ)</b> <span>[ῐῠ]</span><br><b>      1</b> justice, sentiments de justice, pratique de la justice, THGN. <i>147 ;</i> HDT. <i>1, 96 ;</i> PLAT. <i>Rsp. 433</i> a, <i>etc. ;</i> ARSTT. <i>Nic. 5, 5, etc. ;</i><br><b>      2</b> fonction de juge, PLAT. <i>Gorg. 464</i> b ;<br><b>      3</b> la Justice personnifiée, ANTH. <i>9, 164</i>.<br><span><b>Étym</b>. δίκαιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιοσυνη - δικαιοσύνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n92 fois dans 85 versets de 19 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (4)</li>\n<li>Romains (35)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (7)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (3)</li>\n<li>Philippiens (4)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (3)</li>\n<li>Tite (1)</li>\n<li>Hébreux (6)</li>\n<li>Jacques (3)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1344":"<h1>dikaioo</h1>\n<p>Strong n° 1344 <i>Prononciation [dik-ah-yo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre juste ou comme il doit être</li>\n<li>montrer, exposer, démontrer sa justice, comme on est et qu'on souhaite être considéré</li>\n<li>déclarer, prononcer la justice de quelqu'un, le justifier</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαιόω-ῶ</b> <span>[ῐ]</span> <span>(<i>f</i>. ώσω <i>et</i> ώσομαι, <i>ao</i>. ἐδικαίωσα, <i>pf. inus. ; pass. f</i>. -ωθήσομαι, <i>ao</i>. ἐδικαιώθην, <i>pf</i>. δεδικαίωμαι)</span><br><b>   I</b> rendre juste, <i>d’où :</i><br><b>      1</b> soumettre à la justice : τὸ βιαιότατον, PD. <i>fr. 151, 4,</i> les abus de la violence ;<br><b>      2</b> établir comme juste, <i>d’où</i> prouver, ESCHL. <i>Ag. 393 ;</i><br><b>   II</b> regarder comme juste, juger légitime, <i>avec une prop. inf</i>. HDT. <i>1, 89, 133 ; 3, 42, 79 ;</i> SOPH. <i>Tr. 1244, O.R. 6 ;</i> EUR. <i>Suppl. 526, etc. ; p. suite :</i><br><b>      1</b> désirer, vouloir, <i>avec une prop. inf</i>. HDT. <i>9, 93 ;</i> THC. <i>2, 41 ; avec</i> ὥστε, SOPH. <i>O.C. 1350 ;</i><br><b>      2</b> ordonner, DH. <i>10, 1 ;</i><br><b>      3</b> consentir à, <i>inf</i>. HDT. <i>2, 172 ;</i><br><b>   III</b> rendre justice à, ARSTT. <i>Nic. 5, 9, 2 ; d’où :</i><br><b>      1</b> condamner, <i>en gén</i>. châtier, punir, HDT. <i>1, 100 ; 3, 29 ;</i> PLAT. <i>Leg. 934</i> b ;<br><b>      2</b> faire valoir les droits de, défendre, <i>acc</i>. SPT. <i>Jos. 1, 17 ;</i><br><b><i>Moy.</i></b> rendre justice, <i>d’où</i> condamner, THC. <i>3, 40</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. 3 pl. ion</i>. δικαιεῦσι, HDT. <i>2, 47 ; inf</i>. δικαιεῦν (<i>var</i>. -οῦν) HDT. <i>6, 82 ; part</i>. δικαιεῦντος, HDT. <i>9, 42. Impf. 3 pl. ion</i>. ἐδικαίευν, HDT. <i>3, 79 ; 6, 15. Fut</i>. δικαιώσω, ORACL. (HDT. <i>5, 92</i>) ; THC. <i>5, 26,</i> POL. <i>3, 31, etc. ; ou</i> δικαιώσομαι, THC. <i>3, 40. — Pass. ao. seul class. : part</i>. δικαιωθείς, ESCHL. <i>Ag. 393 ; les autres temps réc. : f</i>. δικαιωθήσομαι, SPT. <i>Esaï. 45, 25 ; pf</i>. δεδικαίωμαι, SPT. <i>Gen. 38, 26</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιοω - δικαιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n42 fois dans 36 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (5)</li>\n<li>Actes (2)</li>\n<li>Romains (15)</li>\n<li>1 Corinthiens (2)</li>\n<li>Galates (8)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Jacques (5)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1345":"<h1>dikaioma</h1>\n<p>Strong n° 1345 <i>Prononciation [dik-ah'-yo-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui a été déterminé comme droit, qui a force de loi\n<ol type=\"a\">\n<li>ce qui a été établi, ordonné par la loi, par une ordonnance</li>\n<li>décision judiciaire, sentence, commandement, acte de justice</li>\n<ol>\n<li>de Dieu\n<ol type=\"a\">\n<li>jugement favorable par lequel il acquitte l'homme et le déclare acceptable pour Lui, acquittement</li>\n<li>défavorable : sentence de condamnation</li>\n</ol>\n</li>\n</ol>\n</ol>\n</li>\n<li>un acte de justice, une œuvre juste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαίωμα, ατος (τὸ)</b> <span>[ῐ]</span><br><b>      1</b> action juste, acte de justice, ARSTT. <i>Rhet. 1, 13, 1 ; particul</i>. réparation d’une faute, ARSTT. <i>Nic. 5, 7, 7 ;</i><br><b>      2</b> réclamation d’un droit, prétention juste, THC. <i>1, 41 ; 6, 80 ;</i> ISOCR. <i>121</i> a ; ARSTT. <i>Cæl. 1, 10, 1 ;</i><br><b>      3</b> décision de justice, jugement, peine, PLAT. <i>Leg. 864</i> e ;<br><b>      4</b> ordre, prescription, SPT. <i>Gen. 26, 5 ; Ex. 15, 26, etc. ;</i> NT. <i>Rom. 1, 32 ; 2, 26 ;</i><br><b>      5</b> justification, <i>p. opp. à</i> κατάκριμα, NT. <i>Rom. 5, 16</i>.<br><span><b>Étym</b>. δικαιόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιωμα - δικαίωμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (5)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1346":"<h1>dikaios</h1>\n<p>Strong n° 1346 <i>Prononciation [dik-ah'-yoce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>juste, conforme au droit</li>\n<li>ce qui est droit</li>\n<li>convenable, conforme à la loi de la rectitude</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαίως</b> <span>[ῐ]</span> <i>adv. :</i><br><b>      1</b> comme il convient, OD. <i>14, 90 ; p. suite,</i> d’une façon tout à fait appropriée, très bien, HPC. <i>783 ;</i><br><b>      2</b> justement, avec justice, HDT. <i>6, 137 ;</i> ESCHL. <i>Ag. 376, etc. ;</i> δ. κἀδίκως, AR. <i>Pl. 233 ;</i> καὶ δ. κἀδίκως, AND. <i>1, 3,</i> à tort et à droit, <i>càd</i>. de toute façon, par tous les moyens possibles ;<br><b>      3</b> exactement, DÉM. <i>515, 13 ; 564, 16</i> ;<br><i>Comp</i>. -ότερον, THC. <i>2, 43, 3, 64 ;</i> PLAT. <i>Theæt. 209</i> e ; <i>rar</i>. -οτέρως, ISOCR. <i>p. 462 Bkk. Sup</i>. -ότατα, HPC. <i>l. c. ;</i> PLAT. <i>Tim. 72</i> b, <i>etc. ;</i> AR. <i>Av. 1222</i>.<br><span><b>Étym</b>. δίκαιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιως - δικαίως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 5 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1347":"<h1>dikaiosis</h1>\n<p>Strong n° 1347 <i>Prononciation [dik-ah'-yo-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>action de Dieu déclarant l'homme libre de culpabilité et acceptable pour Lui</li>\n<li>justification, état du juste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαίωσις, εως (ἡ)</b> <span>[δῐ]</span><br><b>   I</b> action de juger comme juste, <i>d’où</i> justification (d’actes jusque-là considérés comme blâmables) THC. <i>3, 82 ;</i><br><b>   II</b> action de faire valoir son droit :<br><b>      1</b> réclamation d’un droit, THC. <i>1, 141 ;</i> PLUT. <i>Demetr. 18 ;</i><br><b>      2</b> défense, justification, LYS. <i>115, 5 ;</i><br><b>   III</b> action de traiter selon la justice, condamnation, THC. <i>8, 66 ; d’où</i> châtiment, PLUT. <i>M. 421</i> d ; DC. <i>40, 43</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαιωσις - δικαίωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Romains (2)</li>\n</ul>\n</td></tr>\n</table>","G1348":"<h1>dikastes</h1>\n<p>Strong n° 1348 <i>Prononciation [dik-as-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un juge, un arbitre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δικαστής, οῦ (ὁ)</b> <span>[ῐ]</span><br><b>      1</b> juge, HDT. <i>1, 91 ; 3, 14, etc. ;</i> ESCHL. <i>Eum. 684 ;</i> PLAT. <i>Rsp. 405</i> b, <i>614</i> c, <i>etc. ;</i><br><b>      2</b> <i>p. suite,</i> qui fait expier, vengeur, EUR. <i>H.f. 1150</i>.<br><span><b>Étym</b>. δικάζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικαστης - δικαστής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – est le terme le plus digne et le plus officiel\n<br><br> – donne la prééminence au procédé mental, que le juge soit un magistrat ou non</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1349":"<h1>dike</h1>\n<p>Strong n° 1349 <i>Prononciation [dee'-kay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coutume, usage</li>\n<li>droit, juste</li>\n<li>un procès</li>\n<li>décision judiciaire</li>\n<li>sentence de condamnation\n<ol type=\"a\">\n<li>souffrir un châtiment</li>\n</ol>\n</li>\n<li>la Justice de Dieu, justice vengeresse.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίκη, ης (ἡ)</b> <span>[ῐ]</span> règle, <i>d’où :</i><br><b>   I</b> usage, manière d’être <i>ou</i> d’agir : αὕτη δ. ἐστὶ βροτῶν, OD. <i>11, 218,</i> telle est la manière d’être des mortels ; δίκη βασιλήων, OD. <i>4, 691 ;</i> γερόντων, OD. <i>24, 255,</i> coutume des rois, des vieillards ; <b><i>adv</i>., δίκην</b>, à la manière de, <i>avec un gén. de pers. :</i> δίκην ἀγγέλου, ESCHL. <i>Ch. 193 ;</i> δ. τοξότου, PLAT. <i>Leg. 705</i> e, à la façon d’un messager, d’un archer ; <i>avec un n. d’animal :</i> λύκοιο δ. PD. <i>P. 2, 84 ;</i> κυνὸς δ. ESCHL. <i>Ag. 3 ;</i> δ. ὄρνιθος, PLAT. <i>Phædr. 249</i> d, à la façon d’un loup, d’un chien, d’un oiseau ; <i>avec un n. de chose :</i> δ. ὕδατος, ESCHL. <i>Sept. 85 ;</i> ἀγγείου δ. PLAT. <i>Phædr. 235</i> d ; δ. κρατῆρος, PLAT. <i>Leg. 773</i> c, comme un torrent, comme un vase, comme une coupe ;<br><b>   II</b> ce qui sert de règle, droit, justice, IL. <i>19, 180, etc. ; p. opp. à la force</i> (βία) IL. <i>16, 388 ;</i> OD. <i>14, 84 ;</i> ἔξω τῆς δίκης βαίνειν, PLAT. <i>Leg. 876</i> e, marcher hors des voies de la justice ; ἔχει δέ μοι πρὸς δίκας τι, SOPH. <i>O.C. 545,</i> mais (le meurtre que j’ai commis) a une excuse (<i>litt</i>. a qqe chose du côté de la justice) ; δίκη ἐστί, ESCHL. <i>Ag. 259,</i> c’est justice, cela est juste ; <i>adv</i>., δίκῃ, IL. <i>23, 542 ;</i> SOPH. <i>O.C. 760, etc. ;</i> ἐν δίκῃ, PD. <i>O. 2, 29 ;</i> SOPH. <i>Tr. 1069 ;</i> PLAT. <i>Phædr. 266</i> a ; σὺν δίκῃ, PD. <i>P. 9, 170 ;</i> ESCHL. <i>Sept. 444, Eum. 610 ;</i> HDT. <i>1, 115, etc. ;</i> μετὰ δίκης, PLAT. <i>Leg. 643</i> e ; πρὸς δίκης, SOPH. <i>O.R. 1014 ;</i> κατὰ δίκην, HDT. <i>7, 35 ;</i> EUR. <i>Tr. 887 ;</i> PLAT. <i>Ep. 351</i> e, avec justice, justement ; παρὰ δίκην, PD. <i>I. 6, 67 ;</i> ἄνευ δίκης, ESCHL. <i>Eum. 554 ;</i> δίκης ἄτερ, ESCHL. <i>Suppl. 703 ;</i> πέρα δίκης, ESCHL. <i>Pr. 30 ;</i> SOPH. <i>El. 521 ;</i> βίᾳ δίκης, ESCHL. <i>Suppl. 430 ;</i> δίχα δίκης, PLUT. <i>Ages. 32,</i> sans justice ;<br><b>   III</b> <i>p. suite :</i> action judiciaire, <i>d’où :</i><br><b>      1</b> procès, <i>particul</i>. procès privé, <i>p. opp. à</i> γραφή, <i>action publique,</i> DÉM. <i>523, 17 ;</i> LYS. <i>135, 42 ;</i> δ. ἔχειν. PLUT. <i>Mar. 6,</i> avoir un procès (<i>v. ci-dessous</i>) ; δίκην διώκειν, ATT. être poursuivant, accusateur, demandeur ; δ. φεύγειν, DÉM. <i>985, 6,</i> être poursuivi, accusé, défendeur ; δ. κρίνειν, ESCHL. <i>Eum. 411 ;</i> SOPH. <i>Ph. 1350,</i> juger un procès ; ἐς δίκην ἄγειν, ATT. citer en justice ;<br><b>      2</b> cours du procès, débats : τῇ προτεραίᾳ τῆς δίκης, PLAT. <i>Phæd. 58</i> b, la veille du procès ; πρὸ δίκης, THC. <i>1, 141,</i> avant l’ouverture du procès ;<br><b>      3</b> le tribunal qui juge le procès, ANT. <i>142, 5 ;</i><br><b>      4</b> le plaidoyer : δίκην εἰπεῖν, XÉN. <i>Mem. 4, 8, 1,</i> plaider une cause devant un tribunal (<i>mais v. ci-dessous</i> III, 5) ;<br><b>      5</b> décision judiciaire, jugement ; δ. εἰπεῖν, IL. <i>18, 508,</i> prononcer un jugement (<i>mais v. ci-dessus</i> III, 4) ; <i>au plur</i>. HÉS. <i>O. 217, 248 ; d’où en gén</i>. décision, décret, SOPH. <i>Ant. 921 ;</i><br><b>      6</b> conséquence d’un jugement, peine, châtiment : δ. διδόναι (<i>cf. lat</i>. pœnas dare) HDT. <i>1, 2 ;</i> SOPH. <i>El. 538, etc</i>. être puni ; δίκην διδόναι τινός, HDT. <i>5, 106, etc</i>. être puni pour qqe ch. ; δίκην ὀφλεῖν, PLAT. <i>Ap. 39</i> b, être condamné ; δίκην <i>ou</i> δίκας τίνειν, HDT. <i>9, 94 ;</i> ἐκτίνειν, SOPH. <i>Aj. 113 ;</i> ὑπέχειν, SOPH. <i>O.R. 552,</i> subir une peine, être puni ; δίκας λαμϐάνειν, tirer vengeance, se venger, LYS. <i>94, 27, etc. ; ou au contr</i>. être puni, HDT. <i>1, 115 ;</i> DÉM. <i>110 fin ;</i> λαϐεῖν δίκην παρά τινος, DÉM. <i>544, 6,</i> tirer vengeance de qqn ; δίκην αἰτέειν, HDT. <i>8, 114,</i> réclamer vengeance ; δίκην ἔχειν, PLAT. <i>Leg. 319</i> e, obtenir satisfaction ; <i>ou au contr</i>. être puni, ANT. <i>124, 45 ;</i> XÉN. <i>Hell. 3, 4, 25 ;</i> PLAT. <i>Rsp. 529</i> c ;<br><b>   IV</b> la règle, le droit, <i>t. pythagor. en parl. des nombres</i> deux, THEOL. <i>12 ;</i> trois, PLUT. <i>M. 381</i> f ; cinq, THEOL. <i>31</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. δίκα, PD. <i>ll. cc. ;</i> ESCHL. <i>Ch. 935, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *deiḱ-, montrer ; <i>cf</i>. δείκνυμι, <i>particul. au sens juridique, cf. lat</i>. jūdex <i>de</i> *iūs-diḱ-s, <i>litt</i>. « droit oral ».</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικη - δίκη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (2)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G1350":"<h1>diktuon</h1>\n<p>Strong n° 1350 <i>Prononciation [dik'-too-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un filet (pour capturer poissons, animaux, ou oiseaux)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίκτυον, ου (τὸ)</b> <span>[ῠ]</span> filet, <i>d’où :</i><br><b>      1</b> filet de pêche, OD. <i>22, 386 ;</i> ESCHL. <i>Ch. 506 ;</i> SOPH. <i>fr. 783 ;</i> XÉN. <i>Cyr. 1, 6, 19 ;</i> ARSTT. <i>H.A. 4, 8, 12 ; 19, 13 ;</i><br><b>      2</b> filet de chasse, HDT. <i>1, 123 ;</i> AR. <i>Av. 1083 ; différent de</i> ἄρκυς, XÉN. <i>Cyn. 2, 5 ;</i><br><b>      3</b> <i>fig</i>. ESCHL. <i>Pr. 1078 ; Ag. 1115, etc</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δικτυον - δίκτυον</font>\n<br><br>vient probablement d'un verbe primaire diko (jeter)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – semble être le mot le plus général pour les filets de toute sorte\n<br><br> – un filet de pêche, filet à lancer, généralement en forme de poire\n<br><br> – un filet de pêche, une seine ou un filet à draguer</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (2)</li>\n<li>Luc (4)</li>\n<li>Jean (4)</li>\n</ul>\n</td></tr>\n</table>","G1351":"<h1>dilogos</h1>\n<p>Strong n° 1351 <i>Prononciation [dil'-og-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dire deux fois la même chose, répétition</li>\n<li>double langue, double en parole, disant une chose à une personne et autre chose à une autre (avec intention de tromper), duplicité, fourbe fourberie, fausseté, hypocrisie</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δί·λογος, ος, ον</b> <span>[ῐ]</span> à deux langages, fourbe, NT. <i>1Tim. 3, 8</i>.<br><span><b>Étym</b>. δίς, λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διλογος - δίλογος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1352":"<h1>dio</h1>\n<p>Strong n° 1352 <i>Prononciation [dee-o']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>en quoi, dans lequel, dont</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διό</b>, <i>adv. p</i>. δι' ὅ :<br><b>      1</b> c’est pourquoi, par suite, PLAT. <i>Rsp. 358</i> d, <i>etc. ; dans le disc. indir. avec l’inf</i>. POÈT. (ATH. <i>36</i> b) : <i>renforcé par</i> καί, PLAT. <i>Phædr. 258</i> e ; TH. <i>Ign. 63 ;</i> DS. <i>11, 81 ; par</i> δή, PLAT. <i>Gorg. 518</i> a, <i>etc. ; par</i> δὴ καί, THC. <i>2, 21 ;</i> PLAT. <i>Conv. 203</i> c ; <i>par</i> περ (<i>v</i>. διόπερ) ;<br><b>      2</b> <i>postér</i>. parce que, ARSTT. <i>Plant. 2, 4, 5</i>.<br><span><b>Étym</b>. διά, ὅ <i>de</i> ὅς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διο - διό</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n53 fois dans 52 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (2)</li>\n<li>Actes (10)</li>\n<li>Romains (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (7)</li>\n<li>Ephésiens (5)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (9)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n<li>2 Pierre (3)</li>\n</ul>\n</td></tr>\n</table>","G1353":"<h1>diodeuo</h1>\n<p>Strong n° 1353 <i>Prononciation [dee-od-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>passer ou voyager à travers</li>\n<li>voyager ici et là, parcourir, aller de lieu en lieu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·οδεύω</b> <span>(<i>impf</i>. διώδευον)</span> faire route à travers, traverser, parcourir, <i>acc</i>. POL. <i>2, 15, 2 ;</i> PLUT. <i>Flam. 5, Ages. 17 ;</i> X. ÉPH. <i>5, 2 ; au pass</i>. être parcouru, ANTH. <i>9, 708</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διοδευω - διοδεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1354":"<h1>Dionusios</h1>\n<p>Strong n° 1354 <i>Prononciation [dee-on-oo'-see-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Denys (Angl. Dionysius) = « appartenant à Dyonisos, le dieu du vin »\n<ol><li>Athénien, membre de l'Aréopage, converti au Christianisme par Paul</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>Διονύσιος, α, ον</b> <span>[ῐῡ]</span> de Dionysos, SIM. <i>fr. 89 ;</i> BACCHYL. <i>fr. 20B, 9 ;</i> ANACR. <i>29, 53 et 54, etc</i>.<br><span><b>Étym</b>. Διόνυσος.</span><br><br>\n② <b>Διονύσιος, ου (ὁ)</b> <span>[ῐῡ]</span> Dionysios (Denys) :<br><b>      1</b> <i>n. de deux tyrans de Syracuse :</i> Δ. ὁ πρότερος, XÉN. <i>Hell. 7, 4, 12 ;</i> ARSTT. <i>Rhet. 2, 15, etc. ; ou</i> ὁ πρεσϐύτερος, POL. <i>1, 6 ;</i> DH. <i>7, 1,</i> Denys l’Ancien ; Δ. ὁ νέος, EL. <i>V.H. 4, 18 ;</i> ὁ νεώτερος, DS. <i>15, 74, etc. ;</i> ὁ δεύτερος, EL. <i>V.H. 6, 12 ;</i> ὁ ὕστερος, ARSTT. <i>Pol. 5, 8, 14,</i> Denys le jeune <i>ou</i> le second ; <i>plur</i>. Διονύσιοι οἱ ἐν Σικελίᾳ, EL. <i>N.A. 5, 15 ; ou</i> οἱ ἀμφότεροι Διονύσιοι, ATH. <i>250</i> d, les Denys de Sicile <i>ou</i> les deux Denys ;<br><b>      2</b> <i>n. de divers écrivains,</i> Denys d’Halicarnasse, Denys le Périègète, Denys de Thrace, <i>etc</i>.<br><span><b>Étym</b>. Διόνυσος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Διονυσιος - Διονύσιος</font>\n<br><br>vient de Dionusos (Bacchus)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1355":"<h1>dioper</h1>\n<p>Strong n° 1355 <i>Prononciation [dee-op'-er]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ceci est la cause, c'est ce qui</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διόπερ</b>, <i>p</i>. δι' ὅπερ, <i>conj. :</i><br><b>      1</b> c’est pourquoi, THC. <i>1, 71 ; 8, 92, etc. ;</i> PLUT. <i>M. 115</i> b, <i>etc. ;</i> CIA. <i>2, 240 b, 17 (307 av. J.C</i>.) ;<br><b>      2</b> parce que, XÉN. <i>Mem. 4, 8, 7 ;</i> DÉM. <i>Ol. 3, 19</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διοπερ - διόπερ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (3)</li>\n</ul>\n</td></tr>\n</table>","G1356":"<h1>diopetes</h1>\n<p>Strong n° 1356 <i>Prononciation [dee-op-et'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tombé de Zeus (Jupiter), c.à.d du ciel</li>\n<li>une image de l'Artémis des Ephésiens, qui était supposée être tombée du ciel</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διο·πετής, ής, ές</b>, <i>propr</i>. tombé de Zeus, <i>càd</i>. du ciel, <i>en parl. d’une statue,</i> EUR. <i>I.T. 977 ; du Palladium,</i> DH. <i>2, 66 ; du bouclier romain</i> « ancile » DH. <i>2, 71 ;</i> PLUT. <i>Num. 13 ; d’une pierre,</i> HDN <i>5, 3, 11</i>.<br><span><b>Étym</b>. Διός, πετ- <i>de</i> πίπτω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διοπετης - διοπετής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1357":"<h1>diorthosis</h1>\n<p>Strong n° 1357 <i>Prononciation [dee-or'-tho-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>sens physique : remettre droit, restaurer aux conditions naturelles et normales quelque chose qui a été défait, cassé, ou qui est difforme, redressement</li>\n<li>pour les actions et institutions : réformation</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διόρθωσις, εως (ἡ) :<br>   I</b> action de redresser, redressement (d’un membre) HPC. <i>745</i> a, <i>839</i> h ; (d’un édifice, <i>càd</i>.) restauration, ARSTT. <i>Pol. 6, 8, 4 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> action de corriger, de châtier, POL. <i>2, 56, 14 etc. ;</i> DH. <i>6, 20 ;</i><br><b>      2</b> action d’améliorer, d’amender (les mœurs, le caractère, la conduite, <i>etc</i>.) POL. <i>3, 58, 4 ; 3, 118, 12 ; 7, 12, 2 ; en gén</i>. rectification, amélioration, HÉRON <i>Aut. 263 ;</i> action de réparer (des revers) POL. <i>6, 38, 4 ; d’où, p. opp. à</i> βλαϐή, avantage, profit, gain, POL. <i>5, 88, 2 ; t. de gr</i>. correction d’un texte, <i>d’où</i> édition critique, GRAMM. ;<br><b>      3</b> action de remettre en ordre, <i>d’où</i> extinction (de dettes) POL. <i>5, 50, 7</i>.<br><span><b>Étym</b>. διορθόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διορθωσις - διόρθωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1358":"<h1>diorusso</h1>\n<p>Strong n° 1358 <i>Prononciation [dee-or-oos'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>creuser à travers : percer une maison pour y pénétrer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ορύσσω</b>, <i>att</i>. -ύττω, <i>f</i>. ύξω, creuser à travers, <i>d’où :</i><br><b>      1</b> percer (un mur, une montagne, <i>etc</i>.) HDT. <i>9, 37 ;</i> AR. <i>Pl. 565 ;</i> DÉM. <i>73, 8 ;</i> LYS. <i>193, 24, etc. ; fig</i>. se faire un chemin en creusant à travers, PLUT. <i>M. 87</i> c ;<br><b>      2</b> <i>p. suite,</i> miner, <i>d’où fig</i>. avarier, endommager, DÉM. <i>1111, 2 ; au pass</i>. être séparé, DÉM. <i>118, 11 ;</i><br><b>      3</b> enfouir, enterrer, DS. <i>4, 43</i>.<br><span><b>Étym</b>. <i>partic. pf. pass</i>. διωρυγμένοις, <i>var</i>. διορυττομένοις, <i>corr</i>. κατωρυγμένοις <i>Reiske</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δι-ορυσσω - διορύσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1359":"<h1>Dioskouroi</h1>\n<p>Strong n° 1359 <i>Prononciation [dee-os'-koo-roy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Dioscures = « les fils de Zeus » (Castor et Pollux)\n<ol><li>Castor et Pollux étaient deux frères jumeaux, fils de Jupiter et Leda et considérés comme les divinités protégeant les marins</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Διόσκουροι</b>, <i>v</i>. Διόσκοροι.<br><br>\n<b>Διόσ·κοροι</b>, <i>postér</i>. <b>Διόσ·κουροι, ων (οἱ)</b> les Dioscures (<i>litt</i>. jeunes garçons de Zeus) <i>càd</i>. Castor et Pollux (<i>v</i>. Κάστωρ <i>et</i> Πολυδεύκης) <i>frères d’Hélène, appelés aussi</i> Τυνδαρίδαι (<i>v. ce mot) et</i> Δίδυμοι « les Jumeaux <i>ou</i> Gémeaux », <i>dieux protecteurs des marins auxquels ils apparaissent dans les tempêtes sous la forme de feux de Saint-Elme</i> (= <i>Sancta Helena), lueur phosphorescente qui, par un temps d’orage, voltige sur la mer ; p. ext. protecteurs des voyageurs sur terre et sur mer, et, p. suite, dieux de l’hospitalité ; honorés surtout comme dieux équestres présidant aux courses de chars et aux concours gymniques</i>.<br><span><b><span class=\"arrow\"></span></b> Διόσκορ- <i>en vieil att. ;</i> Διόσκουρ-, <i>forme att. plus réc., ion., et de gréc. réc. ; le duel plus us. que le plur. :</i> τὼ Διοσκόρω, EUR. <i>Or. 465, I.T. 272, Hel. 282, 720 ;</i> AR. <i>Pax 285, Eccl. 1069 ;</i> XÉN. <i>Hell. 6, 3, 6, etc. ; gén</i>. τοῖν Διοσκόροιν, MÉN. <i>4, 278 Meineke ; ttf. le plur. très us</i>. οἱ Διόσκοροι, EUR. <i>Hel. 1167, El. 1239 ;</i> XÉN. <i>Conv. 8, 29 ;</i> PLAT. <i>Leg. 796</i> b ; ARSTT. <i>Eud. 8, 12, etc. — Du radic</i>. Διόσκουρ-: <i>duel</i> τοῖν Διοσκούροιν, LUC. <i>Char. 3 ;</i> ARR. <i>An. 4, 8, 2 ; plur</i>. οἱ Διόσκουροι, <i>ion</i>. HDT. <i>2, 43 et 50 ; 6, 127 ;</i> EUR. <i>I.A. 769 ;</i> THC. <i>3, 75 (un seul ms</i>. Διοσκόρων) ; PLUT. <i>M. 483</i> c, <i>etc. — Écrit en deux mots</i> Διὸς κοῦροι, HH. <i>33, 1, 9</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Διοσκουροι - Διόσκουροι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G1360":"<h1>dioti</h1>\n<p>Strong n° 1360 <i>Prononciation [dee-ot'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>à cause de ceci, parce que</li>\n<li>car</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ότι</b> <i>p</i>. δι' ὅτι, <i>conj. :</i><br><b>      1</b> <i>c</i>. δι' ὅτι, pour quelle raison, pourquoi, <i>dans le disc. indir. :</i> φράσω διότι, HDT. <i>2, 24,</i> je dirai pourquoi ; σκοπεῖν διότι, THC. <i>1, 77,</i> examiner pourquoi, <i>etc. ; postér. dans le disc. dir</i>. διότι… ; SPT. <i>Judith 5, 28,</i> pourquoi ? ;<br><b>      2</b> <i>c</i>. διὰ τοῦτο ὅτι, parce que, HDT. <i>1, 44 ; 3, 55 ;</i> THC. <i>1, 52 ;</i> οὐδὲ δι' ἓν ἄλλο ἢ διότι, PLAT. <i>Phæd. 100</i> c, ni pour aucune autre raison sinon que ; <i>pour répondre à une question faite par</i> διὰ τί ; PLAT. <i>Pol. 310</i> d ; AMPHIS (<i>Com. fr. 3, 306</i>) ;<br><b>      3</b> <i>c</i>. ὅτι, que, HDT. <i>2, 43, etc. ;</i> ISOCR. <i>50</i> c ; DÉM. <i>163 fin ; qqf. avec l’inf</i>. HDT. <i>3, 55 ;</i> POL. <i>31, 20, 4 ;</i> DS. <i>4, 76</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. διότι <i>inus. au sens de</i> « parce que », <i>mais us. au sens de</i> « que » <i>au commenc. du 3<sup>e</sup> siècle av. J.C. (v. Meisterh. p. 211, 25 et 28</i>).<br><span><b>Étym</b>. διά, ὅτι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διοτι - διότι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 10 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Actes (5)</li>\n<li>Romains (4)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>Hébreux (2)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G1361":"<h1>Diotrephes</h1>\n<p>Strong n° 1361 <i>Prononciation [dee-ot-ref-ace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Diotrèphe (Angl. Diotrephes) = « nourri par Zeus »\n<ol><li>Chrétien fier et arrogant mentionné dans <a class=\"ref\" data-r=\"3JN1.9\">3 Jean 9</a></li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Διο·τρέφης, ους (ὁ)</b> Diotréphès, <i>h</i>. THC. <i>4, 53 ;</i> DH. DS. <i>etc</i>. (<i>cf</i>. διοτρεφής).<br><span><b>Étym</b>. Διός, τρέφω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Διοτρεφης - Διοτρεφής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1362":"<h1>diplous</h1>\n<p>Strong n° 1362 <i>Prononciation [dip-looce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un double, au double</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διπλοῦς, ῆ, οῦν</b>, <i>v</i>. διπλόος.<br><br>\n<b>διπλόος-οῦς, όη-ῆ, όον-οῦν :<br>   I</b> double :<br><b>      1</b> double, au nombre de deux : διπλῆ μάστιξ, ESCHL. <i>Ag. 642 ;</i> SOPH. <i>Aj. 242,</i> fouet à double lanière ; διπλᾶ κέντρα, SOPH. <i>O.R. 809,</i> aiguillon à double pointe ; διπλοῦν οἰκίδιον, LYS. <i>92, 28,</i> maisonnette à deux étages ; ἐκπεφευγὼς διπλόον θάνατον, HDT. <i>6, 104,</i> ayant échappé à une double mort ; παίειν διπλῆν (<i>s.-e</i>. πληγήν) SOPH. <i>El. 1416,</i> frapper un second coup ; <i>au plur</i>. διπλοῖ βασιλῆς, SOPH. <i>Aj. 959 ;</i> διπλοῖ στρατηλάται, SOPH. <i>Ph. 793,</i> deux rois, deux chefs d’armée ; <i>cf</i>. ESCHL. <i>Pr. 950 ;</i> SOPH. <i>O.R. 1135, etc. ; adv</i>. διπλῷ, PLAT. <i>Leg. 722</i> b, doublement (<i>cf</i>. διπλῇ) ; <i>particul</i>. formé de deux éléments, <i>en parl. de mots composés,</i> ARSTT. <i>Rhet. 8, 2, 5, ou des consonnes doubles</i> (ζ, ξ, ψ) D. THR. <i>632, 3 ;</i> A. QUINT. <i>p. 44 ;</i> SEXT. <i>622, 10 Bkk. ;</i><br><b>      2</b> qui se met en double, qui se replie, <i>en parl. de vêtements :</i> χλαῖνα διπλῆ, IL. <i>10, 134 ;</i> OD. <i>19, 226,</i> manteau qu’on met en double (<i>cf</i>. διπλοΐς <i>ou</i> δίπλαξ) ; <i>cf</i>. APD. COM. 2 (<i>Com. fr. 4, 440) ; subst</i>. ἡ διπλῆ, <i>m. sign</i>. PHILSTR. <i>385 ;</i> SEXT. <i>41, 31 Bkk. ;</i> ὅθι διπλόος ἤντετο θώρηξ, IL. <i>4, 133,</i> là où la cuirasse, rencontrant le ζῶμα, formait avec lui une double feuille ;<br><b>      3</b> qui se courbe en deux : δ. ἄκανθα, EUR. <i>El. 492,</i> l’épine du dos courbée (par la vieillesse) ;<br><b>      4</b> qui agit doublement, <i>càd</i>. par une action réciproque <i>ou</i> simultanée : ἀδελφῶν θανόντων διπλῇ χερί, SOPH. <i>Ant. 14,</i> frères morts des coups dont ils se sont mutuellemeht frappés (<i>cf</i>. ἐπαλλήλοιν χεροῖν, <i>ibid. 57</i>) ;<br><b>      5</b> de double nature (dieu et homme) <i>en parl. de J.C</i>. NAZ. <i>2, 328, c Migne ;</i><br><b>      6</b> <i>en mauv. part,</i> double, équivoque, faux, EUR. <i>Rhes. 395 ;</i> XÉN. <i>Hell. 4, 1, 32 ;</i> PLAT. <i>Rsp. 397</i> d, <i>554</i> d ;<br><b>      7</b> <i>subst</i>. ἡ διπλόη, signe critique, <i>c</i>. διπλῆ, HÉPH. <i>Sign. 1, 4 ;</i> DL. <i>3, 66, etc. ;</i><br><b>   II</b> deux fois aussi grand, aussi long, PLAT. <i>Tim. 75</i> b ; <i>avec le gén</i>. double de, PLAT. <i>Tim. 35</i> c ; διπλοῦν ὅσον, DÉM. <i>629, 22,</i> le double de ce que.<br><span>•<i> Cp</i>. διπλότερος, APP. <i>Pr. 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Sg. fém. ion</i>. διπλέη, HDT. <i>3, 42, dout. Dans les inscr. att. seul. la forme contracte</i> διπλοῦν, CIA. <i>2, 808, Z, 90, 107 ; les Trag. emploient les formes contr. sauf pour</i> διπλόοι, ESCHL. <i>fr. 33. Pl. neutre</i> διπλά <i>p</i>. διπλᾶ, ANTH. <i>10, 101 ; cf</i>. OPP. <i>C. 2, 449. — Fém. dor</i>. διπλόα, PD. <i>N. 5, 96</i>.<br><span><b>Étym</b>. δίς, -πλοος, <i>cf</i>. ἁπλόος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διπλους - διπλοῦς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Timothée (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1363":"<h1>diploo</h1>\n<p>Strong n° 1363 <i>Prononciation [dip-lo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>doubler, mettre en double, rendre la pareille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διπλόω-ῶ</b> <span>(<i>ao</i>. ἐδίπλωσα)</span><br><b>   I</b> doubler :<br><b>      1</b> mettre en double, ARSTT. <i>An. post. 2, 4, 2 ; en parl. d’un manteau,</i> DL. <i>6, 22 ;</i><br><b>      2</b> <i>au pass. en parl. du tranchant d’un fer,</i> se replier, <i>càd</i>. s’émousser, PLUT. <i>Cam. 41 ;</i><br><b>   II</b> rendre la pareille, <i>acc</i>. NT. <i>Apoc. 18, 6</i>.<br><span><b>Étym</b>. διπλόος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διπλοω - διπλόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1364":"<h1>dis</h1>\n<p>Strong n° 1364 <i>Prononciation [dece]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>deux fois</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίς</b> <span>[ῐ]</span> <i>adv</i>., deux fois, <i>avec un adj</i>. δὶς τόσσον, OD. <i>9, 491,</i> deux fois autant ; <i>avec un verbe :</i> δὶς τοῦτο ἐγένετο, HDT. <i>8, 104,</i> cela est arrivé deux fois (<i>cf</i>. ESCHL. <i>Pers. 173 ;</i> SOPH. <i>Aj. 432, etc.) ; avec un subst</i>. δὶς παῖς γέρων, CRAT. (<i>Com. fr. 5, 16 ; cf. 2, 818</i>) un vieillard est deux fois un enfant ; <i>avec une loc. adv</i>. δὶς τῆς ἡμέρας, PLAT. COM. <i>2-2, 692,</i> deux fois le jour ; δὶς καὶ τρίς, SOPH. <i>Aj. 432 ;</i> PLAT. <i>Gorg. 498</i> e, deux et trois fois ; <i>précédé d’une prép</i>. ἐς δίς, APP. <i>Mithr. 78,</i> jusqu’à deux fois.<br><span><b><span class=\"arrow\"></span></b> <i>En compos</i>. δίς <i>se réduit à</i> δι <i>devant une consonne, exc. devant</i> θ, τ, μ, π, χ, <i>et qqf. devant</i> κ (δισκόραξ) <i>et devant le</i> σ <i>lui-même</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *dui-s-, deux fois ; <i>cf</i>. διά, δοιός, <i>lat</i>. bis, <i>anc. lat</i>. duis.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δις - δίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G1365":"<h1>distazo</h1>\n<p>Strong n° 1365 <i>Prononciation [dis-tad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>douter, un abandon</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·στάζω</b>, douter, être dans l’incertitude, PLAT. <i>Theæt. 190</i> a, <i>etc. ;</i> περί τι, ARSTT. <i>Nic. 3, 3, 9,</i> περί τινος, PLUT. <i>M. 62</i> a, sur qqe ch. ; <i>la prop. suiv. avec</i> ὅτι <i>et l’ind</i>. PLAT. <i>Ion 534</i> e ; εἰ <i>et l’ind</i>. PLAT. <i>Leg. 897</i> b ; μή <i>et un mode subordonné,</i> PLAT. <i>Soph. 235</i> a ; <i>avec</i> πῶς, ARSTT. <i>Nic. 3, 3, 8 ; au pass</i>. être mis en doute, DS. <i>17, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δισταζω - διστάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (2)</li>\n</ul>\n</td></tr>\n</table>","G1366":"<h1>distomos</h1>\n<p>Strong n° 1366 <i>Prononciation [dis'-tom-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fleuve avec deux embouchures\n<ol type=\"a\">\n<li>utilisé pour le tranchant de l'épée et d'autres armes « arme à double tranchant »</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δί·στομος, ος, ον</b>, <i>propr</i>. à deux bouches, <i>càd. :</i><br><b>      1</b> à deux embouchures, POL. <i>34, 10, 5 ;</i> STR. <i>809 ;</i> NONN. <i>D. 27, 157 ;</i> à deux ouvertures, <i>en parl. d’une caverne,</i> SOPH. <i>Ph. 16, ou d’une route qui se bifurque,</i> SOPH. <i>O.C. 900. etc. ;</i><br><b>      2</b> à deux tranchants, EUR. <i>Hel. 983, 1044 ; Or. 1303 ;</i> NT. <i>Hebr. 4, 12</i>.<br><span><b>Étym</b>. δίς, στόμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διστομος - δίστομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Hébreux (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1367":"<h1>dischilioi</h1>\n<p>Strong n° 1367 <i>Prononciation [dis-khil'-ee-oy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>deux mille</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δισ·χίλιοι, αι, α</b> <span>[χῑ]</span> deux mille, PLAT. <i>Criti. 118</i> a ; AR. <i>Vesp. 660 ;</i> PLUT. <i>Fab. 6 ; au sg</i>. δισχιλίη (<i>ion</i>.) ἵππος, HDT. <i>7, 158,</i> troupe de 2 000 cavaliers.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δισχιλιοι - δισχίλιοι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G1368":"<h1>diulizo</h1>\n<p>Strong n° 1368 <i>Prononciation [dee-oo-lid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>filtrer à travers, passer à travers un filtre, filtrer en faisant couler, clarifier, purifier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·υλίζω</b> <span>[ῡ]</span> passer à la chausse, clarifier, purifier, PLUT. <i>M. 692</i> d ; DIOSC. <i>5, 82 ;</i> NT. <i>Matth. 23, 24 ; fig. en parl. de la vertu,</i> ARCHYT. (STOB. <i>Fl. 13, 40</i>).<br><span><b><span class=\"arrow\"></span></b> <i>Part. pf. pass. acc. fém. dor</i>. -ισμέναν, ARCHYT. <i>l. c</i>.<br><span><b>Étym</b>. διά, ὑ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διυλιζω - διϋλίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1369":"<h1>dichazo</h1>\n<p>Strong n° 1369 <i>Prononciation [dee-khad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>couper en deux parts, fendre en morceaux, séparer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διχάζω</b> <span>[ῐ]</span><br><b>      1</b> partager (une chose) en deux, PLAT. <i>Pol. 264</i> d ;<br><b>      2</b> séparer (deux personnes <i>ou</i> deux choses) ; <i>particul</i>. diviser (un nombre) NICOM. <i>Theol. 75, 78 ;</i> τινὰ κατά τινος, NT. <i>Matth. 10, 35,</i> séparer une personne d’une autre.<br><span><b>Étym</b>. δίχα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διχαζω - διχάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G1370":"<h1>dichostasia</h1>\n<p>Strong n° 1370 <i>Prononciation [dee-khos-tas-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dissension, division, sédition, discorde</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διχο·στασία, ας (ἡ)</b> <span>[ῐτᾰ]</span><br><b>      1</b> dissension, discorde, HDT. <i>5, 75 ;</i> PLUT. <i>M. 20</i> c, <i>479</i> a ;<br><b>      2</b> <i>p. suite,</i> séparation, sédition, SOL. <i>3, 37 ;</i><br><b>      3</b> doute, incertitude, THGN. <i>78</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίη, HDT. THGN. <i>ll. cc. etc</i>.<br><span><b>Étym</b>. δίχα, ἵστημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διχοστασια - διχοστασία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G1371":"<h1>dichotomeo</h1>\n<p>Strong n° 1371 <i>Prononciation [dee-khot-om-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couper en deux parts\n<ol type=\"a\">\n<li>méthode cruelle de châtiment utilisé par les Hébreux et d'autres, en coupant quelqu'un en deux</li>\n</ol>\n</li>\n<li>châtiment sévère</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διχοτομέω-ῶ</b> <span>[ῐ]</span><br><b>      1</b> couper <i>ou</i> diviser en deux, PLAT. <i>Pol. 302</i> e ; ARSTT. <i>Probl. 16, 4 ;</i> POL. <i>6, 28, 2 ; 10, 15, 5 ; t. de log</i>. ARSTT. <i>P.A. 1, 3, 1 ; 1, 4, 9 ; en parl. de la pleine lune qui divise le mois en deux parties égales,</i> PLUT. <i>M. 929</i> f ;<br><b>      2</b> séparer, retrancher (d’un tout, d’un groupe, <i>etc</i>.) NT. <i>Matth. 24, 51</i>.<br><span><b>Étym</b>. *διχοτόμος, qui coupe en deux ; <i>cf</i>. διχότομος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διχοτομεω - διχοτομέω</font></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G1372":"<h1>dipsao</h1>\n<p>Strong n° 1372 <i>Prononciation [dip-sah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>souffrir de la soif\n<ol type=\"a\">\n<li>figure : ceux qui ressentent douloureusement leur besoin, qui attendent, ou ce dont l'âme est rafraîchie, réconfortée, renforcée</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διψάω-ῶ</b> <span>(<i>impf</i>. ἐδίψων, <i>f</i>. διψήσω, <i>ao</i>. ἐδίψησα, <i>pf</i>. δεδίψηκα)</span> avoir soif, être altéré, OD. <i>11, 584, etc. ;</i> ESCHL. <i>Ag. 901, etc. ; en parl. de la terre, des plantes,</i> HDT. <i>2, 24 ;</i> TH. <i>H.P. 3, 22, 5, etc. ; avec un dat</i>. δ. ὕδατι, SPT. <i>Ex. 17, 3,</i> avoir soif d’eau ; <i>fig</i>. τινος, PD. <i>N. 3, 6 ;</i> PLAT. <i>Rsp. 562</i> c ; PLUT. <i>Cato mi. 11, etc. ; rar</i>. τι, TÉLÈS (STOB. <i>Fl. 5, 67, t. 1, p. 124, l. 4</i>) ; A. PL. <i>4, 137 ;</i> NT. <i>Matth. 5, 6 ;</i> τινί, SPT. <i>Ps. 62, 3,</i> avoir soif de qqe ch. (de justice, de liberté, de vengeance, <i>etc.) ; avec l’inf</i>. XÉN. <i>Cyr. 4, 6 ;</i> EL. <i>V.H. 2, 41 ;</i><br><b><i>Moy.</i></b> (<i>seul. prés</i>.) -ώμεθα, HERMIPP. (ATH. <i>426</i> f).<br><span><b><span class=\"arrow\"></span></b> <i>Les contract. de</i> αε <i>sont en</i> η : διψάει = διψῇ, PD. <i>N. 3, 6 ; sbj. 3 sg</i>. διψάῃ = διψῇ, PLAT. <i>Gorg. 517 ; inf</i>. διψῆν, <i>ion</i>. HDT. <i>2, 24 ; att</i>. SOPH. <i>fr. 701 ;</i> AR. <i>Nub. 441 ;</i> PLAT. <i>Gorg. 496</i> d ; <i>impf. 3 sg</i>. ἐδίψη, HPC. <i>1063, 1067 ;</i> EL. <i>V.H. 2, 41 ; qqf. en</i> α : <i>prés. ind. 2 et 3 sg</i>. διψᾷς, A. PL. <i>4, 137 ;</i> διψᾷ, PLAT. <i>Ax. 366</i> a ; SPT. <i>Prov. 25, 21 ; inf</i>. διψᾶν, GAL. <i>5, 837. — Prés. ion</i>. διψέω, ARCHIL. <i>68. Épq. réc</i>. διψώω, NONN. <i>Jo. 19, 29 ;</i> TRIPHIOD. <i>548 ;</i> ANTH. <i>11, 57. Poét. part. prés. non-contr</i>. διψάων <span>[ᾱ]</span> OD. <i>11, 587 ; fém. éol</i>. διψεῦσα, ANTH. <i>6, 21</i>.<br><span><b>Étym</b>. δίψα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διψαω - διψάω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Jean (6)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G1373":"<h1>dipsos</h1>\n<p>Strong n° 1373 <i>Prononciation [dip'-sos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>soif</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δίψος, εος-ους (τὸ)</b> <i>c</i>. δίψα, THC. <i>4, 35 ;</i> XÉN. <i>Cyr. 8, 1, 36 ;</i> PLAT. <i>Rsp. 437</i> d, <i>etc</i>.<br><br>\n<b>δίψα, ης (ἡ)</b> <span>[ᾰ]</span> soif, IL. <i>22, 2 ;</i> δ. τε καὶ λιμός, IL. <i>19, 166 ;</i> πεῖνα καὶ δ. PLAT. <i>Rsp. 585</i> a, la faim et la soif ; δίψῃ ἐξώλλυντο, ATH. <i>457</i> c, ils mouraient de soif ; <i>au plur</i>. ARSTT. <i>Nic. 7, 14, 5 ; fig., càd</i>. désir ardent, PD. <i>P. 9, 108 ;</i> PLAT. <i>Rsp. 437</i> d.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. δίψη, OPP. <i>C. 4, 339</i>.<br><span><b>Étym</b>. <i>pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διψος - δίψος</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1374":"<h1>dipsuchos</h1>\n<p>Strong n° 1374 <i>Prononciation [dip'-soo-khos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>esprit double, irrésolu, âme double (littéralement : δυο et ψυχη)\n<ol type=\"a\">\n<li>vacillant, incertain, doutant</li>\n<li>divisé en intérêt</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δι·ψύχος, ος, ον</b> <span>[ῡ]</span> partagé entre deux sentiments <i>ou</i> deux tendances, incertain, irrésolu, PHIL. <i>2, 663 ;</i> ORIG. <i>3, 413 Migne</i>.<br><span><b>Étym</b>. δίς, ψυχή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διψυχος - δίψυχος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G1375":"<h1>diogmos</h1>\n<p>Strong n° 1375 <i>Prononciation [dee-ogue-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>persécution, poursuite</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διωγμός, οῦ (ὁ) :<br>      1</b> poursuite, EUR. <i>I.T. 1435 ;</i> DS. <i>3, 38 ; au plur</i>. ESCHL. <i>Suppl. 1046 ;</i> EUR. <i>Or. 412 ;</i> PLUT. <i>M. 483</i> e ; <i>particul</i>. poursuite à la chasse, XÉN. <i>Cyr. 1, 4, 21, etc. ;</i><br><b>      2</b> persécution, NT. <i>Matth. 13, 21 ; Ap. 8, 1 ;</i> CLÉM. <i>1, 1293 ; 2, 629 Migne</i>.<br><span><b>Étym</b>. διώκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διωγμος - διωγμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 9 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G1376":"<h1>dioktes</h1>\n<p>Strong n° 1376 <i>Prononciation [dee-oke'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>persécuteur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διώκτης, ου (ὁ)</b> <i>c</i>. διωκτήρ, <i>d’où</i> persécuteur, NT. <i>1Tim. 1, 13 ;</i> NAZ. <i>1, 584 Migne</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διωκτης - διώκτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G1377":"<h1>dioko</h1>\n<p>Strong n° 1377 <i>Prononciation [dee-o'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire courir ou faire s'enfuir, amener à la fuite</li>\n<li>courir rapidement pour attraper une personne ou une chose\n<ol type=\"a\">\n<li>poursuivre</li>\n</ol>\n</li>\n<li>harceler, troubler, molester, persécuter</li>\n<li>courir après, suivre, sans idée hostile</li>\n<li>métaph : chercher sincèrement, vouloir fermement acquérir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>διώκω</b> <span>[ῐ]</span> <span>(<i>f</i>. διώξω <i>ou</i> διώξομαι, <i>ao</i> ἐδίωξα, <i>pf</i>. δεδίωχα ; <i>pass. ao</i>. ἐδιώχθην, <i>pf</i>. δεδίωγμαι)</span><br><b>   I</b> faire mouvoir rapidement, <i>en parl. du vent ou des rameurs qui poussent un navire,</i> OD. <i>5, 332 ;</i> νηῦς ῥίμφα διωκομένη, OD. <i>13, 162,</i> vaisseau lancé avec vitesse ; ἅρμα διώκειν, ESCHL. <i>Pers. 84,</i> lancer un char ; διώκειν πόδα, ESCHL. <i>Eum. 403 ;</i> EUR. <i>Or. 1344,</i> précipiter sa marche ; βέλος χερί, PD. <i>I. 8, 35</i> lancer un trait ; φόρμιγγα πλάκτρῳ, PD. <i>N. 5, 24,</i> frapper (<i>litt</i>. mettre en mouvement) une lyre avec le plectre ; <i>au pass</i>. être poussé vivement : <i>fig</i>. διώκομαι μολεῖν, SOPH. <i>El. 871,</i> je suis poussée à venir ; <i>d’où intr. en apparence (s.-e</i>. ἵππον, νῆα, <i>etc.)</i> s’élancer, IL. <i>23, 344, 424 ;</i> OD. <i>12, 182 ;</i> XÉN. <i>An. 7, 2, 20 ;</i><br><b>   II</b> poursuivre, <i>d’où :</i><br><b>      1</b> se mettre à la poursuite de, <i>acc</i>. IL. <i>22, 158 ; joint à</i> φέϐεσθαι, « faire fuir », IL. <i>5, 223 ; p. opp. à</i> φεύγειν : XÉN. <i>Mem. 2, 8, 6, etc. ;</i> δρόμῳ δ. XÉN. <i>An. 6, 3, 25,</i> poursuivre en courant ; <i>cf</i>. νῦν ὧδε θέεις ἀκίχητα διώκων, IL. <i>17, 75,</i> maintenant tu cours ainsi poursuivant sans atteindre ; δ. πεδίοιο, IL. <i>5, 223,</i> poursuivre à travers la plaine ; διώκειν πρός, PLUT. <i>Eum. 7,</i> poursuivre vers, jusqu’à, <i>etc. ; au pass</i>. être poursuivi, <i>d’où</i> fuir (<i>fut. moy. au sens pass</i>. διώξεται) SPT. <i>Amos 2, 16 ; Esaï. 13, 14 ;</i><br><b>      2</b> presser, contraindre, violenter, <i>d’où</i> chasser : δ. τινά, OD. <i>18, 408,</i> chasser qqn ; δ. τινὰ ἔκ γῆς, HDT. <i>9, 77,</i> chasser qqn d’un pays ;<br><b>      3</b> <i>t. de droit,</i> poursuivre, accuser devant les tribunaux, <i>p. opp. à</i> φεύγειν, être accusé, PLAT. <i>Euthyphr. 3</i> e ; ὁ διώκων, ESCHL. <i>Eum. 583 ;</i> AR. <i>Vesp. 902,</i> le poursuivant, le demandeur ; <i>p. opp. à</i> ὁ φεύγων, l’accusé, le défendeur, PLAT. <i>Rsp. 405</i> b ; δ. τινά τινός (τυραννίδος, <i>etc</i>.) HDT. <i>6, 104,</i> accuser qqn de qqe ch. (de tyrannie, <i>etc</i>.) ; τινά τινος εἵνεκεν, HDT. <i>6, 136, litt</i>. accuser qqn au sujet de qqe ch. ; θανάτου <i>ou</i> περὶ θανάτου τινὰ δ. XÉN. <i>Hell. 7, 3, 6,</i> poursuivre qqn pour une cause capitale ; γραφὴν <i>ou</i> δίκην δ. τινά, ANT. <i>115, 24 ;</i> DH. <i>7, 52,</i> intenter un procès à qqn ; <i>seul. avec l’acc. du grief :</i> τόν τινος φόνον δ. EUR. <i>Or. 1534, litt</i>. poursuivre le meurtre, <i>càd</i>. le meurtrier de qqn ; <i>avec l’inf</i>. ἐδίωκε τὸν Λεπίδου παῖδα βουλεύσεως ἐπὶ Καίσαρι, ἐδίωκε δὲ καὶ τὴν μητέρα τῷ παιδὶ συνεγνωκέναι, APP. <i>Civ. 4, 50,</i> il poursuivit le fils de Lépide pour complot contre César ; il poursuivit aussi la mère comme complice (<i>litt</i>. pour avoir conspiré avec le fils) ;<br><b>      4</b> s’attacher à, rechercher : τὰς τιμάς, THC. <i>2, 63 ;</i> τὴν ἡδονήν, PLAT. <i>Prot. 354</i> c ; τὴν ἀλήθειαν, PLAT. <i>Gorg. 482</i> e, poursuivre les honneurs, le plaisir, la vérité, <i>etc. ;</i> δ. τινά, XÉN. <i>Mem. 2, 8, 6 ; 4, 4, 24,</i> s’attacher à qqn (ami, maître, <i>etc</i>.) ; δ. τοὺς ξηροὺς τόπους, TH. <i>H.P. 1, 4, 2,</i> rechercher les lieux secs, <i>en parl. de plantes ;</i><br><b>      5</b> continuer sans interruption, poursuivre (sa route) <i>abs</i>. PLUT. <i>Cæs. 17 ;</i> CHARÈS (ATH. <i>575</i> e) ; <i>fig</i>. δ. λόγον, PLAT. <i>Soph. 251</i> a (<i>cf. Rsp. 454</i> a) poursuivre un raisonnement ; <i>p. suite,</i> exposer en détail, décrire : ὕμνῳ ἀρετάς, PD. <i>I. 3, 21,</i> chanter les mérites (de qqn) ;<br><b><i>Moy.</i></b> :<br><b>      1</b> poursuivre : τινα πεδίοιο, IL. <i>21, 602,</i> poursuivre qqn à travers la plaine ;<br><b>      2</b> chasser : δόμοιο, OD. <i>18, 8,</i> d’une maison ;<br><b>      3</b> poursuivre en justice : τινα δειλίας, AR. <i>Eq. 368,</i> poursuivre qqn pour crime de lâcheté ;<br><b>      4</b> poursuivre, s’attacher à, <i>acc., joint à</i> φιλέω, PLAT. <i>Theæt. 168</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. inf. poét</i>. διωκέμεναι, OD. <i>15, 278, ou</i> διωκέμεν, IL. <i>5, 223. Impf. duel</i> διώκετον, IL. <i>10, 364. Fut</i>. διώξω, PD. <i>O. 3, 45 ; I. 8, 35 ;</i> XÉN. <i>An. 1, 4, 8 ; Cyr. 6, 3, 13 ;</i> DÉM. <i>989, 11, etc. et</i> διώξομαι, THC. <i>7, 85 ;</i> XÉN. <i>Cyr. 1, 3, 14 ; 4, 1, 19 ; 4, 3, 18 ;</i> PLAT. <i>Prot. 313</i> c, <i>Theæt. 168</i> a. <i>Pf. rare</i> δεδίωχα, HYPÉR. <i>Lyc. p. 29, Baiter-Sauppe. — Pass. prés. 1 pl</i>. διωκόμεθα, AR. <i>Ach. 700 ou</i> διωκόμεσθα, EUR. <i>Her. 50. Fut. réc</i>. διωχθήσομαι, DS. <i>19, 95 ;</i> POLYEN <i>2, 13 (v. le moy.). Ao</i>. ἐδιώχθην, HDT. <i>5, 73 ;</i> ANT. <i>2, 3, 6 Baiter-Sauppe, etc. Pf. réc. part</i>. δεδιωγμένος, NT. <i>Matth. 5, 10. — Moy. prés</i>. διώκομαι, ESCHL. <i>Ch. 289 ; part</i>. -όμενος, DH. <i>1, 87. Impf. 3 sg. poét</i>. διώκετο, IL. <i>21, 602 ;</i> OD. <i>18, 8. Fut</i>. διώξομαι, <i>au sens act. (v. ci-dessus) ; au sens pass. 3 sg</i>. διώξεται, SPT. <i>ll. cc. ; inf</i>. διώξεσθαι DH. <i>3, 20</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">διωκω - διώκω</font>\n<br><br>forme du verbe primaire dio (s'enfuir)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n44 fois dans 43 versets de 15 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n<li>Actes (9)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (5)</li>\n<li>Philippiens (3)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1378":"<h1>dogma</h1>\n<p>Strong n° 1378 <i>Prononciation [dog'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>doctrine, décret, ordonnance, édit\n<ol type=\"a\">\n<li>un décret public</li>\n<li>du Sénat Romain</li>\n<li>des gouvernants</li>\n</ol>\n</li>\n<li>règles et prescriptions de la loi de Moïse ; avec une idée de sévérité et de menace de jugement</li>\n<li>certains décrets des apôtres relatifs à une vie droite</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόγμα, ατος (τὸ)</b> <i>propr</i>. ce qui paraît bon, <i>d’où :</i><br><b>      1</b> opinion, PLAT. <i>Rsp. 538</i> c, <i>Phædr. 257</i> c, <i>etc. ; particul</i>. doctrine philosophique <i>ou</i> autre, PLUT. <i>M. 14</i> c, <i>etc. ;</i> DL. <i>3, 52 ;</i><br><b>      2</b> décision, décret, arrêt, PLAT. <i>Leg. 644</i> d ; DÉM. <i>62, 4, 278, 17 ;</i> POL. <i>3, 27, 7 ; 20, 4, 6 ; etc. ;</i> δόγμα ποιεῖσθαι <i>avec l’inf</i>. XÉN. <i>An. 3, 3, 5,</i> rendre un décret pour, <i>etc. ; à Rome,</i> δόγμα τῆς συγκλήτου, POL. <i>6, 13, 2, ou</i> βουλῆς, DH. <i>3, 1723 Reiske = lat</i>. senatus consultum, décret du sénat.<br><span><b><span class=\"arrow\"></span></b> <i>Différ. de</i> ψήφισμα, <i>qui s’emploie seul. en parl. des décrets de l’</i>ἐκκλησία.<br><span><b>Étym</b>. δοκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δογμα - δόγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1379":"<h1>dogmatizo</h1>\n<p>Strong n° 1379 <i>Prononciation [dog-mat-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>décréter, commander, enjoindre, imposer une ordonnance, être soumis à une décision</li>\n<li>soutenir une opinion, d'où : juger décider, déclarer</li>\n<li>enseigner comme une doctrine</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δογματίζω</b> <span>[ᾰ]</span><br><b>      1</b> soutenir une opinion, <i>acc</i>. ARR. <i>Epict. 3, 7, 18 ; avec l’inf</i>. DS. <i>4, 83 ; d’où en gén</i>. juger, décider, déclarer : τινὰ καλήν, ANTH. <i>9, 576,</i> qu’une femme est belle ;<br><b>      2</b> enseigner comme une doctrine, DL. <i>3, 52 ;</i><br><b>      3</b> décréter, SPT. <i>1Esdr. 6, 33 ; Esth. 3, 9 ; Dan. 2, 13 ; 2 Macc. 10, 8, etc.,</i> JOS. <i>A.J. 14, 10, 22 ; etc. ; p. suite,</i> soumettre à un décret, à une décision, <i>d’où, au pass</i>. être soumis à une décision, NT. <i>Col. 2, 20</i>.<br><span><b>Étym</b>. δόγμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δογματιζω - δογματίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1380":"<h1>dokeo</h1>\n<p>Strong n° 1380 <i>Prononciation [dok-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir une opinion, penser, supposer</li>\n<li>sembler, chose réputée</li>\n<li>il me semble\n<ol type=\"a\">\n<li>Je pense, je juge : c'est ainsi</li>\n<li>il me paraît bon, il me plaît, j'ai déterminé</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοκέω-ῶ</b> <span>(<i>f</i>. δόξω, <i>ao</i>. ἔδοξα, <i>pf. inus., v. ci-dessous ; pl.q.pf</i>. ἐδεδόχειν ; <i>pass. ao</i>. ἐδόχθην, <i>pf</i>. δέδογμαι, <i>pl.q.pf</i>. ἐδεδόγμην)</span><br><b>A</b> sembler, paraître, <i>d’où :</i><br><b>   I</b> <i>abs. :</i><br><b>      1</b> avoir l’apparence de, <i>p. opp. à la</i> réalité, paraître, <i>p. opp. à</i> être : οὐ γὰρ δοκεῖν ἄριστος, ἀλλ' εἶναι θέλει, ESCHL. <i>Sept. 592,</i> car il veut non paraître juste et brave, mais l’être ; μελετητέον οὐ τὸ δοκεῖν ἀγαθόν, ἀλλὰ τὸ εἶναι, PLAT. <i>Gorg. 527</i> b, car il faut avoir à cœur non de paraître bon, mais de l’être ; μὴ ὄντες ἀλλὰ δοκοῦντες, PLAT. <i>Rsp. 421</i> a, des gens qui ne sont pas, mais qui ont l’air d’être (les gardiens des lois, <i>etc.) ; de même p. opp. à</i> βούλεσθαι : τῷ δοκεῖν μὲν οὐχὶ χρῄζων, τῷ δὲ βούλεσθαι θέλων, EUR. <i>I.A. 338,</i> en apparence tu n’y aspirais point ; mais, à sonder ta volonté, tu le désirais ;<br><b>      2</b> avoir de l’apparence, faire bonne figure, paraître qqe ch. : ὁρῶ τὰ τῶν θεῶν, ὡς τὰ μὲν πυργοῦσ' ἄνω τὰ μηδὲν ὄντα, τὰ δὲ δοκοῦντ' ἀπώλεσαν, EUR. <i>Tr. 608,</i> je vois comme la volonté des Dieux élève jusqu’aux sommets ce qui n’est rien, et renverse jusqu’à le détruire ce qui a l’air d’être qqe ch. ; εὐτυχίαν τῶν πάρος οὐ δοκούντων, EUR. <i>Her. 897,</i> la prospérité de ceux qui auparavant ne paraissaient pas (être qqe ch.) ; οἱ δοκοῦντες, EUR. <i>Hec. 295,</i> ceux qui ont du renom, <i>p. opp. à</i> οἱ ἀδοξοῦντες ;<br><b>   II</b> <i>avec un déterminatif (verbe ou nom)</i> :<br><b>      1</b> paraître, sembler : <i>en parl. de visions, de songes :</i> ἐδοξάτην μοι δύο γυναῖκ' εἰς ὄψιν μολεῖν, ESCHL. <i>Pers. 181,</i> je crus voir deux femmes s’avancer sous mes yeux ; <i>joint pléonast. à</i> φαίνεσθαι : ὥστε λευκοτέραν τε καὶ ἐρυθροτέραν τοῦ ὄντος δοκεῖν φαίνεσθαι, XÉN. <i>Mem. 2, 1, 22,</i> au point de paraître plus blanche et plus rouge qu’elle n’était en réalité ; <i>cf</i>. XÉN. <i>Cyr. 8, 3, 14 ;</i> PLAT. <i>Rsp. 381</i> e ;<br><b>      2</b> paraître (après réflexion <i>ou</i> après examen) : ὥς μοι δοκεῖ εἶναι ἄριστα, IL. <i>12, 215,</i> comme cela me semble être le mieux ; δοκέεις δέ μοι οὐκ ἀπινύσσειν, OD. <i>5, 342,</i> tu me parais ne pas manquer de sagesse ; <i>avec l’inf. fut</i>. δοκέει δέ μοι ὧδε λώϊον ἔσσεσθαι, IL. <i>6, 338,</i> cela me semble devoir être mieux ainsi ; <i>avec l’inf. ao. (jamais dans Hom</i>.) : τί δ' ἂν δοκεῖ σοι Πρίαμος ποιῆσαι ; ESCHL. <i>Ag. 935,</i> que te semble-t-il qu’aurait fait Priam ? ἄξιοι ὑμῖν δοκοῦντες, THC. <i>1, 76,</i> nous qui vous paraissons dignes de, <i>etc. ; particul. en parl. de gens soupçonnés d’un crime :</i> ἂν δ' ἁλῷ καὶ δοκῇ τοὔργον εἰργάσθαι, DÉM. <i>643, 25,</i> s’il vient à être pris et qu’il paraisse avoir fait le coup ; <i>cf</i>. THC. <i>2, 21 ; 5, 16 ;</i><br><b>      3</b> <i>p. suite,</i> avoir la réputation d’être, être considéré comme, passer pour : οἱ δοκοῦντες εἶναί τι, PLAT. <i>Gorg. 472</i> a, ceux qui passent pour être qqe ch. ; ἐδόκει τις εἶναι, PLUT. <i>Arist. 1,</i> il passait pour être un homme (d’un jugement supérieur) ;<br><b>   III</b> paraître, avoir l’air de, feindre de, <i>d’ord. précédé d’une nég</i>. (οὐ, μή) : οὔτε ἀνεϐόησεν οὔτε ἔδοξε μαθέειν, HDT. <i>1, 10,</i> ni elle ne jeta un cri, ni elle ne parut s’être aperçue de rien ; ἤκουσα τοῦ λέγοντος οὐ δοκῶν κλύειν, EUR. <i>Med. 67,</i> j’entendais, sans avoir l’air d’entendre, celui qui parlait ; πόσους δοκεῖς ὁρῶντας μὴ δοκεῖν ὁρᾶν, EUR. <i>Hipp. 462,</i> combien voient, à ton avis, qui n’ont pas l’air de voir (<i>cf</i>. XÉN. <i>Hell. 4, 5, 6 ;</i> PLAT. <i>Euthyphr. 5</i> c) ; μὴ νῦν ὁρᾶν δοκῶμεν αὐτόν, AR. <i>Pax 1051,</i> pour le moment, n’ayons pas l’air de le voir ;<br><b>   IV</b> paraître bon : εἰ δοκεῖ σοι ταῦτα, ESCHL. <i>Ag. 944,</i> si cela te paraît convenable ; τὸ σοὶ δοκοῦν ἡδέως ἂν ἀκούοιμι, PLAT. <i>Rsp. 487</i> e, j’entendrais volontiers ton avis ; παρὰ τὸ δοκοῦν ἡμῖν, THC. <i>1, 84,</i> contrairement à ce qui nous paraît bon ; τὰ δοκοῦντα περὶ τῆς ἀληθείας λέγειν, PLAT. <i>Rsp. 349</i> a, exprimer son opinion sur la vérité ; <i>particul. en parl. de décisions ayant force de loi, de décrets, etc. :</i> τοιαῦτ' ἔδοξε τῷδε Καδμείων τέλει, ESCHL. <i>Sept. 1025,</i> voilà ce qu’ont décidé les magistrats des Cadméens ; <i>impers</i>. ἔδοξε <i>dans la formule initiale des décrets :</i> ἔδοξε τῇ βουλῇ, AR. <i>Th. 372 ;</i> ἔ. τῷ δήμῳ, THC. <i>4, 118 ;</i> ἔ. τῇ βουλῇ καὶ τῷ δήμῳ, PLAT. <i>Phædr. 258</i> a, le sénat a décidé, le peuple a décidé, le sénat et le peuple ont décidé ; τὰ δεδογμένα, HDT. <i>3, 76,</i> le décret, la décision ; τὰ δόξαντα, SOPH. <i>El. 29,</i> les résolutions (d’Oreste) ; <i>de même dans un grand nombre de locut. formant parenthèse :</i> ὡς ἐμοὶ δοκεῖ, ESCHL. <i>Sept. 369,</i> à mon avis ; εἰ δοκεῖ, SOPH. <i>Ph. 1402,</i> si tu veux ; <i>avec l’inf</i>. ὡς ἐμοὶ δοκέειν, HDT. <i>2, 124 ;</i> ἐμοὶ δοκεῖν, ESCHL. <i>Pers. 246 ;</i> ἐμοὶ δοκέειν, HDT. <i>3, 45 ;</i> δοκεῖν ἐμοί, SOPH. <i>El. 410 ;</i> δοκέειν ἐμοί, HDT. <i>1, 172 ;</i> δοκεῖν δέ μοι, THC. <i>8, 64 ; ou sans</i> μοι, δοκεῖν, XÉN. <i>An. 4, 5, 1,</i> à ce qu’il me semble, à mon avis ; — <i>au participe abs</i>. δόξαν αὐτοῖς ὥστε διαναυμαχεῖν (<i>pour</i> ὅτε ἔδοξεν αὐτοῖς, <i>etc</i>.) THC. <i>8, 79,</i> comme ils avaient décidé d’engager le combat sur mer ; δόξαν ἡμῖν ταῦτα (<i>s.-e</i>. πράττειν) PLAT. <i>Prot. 314</i> c, lorsque nous eûmes pris ce parti ; δόξαντα δὲ ταῦτα καὶ περανθέντα, τὰ στρατεύματα ἀπῆλθε, XÉN. <i>Hell. 3, 2, 19,</i> lorsque ces décisions eurent été prises et exécutées, les troupes s’éloignèrent, δόξαντος τούτου, XÉN. <i>Hell. 1, 1, 36,</i> cela ayant été décidé ;<br><b>B</b> penser, croire, <i>d’où :</i><br><b>   I</b> se figurer (par l’imagination), <i>en parl. de visions, de songes :</i> τεκεῖν δράκοντ' ἔδοξεν, ESCHL. <i>Ch. 527,</i> elle crut avoir enfanté un dragon ; ἔδοξ' ἰδεῖν τρεῖς κόρας, EUR. <i>Or. 408,</i> je crus voir trois vierges (les Euménides) ; <i>cf</i>. EUR. <i>I.T. 44 ;</i> AR. <i>Vesp. 15 ;</i><br><b>   II</b> croire (après réflexion <i>ou</i> après examen) :<br><b>      1</b> <i>prop</i>. croire, juger, penser : ὁρᾷς γὰρ οὐδὲν ὧν δοκεῖς σάφ' εἰδέναι, EUR. <i>Or. 259,</i> car tu ne vois rien de ce que tu crois savoir et tenir pour certain ; <i>rar. sans inf</i>. τούτους τι δοκεῖτε ; XÉN. <i>An. 5, 7, 26,</i> ces gens que croyez-vous qu’ils sont ? <i>avec</i> περί : δοκέω δέ, εἴ τι περὶ τῶν θείων πρηγμάτων δοκέειν δεῖ, HDT. <i>9, 65,</i> or je pense, s’il est permis de penser qqe ch. des affaires divines ; <i>avec un inf. ao</i>. ἡδέως δ' ἄν μοι δοκῶ κοινωνῆσαι, XÉN. <i>Cyr. 8, 7, 25,</i> il me semble qu’il me plairait de devenir une partie de ce tout ; <i>avec l’inf. prés</i>. ταῦτ' ἄν μοι δοκῶ ἡδέως ἀκούειν σου, XÉN. <i>Œc. 6, 11,</i> j’imagine que je t’entendrais avec plaisir expliquer, <i>etc. ; dans un grand nombre de locut. formant parenthèse :</i> δοκῶ μοι, PLAT. <i>Theag. 121</i> d ; ἐμοὶ μὲν δοκῶ, LYNC. (ATH. <i>129</i> a) je crois, je pense : <i>ou sans</i> μοι : δοκῶ μέν, SOPH. <i>El. 61, 547 ; O.C. 995 ;</i> EUR. <i>Suppl. 771 ;</i> PLAT. <i>Parm. 126</i> b, <i>m. sign., de même</i> δοκεῖς, PLAT. <i>Leg. 687</i> e, tu le penses bien ; τοῦτον λαϐοῦσα, πῶς δοκεῖς ; καθύϐρισεν, EUR. <i>Hipp. 446,</i> Vénus s’empare de lui, et l’accable, Dieu sait comme ! κἄπειθ' ὁ δῆμος ἀναϐοᾷ, πόσον δοκεῖς ; AR. <i>Eccl. 399,</i> et après cela le peuple jette les hauts cris, tu peux penser combien ;<br><b>      2</b> penser, espérer : ἐπεὶ δοκέω νικησέμεν Ἕκτορα, IL. <i>7, 192,</i> car je pense vaincre Hector ; οὐ γάρ σε δοκέω πείθεσθαί μοι, HDT. <i>1, 8,</i> car je n’espère pas te persuader ;<br><b>      3</b> penser à, songer à, se proposer de : εὖτ' ἂν δ' ἀείδειν δοκῶ, ESCHL. <i>Ag. 16,</i> et lorsque je pense à chanter ;<br><b>   III</b> juger bon, <i>d’où</i> décider, <i>avec l’inf. fut</i>. ταῦτά μοι δοκῶ ὑπερϐήσεσθαι, ESCHN. <i>61, 8,</i> je suis décidé à passer par là-dessus ; τὸν οὖν Δία μοι δοκῶ χαίρειν ἐάσας ἐνθάδ' αὐτοῦ καταμενεῖν, AR. <i>Pl. 1186,</i> je suis donc décidé à envoyer promener Zeus et à rester résolument ici même ; <i>sans</i> μοι : γνῶθι τίνα πέμπειν δοκεῖς (<i>conj</i>. -εῖ) ESCHL. <i>Sept. 650,</i> décide qui tu crois devoir envoyer ; <i>au pass</i>. être jugé bon, paraître bon, être décidé : οὕτω δέδοκται, SOPH. <i>Ph. 1277,</i> cela a été ainsi décidé ; δέδοκταί μου κατθανεῖν, EUR. <i>I.A. 1375,</i> je suis condamnée à mourir ; <i>de même au participe :</i> πάλαι ποτ' ἐστὶ τοῦτ' ἐμοὶ δεδογμένον, EUR. <i>Her. 1,</i> depuis longtemps déjà c’est une opinion arrêtée dans mon esprit ; δεδογμέν', ὡς ἔοικε, τήνδε κατθανεῖν, SOPH. <i>Ant. 576,</i> c’est chose décidée, selon toute apparence, qu’elle meure ; — <i>avec le dat. de la personne à qui s’applique la décision :</i> δέδοκται τοῖσι πρώτοισι τῶν μαντίων ἀπόλλυσθαι, HDT. <i>4, 68,</i> il est décidé que les premiers des devins doivent périr ;<br><b><i>Moy.</i></b> (<i>part. prés. ion</i>. δοκεύμενος) s’imaginer, penser, <i>avec l’inf. fut</i>. OPP. <i>C. 4, 109</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Act. prés. ind. ion</i>. δοκέω, IL. <i>7, 192, etc. ;</i> HDT. <i>2, 125 ; etc. ; opt. ion</i>. δοκέοιμι, THGN. <i>339 ; 3 sg</i>. -έοι, HDT. <i>8, 19 ; opt. att</i>. δοκοίην, THC. <i>4, 11 ;</i> ISOCR. <i>5, 98 Baiter-Sauppe, etc. Impf. ion</i>. ἐδόκεον, HDT. <i>3, 65 ; 3 sg</i>. ἐδόκεε, HDT. <i>1, 10 ; 1 pl. dor</i>. ἐδοκεῦμες, THCR. <i>Idyl. 13, 1 ; 3 pl. poét</i>. δόκεον, A. RH. <i>4, 666. Impf. itér. réc</i>. δοκέεσκον, ANTH. <i>5, 299. Fut</i>. δόξω, PD. <i>N. 4, 37,</i> HDT. <i>8, 80 ;</i> ATT. (ESCHL. <i>Ag. 415 ;</i> PLAT. <i>Phædr. 275</i> a, <i>etc.) ; fut. dor. 2 pl</i>. δοξεῖτε, AR. <i>Ach. 741 ; sur le fut</i>. δοκήσω, <i>v. ci-dessous. Ao. opt</i>. δόξαιμι, PLAT. <i>Ap. 34</i> c ; αις, PLAT. <i>Phædr. 275</i> d ; <i>mais</i> δόξειε, PLAT. <i>Rsp. 337</i> e ; δόξαιμεν PLAT. <i>Pol. 280</i> c ; <i>2 pl. inus. ; 3 pl</i>. δόξαιεν (δόξειαν, <i>Dind. Sauppe</i>) XÉN. <i>Cyr. 2, 1, 23. Pf. inus. Pl.q.pf. 3 pl</i>. ἐδεδόχεσαν, DC. <i>44, 26. Pass. ao</i>. ἐδόχθην, POL. <i>21, 8 ;</i> DS. <i>11, 50 ; etc. Pf</i>. δέδογμαι, HDT. <i>8, 100 ;</i> ATT. (THC. <i>3, 49 ; etc.). Pl.q.pf. 3 sg</i>. ἐδέδοκτο (<i>var</i>. δέδοκτο) HDT. <i>5, 96 ; 9, 74 ;</i> PLAT. <i>Menex. 244 ;</i> PLUT. <i>Cæs. 28. — Les formes des fut. ao. et pf. en</i> δοκη-, ἐδοκη-, δεδοκη- <i>sont poét., ion., dor. ou de prose réc. : fut</i>. δοκήσω, ESCHL. <i>Pr. 386 ;</i> EUR. <i>Her. 261 ;</i> AR. <i>Nub. 562, Ran. 737, etc. ; en ion. seul</i>. HDT. <i>4, 74 ; fut. dor</i>. δοκησῶ, THCR. <i>Idyl. 1, 150. Ao</i>. ἐδόκησα, PD. <i>O. 13, 56 ; 3 sg</i>. δόκησε, OD. <i>20, 92 ; impér. 3 sg</i>. δοκησάτω, ESCHL. <i>Sept. 1036 ;</i> JOS. <i>A.J. 17, 6, 5 ; part</i>. δοκήσας, EUR. <i>Suppl. 129 ;</i> AR. <i>Ran. 1485. Pf. 3 sg</i>. δεδόκηκε, ESCHL. <i>Eum. 309 ; inf</i>. δεδοκηκέναι, ORIG. <i>Ref. hær. p. 175 Mill. Pass. ao</i>. ἐδοκήθην, ANTH. <i>8, 188 ; part</i>. δοκηθείς, EUR. <i>Alc. 1161, etc. Pf. 2 sg</i>. δεδόκησαι, EUR. <i>Med. 763 ; 3 sg</i>. δεδόκηται, PD. <i>N. 5, 19 ; de même, ion</i>. HDT. <i>7, 16 ;</i> HPC. <i>Epist. 9, 402</i>.<br><span><b>Étym</b>. δέκομαι, <i>v</i>. δέχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκεω - δοκέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n62 fois dans 61 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (10)</li>\n<li>Marc (2)</li>\n<li>Luc (10)</li>\n<li>Jean (7)</li>\n<li>Actes (9)</li>\n<li>1 Corinthiens (9)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (5)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (4)</li>\n<li>Jacques (2)</li>\n</ul>\n</td></tr>\n</table>","G1381":"<h1>dokimazo</h1>\n<p>Strong n° 1381 <i>Prononciation [dok-im-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre à l'épreuve, examiner, éprouver (épreuve de métaux)</li>\n<li>reconnaître comme véritable après examen, juger digne, approuver, juger bon</li>\n<li>faire l'essai de, choisir, reconnaître</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοκιμάζω</b> <span>[ῐ]</span> <span>(<i>f</i>. άσω, <i>ao. et pf. inus. ; pass. ao</i>. ἐδοκιμάσθην, <i>pf</i>. δεδοκίμασμαι)</span><br><b>      1</b> éprouver, mettre à l’épreuve : τι ISOCR. <i>240</i> d ; ARSTT. <i>Nic. 3, 10, 9 ; H.A. 1, 6, 11,</i> qqe ch. (métal, monnaie, étoffe, <i>etc</i>.) ; τινά, THC. <i>6, 53 ;</i> XÉN. <i>Mem. 2, 6, 1 ;</i> ISOCR. <i>24</i> e, <i>etc</i>. qqn (ami, dénonciateur, <i>etc</i>.) ;<br><b>      2</b> <i>p. suite,</i> approuver, juger bon : τι, XÉN. <i>Mem. 1, 2, 4,</i> qqe ch. ; <i>au pass</i>. être approuvé, THC. <i>2, 35 ;</i> PLAT. <i>Rsp. 407</i> c ; DÉM. <i>281, 26 ;</i> PLUT. <i>M. 11</i> f, <i>18</i> f ; <i>particul. à Athènes,</i> vérifier l’aptitude <i>ou</i> l’éligibilité, <i>en parl. des nouveaux soldats enrégimentés dans la cavalerie,</i> LYS. <i>142, 36 ; des candidats aux charges (magistrats <i>ou</i> généraux</i>) PLAT. <i>Leg. 759</i> c, <i>765</i> b ; DÉM. <i>551, 1 ; 1381, 6 ; des jeunes gens à admettre parmi les éphèbes,</i> LYS. <i>145, 41 ;</i> AR. <i>Vesp. 578 ;</i> PLAT. <i>Crit. 51</i> d ; ISOCR. <i>238</i> c ; DÉM. <i>565, 17 ; 814, 20 ; p. ext</i>. reconnaître capable de, <i>ou, avec une nég.,</i> incapable de, <i>inf</i>. NT. <i>Rom. 1, 28 ;</i> JOS. <i>A.J. 2, 7, 4 ;</i><br><b><i>Moy.</i></b> <span>(<i>ao. inf</i>. -άσασθαι)</span> MÉN. (STOB. <i>Fl. 72, 2, dout</i>.) faire l’essai de, choisir.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. réc</i>. δοκιμῶ, SPT. <i>Jer. 9, 7</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκιμαζω - δοκιμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n24 fois dans 21 versets de 12 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G1382":"<h1>dokime</h1>\n<p>Strong n° 1382 <i>Prononciation [dok-ee-may']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>épreuve, examen</li>\n<li>éprouvé</li>\n<li>une preuve, contrôler la valeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοκιμή, ῆς (ἡ)</b> <span>[ῐ]</span><br><b>      1</b> épreuve, essai, expérience, NT. <i>2Cor. 8, 2 ;</i> DIOSC. <i>4, 186 ;</i><br><b>      2</b> indice probant, preuve, NT. <i>2Cor. 13, 3 ;</i><br><b>      3</b> caractère éprouvé, fidélité <i>ou</i> foi éprouvée, NT. <i>2Cor. 2, 9 ;</i> PHIL. <i>2, 22</i>.<br><span><b>Étym</b>. δόκιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκιμη - δοκιμή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>2 Corinthiens (4)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1383":"<h1>dokimion</h1>\n<p>Strong n° 1383 <i>Prononciation [dok-im'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la preuve</li>\n<li>ce par quoi une chose est éprouvée, un contrôle</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοκίμιον</b>, <i>v</i>. δοκιμεῖον.<br><br>\n<b>δοκιμεῖον</b>, <i>mieux que</i> <b>δοκίμιον, ου (τὸ)</b> <span>[κῐ]</span><br><b>      1</b> moyen d’éprouver, d’essayer, PLAT. <i>Tim. 65</i> c (<i>vulg</i>. -ιον) ; DH. <i>Rhet. 11 ;</i> PLUT. <i>M. 230</i> b ; HDN <i>2, 10, 12 ;</i><br><b>      2</b> <i>p. suite,</i> organe, instrument, LGN <i>32, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. seul</i>. δοκιμεῖον, CIA. <i>2, 684, 5 (après 368 av. J.C.) ; 701, 2, 30 (344 av. J.C</i>.).<br><span><b>Étym</b>. δόκιμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκιμιον - δοκίμιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G1384":"<h1>dokimos</h1>\n<p>Strong n° 1384 <i>Prononciation [dok'-ee-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>accepté, particulièrement pour les pièces de monnaie</li>\n<li>accepté, plaisant, acceptable, reconnu</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόκιμος, ος, ον</b> <span>[ῐ]</span><br><b>   I</b> croyable, présumable, ESCHL. <i>Pers. 87 ;</i><br><b>   II</b> éprouvé, dont on a fait l’essai (métal, monnaie) DÉM. <i>931, 3, etc. ; fig</i>. éprouvé, qui a fait ses preuves, <i>d’où :</i><br><b>      1</b> considéré, estimé. NT. <i>1Cor. 11, 19 ;</i> HDT. <i>1, 65 ; 3, 143 ; 7, 117 ;</i> EUR. <i>Suppl. 277 ;</i><br><b>      2</b> acceptable, <i>d’où</i> agréable, HDT. <i>7, 162 ;</i> τινι, PD. <i>N. 3, 18,</i> à qqn ;<br><b>      3</b> <i>p. ext</i>. considérable, <i>en parl. d’un fleuve,</i> HDT. <i>7, 129</i>.<br><span>•<i> Sup</i>. -ώτατος, EUR. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκιμος - δόκιμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1385":"<h1>dokos</h1>\n<p>Strong n° 1385 <i>Prononciation [dok-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une poutre, une solive</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n① <b>δοκός, οῦ (ἡ) :<br>      1</b> poutre, solive, IL. <i>17, 744 ;</i> OD. <i>22, 176 ;</i> THC. <i>4, 112 ;</i> AR. <i>Nub. 1496 ;</i> ARSTT. <i>Rhet. 3, 12, 3 ;</i> LUC. <i>Her. 5 ; particul</i>. faîtage (d’un toit) ATHÉNÉE MÉC. ;<br><b>      2</b> météore en forme de poutre, DL. <i>5, 81</i>.<br><span><b><span class=\"arrow\"></span></b> ὁ δ. LUC. <i>V.H. 2, 1 ;</i> DÉMÉTR. (DL. <i>5, 81</i>).</span><br><br>\n② <b>δόκος, ου (ὁ)</b> opinion, XÉNOPHAN. <i>fr. 14 ;</i> CALL. <i>fr. 100</i>.<br><span><b>Étym</b>. <i>cf</i>. δοκέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοκος - δοκός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G1386":"<h1>dolios</h1>\n<p>Strong n° 1386 <i>Prononciation [dol'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>trompeur, artificieux, rusé, fourbe, machiavélique</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόλιος, α</b> <i>ou</i> <b>ος, ον</b>, fourbe, rusé, trompeur, <i>en parl. de choses (parole, machination, etc</i>.) OD. <i>4, 455 ; 9, 282, etc. ;</i> HÉS. <i>Th. 160, 540 ; œil, regard,</i> ESCHL. <i>Pr. 570 ; lèvres,</i> SPT. <i>Prov. 26, 3 ; langue, ibid. 51, 4 ;</i> δ. κύκλος, OD. <i>4, 792,</i> cercle trompeur (que forment les chasseurs autour d’un lion) ; <i>en parl. de personnes,</i> PD. <i>P. 2, 150 ;</i> SOPH. <i>Aj. 47, Ph. 608 ; d’Aphrodite,</i> EUR. <i>Hel. 242 ; d’Hermès,</i> SOPH. <i>Ph. 133 ;</i> AR. <i>Pl. 1157</i>.<br><span>•<i> Sup</i>. -ώτατος, JOS. <i>B.J. 4, 3, 13</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, EUR. <i>Alc. 34, Tr. 530 ;</i> SPT. <i>Prov. 51, 4 ; etc</i>.<br><span><b>Étym</b>. δόλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δολιος - δόλιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1387":"<h1>dolioo</h1>\n<p>Strong n° 1387 <i>Prononciation [dol-ee-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tromper, utiliser la tromperie, duper, être fourbe, rusé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δολιόω-ῶ :<br>      1</b> être fourbe, rusé, SYMM. <i>Prov. 26, 19 ;</i><br><b>      2</b> <i>act</i>. tromper : τινά τι, SPT. <i>Num. 25, 17,</i> qqn en qqe ch. ; <i>abs</i>. SPT. <i>Ps. 6, 9 ; au pass. ibid. 104, 24</i>.<br><span><b>Étym</b>. δόλιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δολιοω - δολιόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G1388":"<h1>dolos</h1>\n<p>Strong n° 1388 <i>Prononciation [dol'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>habileté, tromperie, astuce</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόλος, ου (ὁ) :<br>   I</b> amorce, OD. <i>12, 252 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> tout objet servant à tromper, piège (<i>le cheval de Troie,</i> OD. <i>8, 494 ; filet de Vulcain,</i> OD. <i>8, 276, etc. ; piège pour les rats,</i> BATR. <i>116</i>) ;<br><b>      2</b> <i>fig. p. suite,</i> ruse, artifice, <i>p. opp. à la</i> force (κράτος) IL. <i>7, 142 (ou</i> ἰσχύς), ESCHL. <i>Pr. 213 ; à la</i> violence (βίη) OD. <i>9, 406 ; à l’idée de</i> agir ouvertement (ἀμφαδόν) OD. <i>11, 120 ; au plur</i>. δόλοι, IL. <i>3, 202 ; 4, 339 ;</i> OD. <i>3, 119,</i> ruses ; <i>adv</i>., δόλῳ, HDT. <i>9, 90 ;</i> δόλοις, SOPH. <i>O.R. 960 ;</i> ἐκ δόλου, SOPH. <i>El. 279 ;</i> ἐν δόλῳ, SOPH. <i>Ph. 102 ;</i> σὺν δόλῳ, SOPH. <i>Aj. 1245 ;</i> EUR. <i>Hec. 1269 ;</i> δόλῳ καὶ ἀπάτῃ, DH. <i>3, 23,</i> par ruse et fourberie ; μετὰ δόλου καὶ τέχνης, ISOCR. <i>195</i> e, avec ruse et artifice.<br><span><b>Étym</b>. <i>p.-ê. pré-grec avec emprunt lat</i>. dolus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δολος - δόλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Pierre (3)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G1389":"<h1>doloo</h1>\n<p>Strong n° 1389 <i>Prononciation [dol-o'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prendre au piège</li>\n<li>corrompre, altérer, frauder</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δολόω-ῶ :<br>   I</b> tromper au moyen d’une amorce, <i>d’où :</i><br><b>      1</b> tromper, HÉS. <i>Th. 494 ;</i> HDT. <i>1, 212 ;</i> ESCHL. <i>Ag. 273, 1636 ;</i> SOPH. <i>Ph. 1288 ;</i> EUR. <i>I.A. 898 ; Alc. 12 ;</i><br><b>      2</b> s’emparer par ruse de, <i>acc</i>. XÉN. <i>Cyr. 1, 6, 28 ;</i><br><b>   II</b> altérer par fraude, <i>d’où :</i><br><b>      1</b> falsifier, changer, altérer, <i>acc</i>. (de l’encens, DIOSC. <i>1, 81 ;</i> du vin, LUC. <i>Herm. 59</i>) ;<br><b>      2</b> dissimuler, déguiser, <i>acc</i>. SOPH. <i>Ph. 129</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. poét. 3 sg</i>. δόλωσεν, HÉS. (SCH.-A. RH. <i>1, 156</i>).</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δολοω - δολόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1390":"<h1>doma</h1>\n<p>Strong n° 1390 <i>Prononciation [dom'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un don, cadeau</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόμα, ατος (τὸ)</b> don, PLAT. <i>Def. 415</i> b ; PLUT. <i>M. 182</i> e, <i>531</i> f ; NT. <i>Matth. 7, 11, etc</i>.<br><span><b>Étym</b>. δίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δομα - δόμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> se réfère à l'action de donner ou à la chose donnée, ex : une dose de médicament.\n<br><br> se réfère à un don qui n'est cependant pas toujours gratuit ni totalement dépourvu d'une notion de récompense.\n<br><br> diffère de  en dénotant un don qui est gratuit, le cadeau d'un souverain.\n<br><br> est ce que Dieu confère, en tant que possesseur de toutes choses.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1391":"<h1>doxa</h1>\n<p>Strong n° 1391 <i>Prononciation [dox'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>opinion, jugement, vue</li>\n<li>estimation, ce qui est mauvais ou bon chez quelqu'un\n<ol type=\"a\">\n<li>dans le N.T toujours une bonne opinion, résultant en louange, honneur et gloire</li>\n</ol>\n</li>\n<li>splendeur, éclat\n<ol type=\"a\">\n<li>de la lune, du soleil, des étoiles</li>\n<li>magnificence, excellence, prééminence, dignité, grâce</li>\n<li>majesté\n<ol>\n<li>une chose appartenant à Dieu</li>\n<li>une chose appartenant à Christ</li>\n<li>des anges</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>la condition la plus glorieuse, l'état le plus élevé</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόξα, ης (ἡ) :<br>   I</b> opinion, <i>d’où :</i><br><b>      1</b> jugement, avis, sentiment : δόξης ἁμαρτία, THC. <i>1, 32,</i> erreur de notre jugement ; κατά γε τὴν ἐμὴν δόξαν, PLAT. <i>Pol. 260</i> b ; ἐμὰν δόξαν, PD. <i>N. 11, 30,</i> à mon avis ; δόξῃ γοῦν ἐμῇ, SOPH. <i>Tr. 718,</i> à mon avis du moins ; ὡς ἡ ἐμὴ δόξα, PLAT. <i>Rsp. 435</i> d, comme c’est mon avis ;<br><b>      2</b> ce à quoi l’on s’attend, ce que l’on croit possible, croyance : ψευδεῖς καὶ ἀληθεῖς δόξαι, PLAT. <i>Phil. 36</i> c, croyances fausses et croyances justes ; δόξαν παρέχειν τινί, <i>avec l’inf. fut</i>. XÉN. <i>Hell. 7, 5, 21,</i> faire supposer à qqn que ; παρὰ δόξαν, HDT. <i>1, 79, 8, 4 ;</i> PLAT. <i>Phæd. 95</i> a, <i>etc</i>. contre toute attente ; πεσέειν ἀπὸ τῆς δόξης, HDT. <i>7, 203,</i> rabattre de ses espérances ; οὐκ ἀπὸ δόξης, IL. <i>10, 324 ;</i> OD. <i>11, 343,</i> inférieur à ce qu’on attend (de qqn) ;<br><b>      3</b> <i>particul</i>. croyance philosophique, doctrine, <i>p. opp. à la</i> « vérité pure (ἀλήθεια) », PLAT. <i>Conv. 218</i> e ; ANT. <i>121, 20, etc. ; à la</i> « connaissance acquise (γνῶσις) », PLAT. <i>Rsp. 478</i> c ; <i>à la</i> « science (ἐπιστήμη) », PLAT. <i>Gorg. 187</i> b ; <i>Rsp. 506</i> c ; αἱ κύριαι δόξαι, EPIC. (CIC. <i>Fin. 2, 7</i>), les dogmes principaux, <i>càd</i>. les principes fondamentaux d’une doctrine ; αἱ κοιναὶ δ. ARSTT. <i>Metaph. 2, 2, 16,</i> opinions généralement admises, axiomes ;<br><b>      4</b> <i>p. suite,</i> opinion sans fondement, pure imagination, conjecture, ESCHL. <i>Ag. 275 ;</i> δόξῃ ἐπίστασθαι, HDT. <i>8, 132,</i> savoir par conjecture, <i>càd</i>. imaginer, supposer (à tort) ; <i>d’où au plur</i>. δόξαι, imaginations, rêveries, ESCHL. <i>Ch. 1053 ; joint à</i> φαντασίαι, PLAT. <i>Theæt. 161</i> e ; <i>au sg. en parl. d’un songe,</i> EUR. <i>Rhes. 780 ;</i><br><b>   II</b> bonne <i>ou</i> mauvaise opinion sur qqn, réputation : δόξαν ἔχειν, ISOCR. <i>80</i> a ; φέρεσθαι, THC. <i>2, 11 ;</i> λαϐεῖν, EUR. <i>Hel. 847,</i> avoir <i>ou</i> acquérir de la réputation ; δόξαν ἔχειν εὐψυχίας, EUR. <i>H.f. 157 ; ou</i> ἐπὶ σοφίᾳ, ISOCR. <i>291</i> c, avoir une réputation de magnanimité, de sagesse ; ἐπὶ σωφροσύνῃ δόξαν ποιεῖσθαι, POL. <i>35, 4, 8 ; ou</i> ἐν ταῖς ναυτικαῖς δυνάμεσι, DS. <i>11, 39,</i> se faire <i>ou</i> acquérir une réputation de modération <i>ou</i> de supériorité dans les choses de marine ; δόξαν αὑτῷ παρασκευάζειν εἰς δικαιοσύνην, PLAT. <i>Rsp. 361</i> a, s’assurer une réputation de justice ; <i>avec une conj</i>. δόξαν ἔχουσιν ὥς εἰσι θαυμαστοί, DÉM. <i>23, 2,</i> ils ont la réputation d’être admirables, <i>ou direct. avec l’inf</i>. δόξαν εἶχον ἄμαχοι εἶναι, PLAT. <i>Menex. 241</i> b, ils avaient la réputation d’être invincibles ; <i>p. suite, abs</i>. gloire, ISOCR. <i>111</i> d ; <i>joint à</i> φήμη <i>et à</i> μνήμη, ISOCR. <i>80</i> a ; δόξαν ἢ τίμην, gloire ou honneur = <i>lat</i>. honorem, PLUT. <i>M. 266</i> f ; δόξαν ἀντὶ τοῦ ζῆν αἱρεῖσθαι, DÉM. <i>22, 21,</i> préférer la gloire à la vie ; <i>au plur</i>. ESCHL. <i>Eum. 351 ; rar. en mauv. part :</i> δ. αἰσχρά, φαύλη, DÉM. <i>460, 4 ; 1475, 23,</i> mauvaise réputation ; δόξαν ἔχειν ἀδικίας, PLAT. <i>Rsp. 316</i> a, avoir une réputation d’injustice ; κληρονομεῖν τὴν ἐπ' ἀσεϐείᾳ δόξαν, POL. <i>15, 22, 3,</i> hériter de la réputation d’impiété (de qqn) ; <i>postér. au plur</i>. δόξαι, des personnes illustres, des célébrités, NT. <i>2Petr. 2, 10 ; Jud. 8</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *deḱ-, recevoir, <i>cf</i>. δοκέω <i>ou pré-grec</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοξα - δόξα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n167 fois dans 150 versets de 23 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (3)</li>\n<li>Luc (13)</li>\n<li>Jean (19)</li>\n<li>Actes (4)</li>\n<li>Romains (16)</li>\n<li>1 Corinthiens (12)</li>\n<li>2 Corinthiens (19)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (8)</li>\n<li>Philippiens (6)</li>\n<li>Colossiens (4)</li>\n<li>1 Thessaloniciens (3)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (3)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (7)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (10)</li>\n<li>2 Pierre (5)</li>\n<li>Jude (3)</li>\n<li>Apocalypse (17)</li>\n</ul>\n</td></tr>\n</table>","G1392":"<h1>doxazo</h1>\n<p>Strong n° 1392 <i>Prononciation [dox-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>penser, supposer, être d'avis</li>\n<li>louer, vanter, magnifier, célébrer</li>\n<li>rendre les honneurs</li>\n<li>être glorieux, vêtu de splendeur, transfigurer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δοξάζω</b> <span>(<i>f</i>. άσω)</span><br><b>      1</b> avoir une opinion, croire, penser, juger : δ. ψευδῆ, PLAT. <i>Theæt. 189</i> c, avoir des opinions fausses ; <i>avec un acc. de m. sign</i>. δ. δόξας, PLAT. <i>Crit. 46</i> d, avoir des opinions ; δ. περί τινος, PLAT. <i>Gorg. 461</i> b, avoir une opinion sur qqe ch. ; οὐ κακῶς δ. PLAT. <i>Rsp. 327</i> c, n’avoir pas tort de croire que, <i>etc</i>. ἐπὶ πλέον τι αὑτὸν δ. THC. <i>3, 45,</i> avoir de soi-même une trop haute opinion ; <i>abs</i>. peser les opinions, délibérer, THC. <i>1, 120 ; p. opp. à</i> γιγνώσκω, PLAT. <i>Rsp. 476</i> d ; <i>à</i> εἰδέναι, XÉN. <i>Mem. 3, 9, 6 ; à</i> ἐπίσταμαι, ARSTT. <i>An. post. 1, 33 (cf</i>. δ. ἄνευ ἐπιστήμης, PLAT. <i>Theæt. 201</i> c, avoir une opinion sans savoir de science sûre) ; <i>au pass</i>. τὰ δοξαζόμενα, PLAT. <i>Pol. 278</i> b, les choses sur lesquelles on a une opinion ;<br><b>      2</b> se figurer, s’imaginer, supposer : πῶς ταῦτ' ἀληθῆ δοξάσω ; ESCHL. <i>Ch. 844,</i> comment pourrai-je savoir que cela est vrai ? <i>avec une prop. inf</i>. ταῦτ' ἔχειν δοξάζομεν, ESCHL. <i>Ag. 673,</i> nous supposons que cela est (<i>cf</i>. EUR. <i>Suppl. 1043) ; avec un part</i>. δοξάσει ἀκούων, ESCHL. <i>Suppl. 60,</i> il s’imaginera qu’il entend ; <i>au pass</i>. δοξάζομαι ἄδικος, PLAT. <i>Rsp. 363</i> e, on s’imagine que je suis injuste ;<br><b>      3</b> glorifier, célébrer, SPT. <i>Ex. 15, 1, 2 ; 1Reg. 2, 30 ; 15, 30 ;</i> ἐπ' ἀρετῇ δεδοξασμένος, POL. <i>6, 53, 10,</i> célèbre pour sa vertu ; <i>ou avec</i> ἐν : ἐν παιδείᾳ καὶ συνέσει δεδοξασμένος, DS. <i>16, 82,</i> célèbre pour son savoir et son intelligence.<br><span><b>Étym</b>. δόξα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοξαζω - δοξάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n62 fois dans 53 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (1)</li>\n<li>Luc (9)</li>\n<li>Jean (24)</li>\n<li>Actes (5)</li>\n<li>Romains (5)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (3)</li>\n<li>Galates (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (4)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G1393":"<h1>Dorkas</h1>\n<p>Strong n° 1393 <i>Prononciation [dor-kas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Dorcas = « gazelle »\n<ol><li>nom d'une femme que Pierre ressuscita</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Δορκάς, άδος (ἡ)</b> Dorkas (<i>litt</i>. Gazelle) <i>n. de f</i>. LUC. <i>D. mer. 9 ;</i> ANTH. <i>5, 182, 187 ;</i> NT. <i>Ap. 9, 36, 39</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. -άς, LUC. <i>D. mer. 9, 3</i>.<br><span><b>Étym</b>. δορκάς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Δορκας - Δορκάς</font>\n<br><br>racine primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G1394":"<h1>dosis</h1>\n<p>Strong n° 1394 <i>Prononciation [dos'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une offrande</li>\n<li>un don, ce qui est donné</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δόσις, εως (ἡ) :<br>A</b> <i>act</i>. action de donner, HDT. <i>1, 61 ;</i> THC. <i>1, 143 ; p. opp. à</i> αἴτησις, PLAT. <i>Euthyphr. 14</i> c ; <i>à</i> λῆψις, ARSTT. <i>Nic. 2, 7, 4 ;</i> δόσις καὶ λῆψις, ARR. <i>Epict. 2, 9, 12 ;</i> SPT. <i>Sir. 42, 7 ;</i> NT. <i>Phil. 4, 15,</i> action de donner et de recevoir, échange, trafic, commerce ;<br><b>B</b> <i>pass</i>. ce qui est donné, ce qu’on donne :<br><b>   I</b> don, largesse, IL. <i>10, 213 ;</i> OD. <i>6, 208, etc. ;</i> HDT. <i>1, 90, etc. ;</i> PLAT. <i>Phil. 16</i> c ; <i>particul</i>. donation par testament ; κατὰ δόσιν, IS. <i>47, 25,</i> fortune acquise par donation testamentaire (<i>p. opp. à</i> κατὰ γένος, par droit de naissance) ; <i>cf</i>. ISOCR. <i>393</i> c, <i>394</i> b ; <i>à Rome,</i> don au peuple, HDN <i>6, 8, 17 ; par suite :</i><br><b>      1</b> portion, part, PLUT. <i>Arat. 14 ;</i> SPT. <i>Gen. 47, 22 ;</i><br><b>      2</b> portion, dose, <i>t. de méd</i>. DIOSC. <i>2, 202 ;</i> RUF. (ORIB. <i>2, 277 B.-Dar</i>.) ; ARÉT. <i>93, 119 ;</i> A. TR. <i>91 ;</i><br><b>      3</b> <i>fig</i>. part, lot, sort (de chaque homme) JAMBL. <i>Myst. 9, 3 ;</i><br><b>   II</b> ce qui peut être donné : τοῦ θεοῦ δόσις, SOPH. <i>O.R. 1518,</i> une chose qu’il n’appartient qu’au dieu de te donner ;<br><b>C</b> <i>au sens réfléchi,</i> action de se donner, <i>d’où</i> action de donner son soin, son attention : δόσιν ποιεῖσθαι, DH. <i>6, 1008, 9 ; 1103, 5, 1112, 9 Reiske,</i> se préoccuper de qqe ch., accorder son attention à qqe ch.<br><span><b>Étym</b>. δίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοσις - δόσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> se réfère à l'action de donner ou à la chose donnée, ex : une dose de médicament.\n<br><br> se réfère à un don qui n'est cependant pas toujours gratuit ni totalement dépourvu d'une notion de récompense.\n<br><br> diffère de  en dénotant un don qui est gratuit, le cadeau d'un souverain.\n<br><br> est ce que Dieu confère, en tant que possesseur de toutes choses.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (1)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G1395":"<h1>dotes</h1>\n<p>Strong n° 1395 <i>Prononciation [dot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un donateur, celui qui accorde, qui distribue</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δότης, ου (ὁ)</b> <i>c</i>. δοτήρ NT. <i>2Cor. 9, 7</i>.<br><span><b>Étym</b>. δίδωμι.</span><br><br>\n<b>δοτήρ, ῆρος (ὁ) :<br>      1</b> celui qui donne, qui distribue, <i>gén</i>. IL. <i>19, 44 ;</i><br><b>      2</b> celui qui fait don de, <i>gén</i>. HH. <i>Mars 9 ; avec double rég. :</i> δ. τίνος τινι, ESCHL. <i>Pr. 613 ;</i> DH. <i>7, 72,</i> celui qui donne qqe ch. à qqn ;<br><b>      3</b> qui est la cause de, qui donne (la mort) <i>gén., en parl. d’un trait,</i> HÉS. <i>Sc. 131</i>.<br><span><b>Étym</b>. δίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δοτης - δότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1396":"<h1>doulagogeo</h1>\n<p>Strong n° 1396 <i>Prononciation [doo-lag-ogue-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>emmener en esclavage, déclarer quelqu'un son esclave</li>\n<li>faire un esclave, et le traiter en esclave (sévèrement), sujet à une stricte et ferme discipline, asservir, tenir en bride</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δουλαγωγέω-ῶ</b> <span>[ᾰ]</span><br><b>      1</b> réduire en esclavage, asservir, <i>acc</i>. DS. <i>12, 24 ; fig</i>. LGN <i>44, 6 ;</i> CHARIT. <i>2, 7 ;</i><br><b>      2</b> traiter comme un esclave, <i>càd</i>. durement, mortifier (les passions) <i>acc</i>. NT. <i>1Cor. 9, 27</i>.<br><span><b>Étym</b>. *δουλαγωγός, <i>de</i> δοῦλος, ἀγωγή.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλαγωγεω - δουλαγωγέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G1397":"<h1>douleia</h1>\n<p>Strong n° 1397 <i>Prononciation [doo-li'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>esclavage, servitude, la condition d'un esclave</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δουλεία, ας (ἡ) :<br>   I. 1</b> esclavage, servitude, ESCHL. <i>Sept. 253 ; p. opp. à</i> ἐλευθερία, PLAT. <i>Rsp. 584</i> a ; <i>joint à</i> ὑπηρεσία, AR. <i>Vesp. 602 ;</i> δουλείας ζυγά, SOPH. <i>Aj. 944,</i> le joug de la servitude ;<br><b>      2</b> soumission, THC. <i>1, 8 ; particul</i>. dépendance des États sujets d’Athènes, THC. <i>5, 9 ;</i><br><b>   II</b> <i>collect</i>. les esclaves, THC. <i>5, 23 ;</i> PLAT. <i>Leg. 776</i> c ; <i>au plur</i>. EUR. <i>Bacch. 803 ;</i> ARSTT. <i>Pol. 2, 5, 22</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Poét. par nécess. métrique</i> δουλία, PD. <i>P. 1, 147. — Ion</i>. δουληΐη, HDT. <i>6, 12 ;</i> ANTH. <i>13, 4</i>.<br><span><b>Étym</b>. δουλεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλεια - δουλεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Galates (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G1398":"<h1>douleuo</h1>\n<p>Strong n° 1398 <i>Prononciation [dool-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un esclave, servir, faire le service\n<ol type=\"a\">\n<li>d'une nation soumise à une autre nation</li>\n</ol>\n</li>\n<li>métaph : obéir à, se soumettre\n<ol type=\"a\">\n<li>bon sens : avoir de l'obéissance</li>\n<li>mauvais sens : ceux qui deviennent esclaves d'un pouvoir vil, se donner, se vendre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δουλεύω</b> <span>(<i>impf</i>. ἐδούλευον, <i>f</i>. δουλεύσω, <i>ao</i>. ἐδούλευσα, <i>pf. inus</i>.)</span><br><b>      1</b> être esclave, <i>abs</i>. THC. <i>7, 85 ;</i> EUR. <i>Tr. 964, etc. ; p. opp. à</i> ἄρχειν, ESCHL. <i>Pr. 927 ; joint à</i> ἄρχεσθαι, PLAT. <i>Phæd. 79</i> e ; <i>ou à</i> ὑπηρετεῖν, PLAT. <i>Euthyd. 282</i> b ; δουλείαν <i>ou</i> δουλείας δ. XÉN. <i>Mem. 3, 12, 2 ;</i> PLAT. <i>Leg. 698</i> c, <i>Conv. 183</i> a, <i>184</i> b, <i>m. sign. ; avec un dat</i>. δ. τινί, AND. <i>18, 8 ;</i> EUR. <i>Andr. 928,</i> être esclave de qqn ; <i>fig</i>. δ. νόμοις, PLAT. <i>Leg. 698</i> c, <i>700</i> a ; ARSTT. <i>Pol. 5, 12 ;</i> γαστρί, XÉN. <i>Mem. 1, 6, 8 ;</i> ταῖς ἡδοναῖς, ISOCR. <i>20</i> d ; PLAT. <i>Phædr. 238</i> e, <i>etc</i>. être esclave des lois, de son ventre, des plaisirs ; καιρῷ, ANTH. <i>9, 441,</i> se plier aux circonstances ;<br><b>      2</b> travailler à gages, faire un travail mercenaire, DL. <i>2, 19</i>.<br><span><b>Étym</b>. δοῦλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλευω - δουλεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 23 versets de 12 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (3)</li>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Romains (7)</li>\n<li>Galates (5)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G1399":"<h1>doule</h1>\n<p>Strong n° 1399 <i>Prononciation [doo'-lay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une esclave féminine, servante</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>δούλη, ης (ἡ)</b> femme esclave, IL. <i>3, 409 ;</i> OD. <i>4, 12 ;</i> ESCHL. <i>Ag. 1326 ;</i> XÉN. <i>Cyr. 5, 1, 4 ;</i> PLAT. <i>Rsp. 395</i> e, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. δούλα, EUR. <i>I.T. 132</i>.<br><span><b>Étym</b>. δοῦλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">δουλη - δούλη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>"};
